// Bouwt rubric-vragen rechtstreeks uit de leerdoelen van de challenge.
function rubricUitLeerdoelen(leerdoelen,niveau){
  const schaal=["Nog niet","Een beetje","Grotendeels","Helemaal — ik kan het met een voorbeeld laten zien"];
  // "Ik kan beschrijven hoe X" → "beschrijven hoe X", met mijn→je (vraag aan de leerling)
  const kern=(ld)=>String(ld)
    .replace(/^Ik kan\s*/i,"")
    .replace(/\.$/,"")
    .replace(/\bmijn\b/gi,"je")
    .replace(/\bmij\b/gi,"jou")
    .trim();
  // Vraagvormen die altijd correct werken met "kun je + kern"
  const vormen=[
    (k)=>`Kun je ${k}?`,
    (k)=>`Hoe goed kun je ${k}?`,
    (k)=>`Kun je inmiddels ${k}?`,
    (k)=>`In welke mate kun je ${k}?`,
  ];
  const vragen=(leerdoelen||[]).map((ld,i)=>({
    v:vormen[i%vormen.length](kern(ld)),
    a:[...schaal],
    leerdoel:ld,
  }));
  vragen.push({
    v:"Heb je de uitdaging, inclusief de werkvorm, echt uitgevoerd?",
    a:["Nee, niet gedaan.","Voor een deel.","Ja, helemaal.","Ja, en ik ontdekte iets nieuws."],
    leerdoel:null,
  });
  return vragen;
}

function berekenScore(antwoorden) {
  if (!antwoorden || !antwoorden.length) return 0;
  const som = antwoorden.reduce((s, a) => s + a, 0);
  return Math.round((som / (antwoorden.length * 4)) * 100);
}


