const PLATINUM_MIN_LEEFTIJD = 15;

// Zet oude/onbekende plannen om naar het nieuwe model, zodat bestaande accounts blijven werken.
function licentieVan(g){
  const key = g && (g.licentieType || g.licentie);
  if(key && LICENTIES[key]) return LICENTIES[key];
  // Migratie van het oude plan-model: free→demo, plus/pro→neo.
  const oud = g && g.plan;
  if(oud==="plus"||oud==="pro") return LICENTIES.neo;
  return LICENTIES.demo;
}

// Demo-verloop: op basis van demoStart (ISO). Retourneert {actief, verlopen, resterendeDagen}.
function demoStatus(g){
  if(!g||licentieVan(g).id!=="demo") return {actief:true, verlopen:false, resterendeDagen:Infinity};
  const start = g.demoStart ? new Date(g.demoStart).getTime() : null;
  if(!start) return {actief:true, verlopen:false, resterendeDagen:DEMO_DAGEN};
  const verstreken = (Date.now()-start)/(1000*60*60*24);
  const rest = Math.max(0, DEMO_DAGEN - verstreken);
  return { actief: rest>0, verlopen: rest<=0, resterendeDagen: Math.ceil(rest) };
}

// ── Centrale capability-checks. Elk component vraagt HIER of iets mag — nooit losse plan-checks. ──
function magFunctie(g, sleutel){
  const lic = licentieVan(g);
  // Verlopen demo = geen enkele functie meer (behalve de upgrade-flow zelf).
  if(lic.id==="demo" && demoStatus(g).verlopen) return false;
  return !!lic.functies[sleutel];
}
function magRoute(g, route){
  const lic = licentieVan(g);
  if(lic.id==="demo" && demoStatus(g).verlopen) return false;
  return lic.routes.includes(route);
}
function magThema(g, themaKey){
  const lic = licentieVan(g);
  if(lic.id==="demo" && demoStatus(g).verlopen) return false;
  return lic.themas==="*" || (Array.isArray(lic.themas) && lic.themas.includes(themaKey));
}
// Niveau-toegang = commercieel (licentie) EN leeftijd (Platinum ≥15). Dit is de énige plek waar
// leeftijd de niveaubeschikbaarheid raakt; het groeiniveau zelf wordt hier nooit gewijzigd.
function magNiveau(g, niveauKey){
  const lic = licentieVan(g);
  if(lic.id==="demo" && demoStatus(g).verlopen) return false;
  if(!lic.niveaus.includes(niveauKey)) return false;
  if(niveauKey==="Platinum"){
    const leeftijd = (g && g.leeftijd) || 0;
    if(leeftijd < PLATINUM_MIN_LEEFTIJD) return false;
  }
  return true;
}
function magModule(g, moduleKey){ const lic=licentieVan(g); return !!(lic.modules&&lic.modules[moduleKey]); }
function beschikbareNiveaus(g){ return ["Bronze","Silver","Gold","Platinum"].filter(n=>magNiveau(g,n)); }

// Compat-laag: oude code las planLim(g).niveaus / .schoolbeheer / .klassen / .leerlingen / .label.
// We laten die interface bestaan maar voeden hem vanuit de centrale License Engine.
const planLim=(g)=>{
  const lic=licentieVan(g);
  return {
    label: lic.label,
    klassen: lic.klassen,
    leerlingen: lic.leerlingen,
    niveaus: beschikbareNiveaus(g),
    schoolbeheer: magFunctie(g,"schoolbeheer"),
  };
};
const planNaam=(g)=> licentieVan(g).label;
