/* ═══════════════════ TAALPROFIEL (leeftijd · leerjaar · onderwijsniveau) ═══════════════════ */
function taalprofiel(leeftijd,klas){
  const k=(klas||"").toLowerCase();
  let onderwijs="havo";
  if(/vmbo|mavo|vbo|kader|basis|beroeps/.test(k))onderwijs="vmbo";
  else if(/vwo|gymnasium|atheneum/.test(k))onderwijs="vwo";
  const lt=Number(leeftijd)||14;
  // niveau: 1 = eenvoudig/kort, 2 = gemiddeld, 3 = rijk/uitgebreid
  let niveau=2;
  if(onderwijs==="vmbo"||lt<=13)niveau=1;
  if(onderwijs==="vwo"&&lt>=15)niveau=3;
  return {onderwijs,leeftijd:lt,niveau};
}
// kiest de juiste taalvariant op basis van het profiel (1=kort, 2=gemiddeld, 3=rijk)
function tp(tprof,kort,gemiddeld,rijk){
  return tprof.niveau<=1?kort:(tprof.niveau>=3?rijk:gemiddeld);
}

