  creatief:{label:"Creëren & maken",activering:"activeert verbeelding en productgericht werken",sociaal:"individueel of groep",bloom:"Creëren",leerstrategie:"Dual coding & constructie",wanneer:"als een tastbaar eindproduct de stof laat landen",kleur:"#B23A1C"},
  spelgericht:{label:"Spel & competitie",activering:"activeert via spelplezier, herhaling en beloning",sociaal:"duo of groep",bloom:"Toepassen",leerstrategie:"Retrieval practice (gamified)",wanneer:"als oefenen leuk en herhaalbaar moet zijn",kleur:"#C9971F"},
