  creatief:{voorbeelden:["een verzorgd ontwerp of prototype met korte toelichting","een strip of poster die één helder inzicht overbrengt","een moodboard met uitleg van je keuzes"],kenmerken:["de boodschap is in één oogopslag helder","vorm en inhoud versterken elkaar","het is af en verzorgd"]},
  spelgericht:{voorbeelden:["een zelfgemaakt spel met heldere regels en 8+ kaarten","een escape met 3 sloten die logisch in elkaar zitten"],kenmerken:["het is echt speelbaar","de inhoud klopt en daagt uit","de regels zijn duidelijk"]},
  actief:{voorbeelden:["een voor-en-na-kaart van wat je in de praktijk deed","een ingevuld observatie- of testformulier met je conclusie"],kenmerken:["je deed het echt, niet alleen op papier","je legde het resultaat vast","je trekt een conclusie uit wat je zag"]},
