// Bepaalt product + bewijs voor een werkvorm (eigen entry, anders standaard op type/categorie).
function werkvormProduct(werkvorm){
  if(!werkvorm)return {product:"een ingevulde opdrachtkaart met je uitwerking",bewijs:"Maak een foto van je opdrachtkaart."};
  const eigen=WERKVORM_PRODUCT[werkvorm.naam];
  if(eigen)return eigen;
  const cat=werkvorm.categorie||werkvorm.type||"";
  const standaard={
    creatief:{product:"een gemaakt werk (ontwerp, strip of poster)",bewijs:"Maak een foto van je werk."},
    visueel:{product:"een schema, mindmap of moodboard",bewijs:"Maak een foto van je schema."},
    spelgericht:{product:"een zelfgemaakt spel of ingevulde scorekaart",bewijs:"Maak een foto van je spel of scorekaart."},
    denken:{product:"een ingevulde beslisboom of tabel met je onderbouwing",bewijs:"Laat je uitwerking zien."},
    sociaal:{product:"een ingevulde interviewkaart of gesprekskaart",bewijs:"Laat je kaart zien."},
    onderzoeksgericht:{product:"een onderzoekkaart met je conclusie",bewijs:"Laat je onderzoekkaart zien."},
    reflectief:{product:"een reflectiekaart met één patroon en één actie",bewijs:"Laat je reflectiekaart zien."},
    reflecteren:{product:"een reflectiekaart met één inzicht en één actie",bewijs:"Laat je reflectiekaart zien."},
    coachen:{product:"een ingevulde feedback- of gesprekskaart",bewijs:"Laat je kaart zien."},
    gedrag:{product:"een ingevulde weektracker of actiekaart",bewijs:"Maak een foto van je tracker."},
    prestatie:{product:"een ingevuld plan of routinekaart",bewijs:"Laat je plan zien."},
    welzijn:{product:"een ingevulde reflectie- of routinekaart",bewijs:"Laat je kaart zien."},
    actief:{product:"een zichtbaar resultaat van je uitvoering",bewijs:"Leg je resultaat vast met een foto."},
    praktisch:{product:"een ingevulde stappenkaart of resultaatkaart van wat je deed",bewijs:"Maak een foto van je kaart of resultaat."},
    cognitief:{product:"een ingevulde denkkaart (schema, woordweb of beslisboom)",bewijs:"Maak een foto van je denkkaart."},
    creatief_default:{product:"een gemaakt ontwerp of kaart",bewijs:"Maak een foto van je werk."},
  }[cat];
  return standaard||{product:"een ingevulde opdrachtkaart met je uitwerking",bewijs:"Maak een foto van je opdrachtkaart."};
}
