// Voor leer-/studiethema's: trek een concrete studietechniek uit de kennisbank.
function studietechniekVoor(thema){
  if(thema==="studie"||thema==="ef")return STUDIETECHNIEKEN[Math.floor(Math.random()*STUDIETECHNIEKEN.length)];
  return null;
}
function kies(arr,n){const c=[...arr];const r=[];while(r.length<n&&c.length){r.push(c.splice(Math.floor(Math.random()*c.length),1)[0]);}return r;}
function hoofdletter(s){return s?s.charAt(0).toUpperCase()+s.slice(1):s;}

// Leerdoelen volgens Bloom, duidelijk gesplitst: observeerbaar werkwoord + inhoud + context.
function bouwLeerdoelen({sub,niveau,sp,tprof,route}){
  const ond=sub.toLowerCase();
  const isTop=!route||route==="topsport";
  const ctx = isTop ? (sp==="je sport"?"in mijn sport en op school":`in ${sp} en op school`)
            : route==="groei" ? "in mijn dagelijks leven en op school"
            : "bij mijn talent en interesses";
  const nieuweSituatie = isTop ? "in een nieuwe situatie binnen sport of school"
            : route==="groei" ? "in een nieuwe situatie in mijn dagelijks leven of op school"
            : "bij een nieuw project of een nieuwe interesse";
  const sjablonen={
    Bronze:[
      `Ik kan de rol van ${ond} ${ctx} beschrijven.`,
      `Ik kan herkennen welke momenten voor mij het belangrijkst zijn.`,
      `Ik kan uitleggen waarom dit mijn ${isTop?"prestaties":"ontwikkeling"} beïnvloedt.`,
    ],
    Silver:[
      `Ik kan een aanpak oefenen om ${ond} ${ctx} te verbeteren.`,
      `Ik kan deze aanpak uitvoeren in mijn eigen weekritme.`,
      `Ik kan analyseren welke gewoonte voor mij het beste werkt.`,
    ],
    Gold:[
      `Ik kan evalueren welke factoren mijn ${ond} ${ctx} beïnvloeden.`,
      `Ik kan een verbeterde aanpak creëren voor situaties die spanning geven.`,
      `Ik kan zelfstandig oplossen wat mijn voortgang in de weg staat.`,
    ],
    Platinum:[
      `Ik kan iemand anders helpen op het gebied van ${ond}.`,
      `Ik kan mijn aanpak toepassen ${nieuweSituatie}.`,
      `Ik kan eigenaarschap nemen over mijn ontwikkeling en die onderbouwd bijsturen.`,
    ],
  };
  let doelen=(sjablonen[niveau]||sjablonen.Bronze).map(hoofdletter);
  // Adaptief formuleren (bron: "Formuleren op vorm", generiek vs specifiek vs hybride):
  // jonger/vmbo => specifieker (concrete houvast); ouder/vwo => transfergericht (generiek) derde doel.
  if(tprof&&tprof.niveau>=3){
    doelen[2]=doelen[2].replace(/\.$/,"")+" en dit ook in andere situaties toepassen.";
  }
  return doelen;
}

// Oriëntatie: voorkennis activeren / eerst onderzoeken (Vygotsky ZPD, constructivisme).
function bouwOrientatie({sub,niveau,sp,tprof,thema}){
  const techniek=studietechniekVoor(thema);
  const ond=sub.toLowerCase();
  const perNiveau={
    Bronze:tp(tprof,
      `Zoek eerst uit wat ${ond} precies betekent. Vraag het na bij je coach of zoek het op.`,
      `Onderzoek eerst wat ${ond} inhoudt: zoek een korte uitleg op of vraag het je coach, en noteer in eigen woorden wat het betekent.`,
      `Verken eerst het onderwerp: zoek een betrouwbare uitleg over ${ond}, leg die in je eigen woorden uit en bedenk waar het in ${sp} terugkomt.`),
    Silver:`Onderzoek voordat je begint hoe ${ond} bij anderen werkt: vraag een teamgenoot hoe die het aanpakt en noteer één bruikbaar idee.`,
    Gold:`Verzamel eerst informatie: analyseer een eigen voorbeeld én bekijk hoe een topsporter met ${ond} omgaat. Noteer de verschillen.`,
    Platinum:`Doe vooronderzoek: verzamel inzichten uit minstens twee bronnen (bijv. een coach, een teamgenoot en een artikel) over ${ond} en bepaal wat voor jouw situatie relevant is.`,
  };
  let uitleg=perNiveau[niveau]||perNiveau.Bronze;
  if(techniek)uitleg+=` Tip — gebruik de techniek "${techniek.naam}": ${techniek.beschrijving}`;
  return { titel:"Oriëntatie — onderzoek dit eerst", uitleg };
}

// Uitdaging: 4 tot 6 substappen die opbouwen in moeilijkheid naar de activerende werkvorm
// (Deliberate Practice: gerichte oefening met oplopende complexiteit en feedback).
function bouwSubstappen({sub,niveau,sp,sit,werkvorm,tprof}){
  const ond=sub.toLowerCase();
  const wp=werkvormProduct(werkvorm);
  const wvNaam=(werkvorm&&werkvorm.naam)||"werkvorm";
  const wvUitleg=(werkvorm&&werkvorm.beschrijving)||`Werk ${ond} concreet uit.`;
  // Concrete, controleerbare opbouw die naar het tastbare product toewerkt.
  // Elke stap benoemt exact wát de leerling doet en maakt — geen "leg in eigen woorden uit" als losse stap.
  const reeks={
    Bronze:[
      {titel:"Verzamel 3 voorbeelden", uitleg:`Schrijf 3 concrete voorbeelden op van ${ond} die jij deze week herkent — bij jezelf, op school of om je heen.`},
      {titel:"Kies je 3 kernwoorden", uitleg:`Kies uit je voorbeelden 3 kernwoorden die het beste bij ${ond} passen. Deze gebruik je zo in je ${wvNaam.toLowerCase()}.`},
      {titel:`Maak je ${wvNaam.toLowerCase()}`, uitleg:`${wvUitleg} Gebruik je 3 kernwoorden. Zo ontstaat ${wp.product}.`},
      {titel:"Kies één actie", uitleg:`Kies op basis van wat je maakte één concreet ding dat je morgen gaat proberen, en schrijf het op je product.`},
    ],
    Silver:[
      {titel:"Breng je startpunt in kaart", uitleg:sit?`Noteer kort wat er nu speelt: "${sit}". Wanneer en hoe vaak gebeurt dit?`:`Noteer 3 momenten waarop ${ond} bij jou een rol speelt in een gewone week.`},
      {titel:"Verzamel je materiaal", uitleg:`Zoek 4 begrippen, situaties of voorbeelden rond ${ond} bij elkaar. Dit is de inhoud voor je ${wvNaam.toLowerCase()}.`},
      {titel:`Maak je ${wvNaam.toLowerCase()}`, uitleg:`${wvUitleg} Zo ontstaat ${wp.product}.`},
      {titel:"Test je product", uitleg:`Probeer je ${wvNaam.toLowerCase()} uit met een klasgenoot of familielid, of loop het zelf hardop door. Noteer wat goed werkte.`},
      {titel:"Verbeter één ding", uitleg:`Pas op basis van de test één ding aan je product aan zodat het duidelijker of leuker wordt.`},
    ],
    Gold:[
      {titel:"Analyseer een echt moment", uitleg:`Kies een concreet moment rond ${ond} en bepaal welke 2–3 factoren daarin het verschil maakten.`},
      {titel:"Ontwerp de inhoud", uitleg:`Bedenk de opzet van je ${wvNaam.toLowerCase()}: welke vragen, kaarten, vakjes of onderdelen komen erin? Maak eerst een korte schets.`},
      {titel:`Maak je ${wvNaam.toLowerCase()}`, uitleg:`${wvUitleg} Werk het volledig uit tot ${wp.product}.`},
      {titel:"Test in de praktijk", uitleg:`Voer je ${wvNaam.toLowerCase()} echt uit of speel het met iemand. Noteer wat werkte en wat niet.`},
      {titel:"Verbeter en onderbouw", uitleg:`Verbeter je product op één punt en leg in 2 zinnen uit waarom die keuze beter is.`},
    ],
    Platinum:[
      {titel:"Breng je patroon in kaart", uitleg:`Breng een week lang jouw patroon rond ${ond} in kaart met korte dagnotities.`},
      {titel:"Ontwerp je opzet", uitleg:`Ontwerp de structuur van je ${wvNaam.toLowerCase()}: onderdelen, regels of vragen, en hoe het aansluit op ${sp==="je sport"?"school én je talent":sp}.`},
      {titel:`Maak je ${wvNaam.toLowerCase()}`, uitleg:`${wvUitleg} Werk het professioneel uit tot ${wp.product}, haalbaar naast school.`},
      {titel:"Test en verzamel bewijs", uitleg:`Voer je product meerdere keren uit, verzamel bewijs van wat het oplevert en noteer je resultaten.`},
      {titel:"Deel en verwerk feedback", uitleg:`Laat je product aan een klasgenoot of mentor zien, vraag gericht om feedback en verwerk één verbetering.`},
    ],
  };
  return (reeks[niveau]||reeks.Bronze);
}

// Interne wetenschappelijke onderbouwing (NIET tonen in de leerling-flow).
function bouwOnderbouwing({niveau,sub}){
  const f=BLOOM[niveau]?BLOOM[niveau].fase:"Ontdekken";
  return `Niveau ${niveau} (${f}). Opbouw volgens Bloom (cognitief niveau passend bij de fase), Vygotsky's Zone of Naaste Ontwikkeling (oriëntatie activeert voorkennis en biedt steun net boven het huidige niveau), Deliberate Practice (substappen lopen op in moeilijkheid met directe feedback) en zelfregulatie/executieve functies (plannen, monitoren en reflecteren via de rubric). Thema: ${sub}.`;
}

function kiesSubthema(subs,situatie,themaLabel){
  if(!subs||!subs.length)return themaLabel;
  if(subs.length===1)return subs[0];
  // Lichte 'beste match': kies het subthema waarvan de meeste woorden in de situatie voorkomen.
  const tekst=(situatie||"").toLowerCase();
  if(tekst){
    let beste=null,score=-1;
    for(const s of subs){
      const woorden=s.toLowerCase().split(/[^a-zà-ÿ]+/).filter(w=>w.length>3);
      const t=woorden.reduce((n,w)=>n+(tekst.includes(w)?1:0),0);
      if(t>score){score=t;beste=s;}
    }
    if(score>0)return beste;
  }
  // Geen context-match: kies er willekeurig één (niet samenplakken).
  return subs[Math.floor(Math.random()*subs.length)];
}
