// Challenge Diversity Engine: een werkvorm die al voorkomt binnen de laatste 15 uitdagingen is
// verboden, nooit twee keer op rij dezelfde werkvormcategorie. Vult SPORTEVENT_WERKVORMEN aan met
// de brede WERKVORM_BIBLIOTHEEK zodat er altijd genoeg opties overblijven.
function kiesSporteventWerkvorm(niveau,event,vermijd,laatsteCategorie){
  const basis=SPORTEVENT_WERKVORMEN[niveau]||SPORTEVENT_WERKVORMEN.Bronze;
  const gecombineerd=new Map();
  basis.forEach(w=>gecombineerd.set(w.naam,{naam:w.naam,categorie:w.categorie,maak:()=>w.beschrijving}));
  WERKVORM_BIBLIOTHEEK.forEach(w=>{if(!gecombineerd.has(w.naam))gecombineerd.set(w.naam,w);});
  const lijst=[...gecombineerd.values()];
  const recent=(Array.isArray(vermijd)?vermijd:[]).slice(0,15); // hard: laatste 15 uitdagingen
  let opties=lijst.filter(w=>!recent.includes(w.naam)&&w.categorie!==laatsteCategorie);
  if(!opties.length)opties=lijst.filter(w=>!recent.includes(w.naam));
  if(!opties.length){
    const laatste=recent[0];
    opties=lijst.filter(w=>w.naam!==laatste);
    if(!opties.length)opties=lijst;
  }
  const seed=`${event}|${recent[0]||""}|${recent.length}|${laatsteCategorie||""}`;
  let h=0; for(let i=0;i<seed.length;i++)h=(h*31+seed.charCodeAt(i))>>>0;
  const w=opties[h%opties.length];
  return {naam:w.naam,categorie:w.categorie,beschrijving:w.maak(String(event||"").toLowerCase(),"je sport")};
}
// Challenge Duration & Complexity Engine (lokaal).
// KERNPRINCIPE: omvang (tijd) en complexiteit (niveau) zijn twee ONAFHANKELIJKE dimensies.
// Een hoog niveau betekent dus niet automatisch een langere uitdaging. Dit systeem bepaalt
// uitsluitend de OMVANG (challenge-type → tijd); het niveau (Bronze→Platinum) bepaalt de complexiteit.
const CHALLENGE_TYPES={
  micro:{naam:"Micro Challenge", tijd:"5–10 minuten", tijdKort:"10 min"},
  core:{naam:"Core Challenge", tijd:"10–20 minuten", tijdKort:"20 min"},
  deep:{naam:"Deep Challenge", tijd:"20–45 minuten", tijdKort:"30–45 min"},
  project:{naam:"Project Challenge", tijd:"1–3 lessen (45–135 minuten)", tijdKort:"1–3 lessen"},
  master:{naam:"Master Challenge", tijd:"meerdaags project", tijdKort:"meerdaags"},
};
// Welke werkvormcategorieën neigen naar welke omvang. Bewust conservatief: de meeste losse
// uitdagingen zijn micro/core; deep alleen waar de werkvorm echt meer denkstappen vraagt.
const CATEGORIE_OMVANG={
  reflectief:["micro","core"],
  cognitief:["micro","core"],
  spelgericht:["micro","core"],
  visueel:["core","deep"],
  sociaal:["core","deep"],
  onderzoeksgericht:["core","deep"],
  praktisch:["core","deep"],
  fysiek:["micro","core"],
  creatief:["deep","core"],
};
// Kiest een omvang deterministisch, met variatie via seed, losgekoppeld van het niveau.
// variatie = recent aangeboden challenge-types (nieuwste eerst), zodat niet steeds dezelfde omvang komt.
function kiesChallengeType(categorie,onderwerp,recenteTypes){
  const opties=CATEGORIE_OMVANG[categorie]||["micro","core"];
  const recent=Array.isArray(recenteTypes)?recenteTypes:[];
  // Variatie-engine: als de laatste 2 challenges dezelfde omvang hadden, kies bewust de andere optie.
  let kandidaten=opties;
  if(recent.length>=2 && recent[0]===recent[1]){
    const anders=opties.filter(t=>t!==recent[0]);
    if(anders.length)kandidaten=anders;
  }
  const seed=`${onderwerp}|${categorie}|${recent[0]||""}|${recent.length}`;
  let h=0; for(let i=0;i<seed.length;i++)h=(h*31+seed.charCodeAt(i))>>>0;
  return kandidaten[h%kandidaten.length];
}

// Experience & Execution Engine (lokaal): leidt praktische uitvoerinfo af uit de werkvormcategorie
// en het gekozen challenge-type (voor de tijd), zodat een leerling elke lokaal gegenereerde
// uitdaging zelfstandig kan uitvoeren. De tijd komt uit de OMVANG, niet uit het niveau.
// Leidt materialen af uit het EINDPRODUCT (niet uit de werkvorm). "Wat heb je nodig?" volgt
// dus logisch het product: een poster vraagt A3 + stiften, een fotocollage een smartphone, enz.
const PRODUCT_MATERIALEN = [
  [/mini-poster|poster/i, ["A3-papier","stiften of markers"]],
  [/canva/i, ["een laptop of tablet"]],
  [/infographic/i, ["een laptop of tablet (bv. Canva)"]],
  [/fotocollage|collage/i, ["een smartphone met camera"]],
  [/\bvideo\b/i, ["een smartphone om mee te filmen"]],
  [/geluidsfragment|voice ?memo|podcast|opname|audiofragment/i, ["een smartphone om mee op te nemen"]],
  [/interviewkaart|interview/i, ["een interviewformulier of vel papier","iemand om te interviewen"]],
  [/mindmap|conceptmap|themakaart|oorzaak-gevolgkaart/i, ["A4-papier, of een digitaal canvas"]],
  [/moodboard/i, ["afbeeldingen of tijdschriften en papier — of een app zoals Canva"]],
  [/strip|storyboard/i, ["papier en potlood, of een tekenapp"]],
  [/beslisboom|tabel|voor-en-na-schema|schema/i, ["papier en pen, of een document"]],
  [/checklist|weekplanning|planning|actieplan|stappenkaart|routekaart|routinekaart/i, ["papier of een notitie-app"]],
  [/reflectiekaart|logboek|groeilogboek|stoplichtkaart|weektracker|patroonkaart/i, ["papier of de notities-app"]],
  [/scorekaart|quizkaart|kaartenset|keuzekaart/i, ["papier en pen"]],
  [/prototype/i, ["knutselmateriaal, of een ontwerp-app"]],
  [/pitchkaart|mini-presentatie|presentatie/i, ["papier, of presentatiesoftware"]],
  [/observatieformulier|observatiekaart|omgevingsscan/i, ["een observatieformulier of vel papier"]],
];
function materialenVoorProduct(eindproduct, fallback){
  const t=String(eindproduct||"");
  for(const [re,mats] of PRODUCT_MATERIALEN){ if(re.test(t)) return mats; }
  return fallback||["papier of een document"];
}

function uitvoerInfo(categorie,challengeType){
  const map={
    visueel:{eindproduct:"een ingevuld schema, mindmap of moodboard",benodigdheden:["papier en stift, of een app zoals Canva"],samen:"Alleen te doen.",bewijs:"Maak een foto van je schema of moodboard en laat die aan je mentor zien."},
    creatief:{eindproduct:"een gemaakt werk (video van max 60 sec, storyboard, strip of ontwerp)",benodigdheden:["je telefoon of computer"],samen:"Alleen te doen. Samen mag ook — dan wordt het vaak leuker.",bewijs:"Lever je gemaakte werk in of laat het zien tijdens het mentoruur."},
    sociaal:{eindproduct:"een ingevulde interviewkaart of gesprekskaart met de kernpunten",benodigdheden:["iemand om mee te praten","eventueel je telefoon om op te nemen"],samen:"Doe dit met een klasgenoot, teamgenoot of familielid. Niemand beschikbaar? Speel dan beide rollen zelf.",bewijs:"Laat je ingevulde interviewkaart zien, of speel een korte voice memo af."},
    fysiek:{eindproduct:"een ingevuld voor-en-na-schema van wat je merkte",benodigdheden:["ruimte om te bewegen"],samen:"Alleen te doen.",bewijs:"Laat je ingevulde voor-en-na-schema aan je mentor zien."},
    spelgericht:{eindproduct:"een ingevulde scorekaart of quizkaart met je uitkomst",benodigdheden:["papier en pen"],samen:"Alleen of samen — samen maakt het spannender.",bewijs:"Laat je ingevulde scorekaart zien."},
    onderzoeksgericht:{eindproduct:"een mini-onderzoekkaart of infographic met je conclusie",benodigdheden:["internet of twee bronnen","papier of een document"],samen:"Alleen te doen.",bewijs:"Lever je onderzoekkaart in of toon je infographic aan je mentor."},
    cognitief:{eindproduct:"een ingevulde beslisboom of tabel met je onderbouwing",benodigdheden:["papier of een document"],samen:"Alleen te doen.",bewijs:"Laat je ingevulde beslisboom of tabel zien."},
    reflectief:{eindproduct:"een ingevulde reflectiekaart met één patroon en één actie",benodigdheden:["papier of de notities-app"],samen:"Alleen te doen — even rustig voor jezelf.",bewijs:"Laat je ingevulde reflectiekaart aan je mentor zien."},
    praktisch:{eindproduct:"een plan, checklist of routinekaart die je echt kunt gebruiken",benodigdheden:["papier of een document"],samen:"Alleen te doen.",bewijs:"Maak een foto van je plan of checklist en laat die zien."},
  };
  const b=map[categorie]||map.cognitief;
  const t=CHALLENGE_TYPES[challengeType]||CHALLENGE_TYPES.core;
  // Mentor-check: max 3 korte, snel te checken punten (geen cijfers, geen rubric).
  const mentorCheck=["Het product is zichtbaar gemaakt.","De leerling legt in één zin uit wat hij of zij ontdekte.","De leerling kiest één concrete vervolgstap."];
  return {benodigdheden:materialenVoorProduct(b.eindproduct,b.benodigdheden), samenwerking:b.samen, tijd:t.tijd, challengeType:t.naam, eindproduct:b.eindproduct, bewijs:b.bewijs, mentorCheck};
}

function genereerSportevent({subs,niveau,sport,situatie,leeftijd,klas,themaLabel,vermijdWerkvormen,vermijdOnderwerpen,laatsteCategorie,recenteTypes}){
  const tprof=taalprofiel(leeftijd,klas);
  const sub=kiesSubthema(subs,situatie,themaLabel);
  const {categorie,event}=splitSportevent(sub);
  const prof=SPORTEVENT_PROFIEL[categorie.toLowerCase()]||{kern:"een groot sportevenement met topsporters",focus:["topsportmentaliteit","omgaan met druk","voorbereiding","doorzettingsvermogen"]};
  const sp=sport&&sport!=="Algemeen"?sport:"je eigen sport";
  const f=prof.focus;
  const f1=f[0], f2=f[1]||f[0], f3=f[2]||f[1]||f[0];
  const comps=kies(f.map(hoofdletter), niveau==="Bronze"?3:4);
  const rol=SPORTEVENT_ROL[categorie.toLowerCase()]||SPORTEVENT_ROL_DEFAULT;
  const werkvorm=kiesSporteventWerkvorm(niveau,event,Array.isArray(vermijdWerkvormen)?vermijdWerkvormen:[],laatsteCategorie);
  const challengeType=kiesChallengeType(werkvorm.categorie,event,recenteTypes);
  const echteSituatie=`een echte training, wedstrijd of schoolsituatie rond ${sp}`;

  // Oriëntatie als OBJECT (titel + uitleg) met rol én gericht toernooi-onderzoek.
  const orientatie={
    titel:`Oriëntatie: ${event} als ${rol.rol}`,
    uitleg:`Jij bent vanaf nu ${rol.rol}. Onderzoek eerst ${event}: wat voor toernooi of wedstrijd is het (${prof.kern})? Wie doen er mee — welke landen, teams of sporters — en welke niveauverschillen zie je? Wat is het doel en hoe is het opgebouwd (poules, rondes, finales)? En wie zijn de grootste namen of favorieten? Noteer 3 dingen die je opvallen en kies wat jou het meest aanspreekt om te onderzoeken.`,
  };

  // Leerdoelen gekoppeld aan het evenement, oplopend in Bloom-niveau.
  const leerdoelenMap={
    Bronze:[
      `Ik kan beschrijven wat ${event} is, wie meedoen en hoe het is opgebouwd.`,
      `Ik kan herkennen hoe topsporters bij ${event} omgaan met ${f1}.`,
      `Ik kan uitleggen wat ik van ${event} kan leren voor ${sp} en school.`,
    ],
    Silver:[
      `Ik kan ${f1} van topsporters bij ${event} vertalen naar een concrete aanpak voor ${sp} en school.`,
      `Ik kan die aanpak een week lang oefenen in mijn eigen ritme.`,
      `Ik kan analyseren welke les uit ${event} mij het meeste oplevert.`,
    ],
    Gold:[
      `Ik kan evalueren hoe topsporters bij ${event} ${f1} en ${f2} inzetten om te presteren.`,
      `Ik kan een eigen verbetering ontwerpen die ik baseer op wat werkt bij ${event}.`,
      `Ik kan beoordelen wat voor mij wel en niet werkt en mijn aanpak bijsturen.`,
    ],
    Platinum:[
      `Ik kan de succesformule achter ${event} doorgronden en vertalen naar een plan voor mezelf én mijn team.`,
      `Ik kan een innovatie ontwerpen en mijn advies professioneel presenteren.`,
      `Ik kan deze inzichten toepassen in nieuwe situaties binnen sport en school.`,
    ],
  };
  const leerdoelen=leerdoelenMap[niveau]||leerdoelenMap.Bronze;

  // Substappen: missie-stappen met gerichte vragen + creatief ontwerpen.
  const analyse={titel:"Analyseer een topsporter of team", uitleg:`Kies als ${rol.rol} één sporter of team uit ${event} en zoek uit hoe zij omgaan met ${f1}. Beschrijf concreet wat ze doen, voor en tijdens de wedstrijd.`};
  const vertaal={titel:"Vertaal het naar jezelf", uitleg:`Wat ga jij deze week één keer net zo aanpakken in ${sp} of op school? Maak het klein en concreet.`};
  const reeks={
    Bronze:[
      {titel:"Verken het toernooi", uitleg:`Leg in je eigen woorden uit wat ${event} is en wat jou het meest aanspreekt.`},
      analyse,
      {titel:"Haal er één les uit", uitleg:`Kies één ding dat jij van ${event} kunt leren en leg uit waarom dat jou helpt.`},
    ],
    Silver:[
      analyse,
      vertaal,
      {titel:"Voer uit en meet", uitleg:`Voer je aanpak een week uit en noteer elke keer kort hoe het ging.`},
      {titel:"Analyseer je resultaat", uitleg:`Vergelijk jouw ervaring met hoe het bij ${event} gaat: wat werkte, wat niet?`},
    ],
    Gold:[
      {titel:"Vergelijk twee aanpakken", uitleg:`Vergelijk twee sporters of teams uit ${event}: wie gaat er anders om met ${f2}, en wat leer jij daarvan?`},
      {titel:"Ontwerp een verbetering", uitleg:`Ontwerp — net als een topteam — een trainings- of voorbereidingsplan voor ${f3} onder druk, gebaseerd op wat werkt bij ${event}.`},
      {titel:"Test in de praktijk", uitleg:`Test je ontwerp in ${echteSituatie}.`},
      {titel:"Evalueer en verbeter", uitleg:`Bepaal wat werkte, waarom, en hoe je het de volgende keer beter doet.`},
    ],
    Platinum:[
      {titel:"Doorgrond de succesformule", uitleg:`Onderzoek hoe het succes bij ${event} is opgebouwd rond ${f1} en ${f2}. Wat is de rode draad?`},
      {titel:"Ontwerp een innovatie", uitleg:`Ontwerp een vernieuwing voor het toernooi of voor jouw eigen sport (bv. een aanpak, systeem of campagne) en onderbouw je keuzes.`},
      {titel:"Voer uit en verzamel bewijs", uitleg:`Voer je plan meerdere dagen uit en verzamel bewijs van je voortgang.`},
      {titel:"Coach, pitch en inspireer", uitleg:`Leer een teamgenoot wat jij uit ${event} haalde, pitch je belangrijkste advies en verwerk de feedback.`},
    ],
  };
  const wpSE=werkvormProduct(werkvorm);
  const werkvormStap={titel:`Maak je ${(werkvorm.naam||"werkvorm").toLowerCase()}`, uitleg:`${werkvorm.beschrijving} Gebruik ${event} als bron. Zo ontstaat ${wpSE.product}.`};
  const stappen=[...(reeks[niveau]||reeks.Bronze), werkvormStap];

  const titelMap={
    Bronze:`Ontdek de succesfactoren van ${event}`,
    Silver:`Leer de aanpak van ${event}`,
    Gold:`Kraak de succesformule van ${event}`,
    Platinum:`Innoveer met de aanpak van ${event}`,
  };
  const succescriteria=[
    `Je hebt als ${rol.rol} onderzocht wat ${event} is en wie eraan meedoen.`,
    `Je hebt minstens één concrete les uit ${event} vertaald naar jezelf.`,
    `Je hebt de werkvorm "${werkvorm.naam}" afgerond met een zichtbaar eindresultaat.`,
  ];
  if(niveau==="Gold"||niveau==="Platinum")succescriteria.push(`Je onderbouwt je keuzes met concrete voorbeelden uit ${event}.`);
  if(niveau==="Platinum")succescriteria.push(`Je advies is professioneel gepresenteerd en haalbaar naast trainingen en school.`);

  const reflectie=[`Wat was je doel als ${rol.rol}, en wat is je belangrijkste bevinding?`,`Wat uit ${event} ga je echt zelf proberen?`];
  if(niveau!=="Bronze")reflectie.push(`Wat is je volgende concrete stap, en hoe houd je dit vast als het tegenzit — net als topsporters?`);

  return {
    titel:hoofdletter(titelMap[niveau]||titelMap.Bronze),
    thema:themaLabel,
    subthema:sub,
    onderwerp:event,
    niveau,
    fase:BLOOM[niveau]?BLOOM[niveau].fase:"Ontdekken",
    sport:sport||"Algemeen",
    bloom:BLOOM[niveau]?BLOOM[niveau].categorie:"",
    onderwijs:tprof.onderwijs,
    werkvorm:{naam:werkvorm.naam,beschrijving:werkvorm.beschrijving,categorie:werkvorm.categorie},
    ...uitvoerInfo(werkvorm.categorie,challengeType),
    ...(()=>{const wp=werkvormProduct(werkvorm);return {eindproduct:wp.product, bewijs:wp.bewijs, benodigdheden:materialenVoorProduct(wp.product)};})(),
    situatie:(situatie&&situatie.trim())||`MISSIE: ${rol.opdrachtgever} heeft jou als ${rol.rol} gevraagd te onderzoeken waarom topsporters bij ${event} succesvol zijn met ${f1}. Breng het in kaart, vertaal het naar ${sp} en presenteer je belangrijkste inzicht. Vanaf nu ben jij de ${rol.rol}.`,
    leerdoelen,
    competenties:comps,
    orientatie,
    stappen,
    succescriteria,
    reflectie,
    transfer:`Hoe pas je één les uit ${event} toe in je eerstvolgende training of toets?`,
    doorstroom:niveau==="Platinum"
      ? "Je werkt nu op het hoogste niveau. Kies een nieuw evenement en neem anderen mee."
      : `Klaar voor meer? Pak ${event} (of een ander toernooi) op ${({Bronze:"Silver",Silver:"Gold",Gold:"Platinum"})[niveau]}-niveau.`,
    onderbouwing:`Niveau ${niveau} (${BLOOM[niveau]?BLOOM[niveau].fase:"Ontdekken"}). Het sportevenement dient als motiverende, herkenbare metafoor met een rol/missie (modelleren en observerend leren, Bandura; betekenisvolle context verhoogt motivatie). Opbouw volgens Bloom, met deliberate practice, een creatieve ontwerpstap en zelfregulatie via reflectie. Evenement: ${event} (${categorie||"sport"}); rol: ${rol.rol}; ontwikkelfocus: ${f.join(", ")}.`,
  };
}
// ═══ EVIDENCE-BASED LEERSTRATEGIE-LAAG (lokale generator) ═══
// Thema's waarbij elke uitdaging structureel op bewezen leerstrategieën wordt gebouwd.
const LEERTHEMAS = ["studie","ef"];
// Herbruikbare, op onderzoek gebaseerde stappen (retrieval, spacing, interleaving, elaboratie, dual coding, worked example, zelfevaluatie, feedback).
const LEERSTRATEGIE_STAP = {
  voorbeeld:(o)=>({titel:"Zoek een voorbeeld en markeer de kernstap", uitleg:`Zoek een voorbeeld van hoe iemand ${o} stap voor stap aanpakt. Schrijf de 3 stappen over en zet een streep onder de belangrijkste stap met in 1 zin waarom. (worked example)`}),
  retrieval:(o)=>({titel:"Schrijf uit je hoofd 5 dingen op", uitleg:`Leg je aantekeningen weg en schrijf uit je hoofd 5 dingen op die je weet over ${o}. Kijk pas daarna of je iets vergat. (actief ophalen)`}),
  feedback:(o)=>({titel:"Vergelijk met de bron en verbeter", uitleg:`Leg je opgeschreven versie naast je bron of die van een klasgenoot. Streep fouten door en vul aan met een andere kleur, zodat je product klopt. (directe feedback)`}),
  elaboratie:(o)=>({titel:"Schrijf een 'omdat'-zin", uitleg:`Schrijf één zin op: "Deze aanpak van ${o} werkt omdat…". Voeg toe waarmee het samenhangt dat je al kunt. Zo maak je het verband zichtbaar. (elaboratie)`}),
  spaced:(o)=>({titel:"Zet 2 herhaalmomenten in je agenda", uitleg:`Noteer in je agenda 2 concrete momenten (over 2 én 4 dagen) waarop je ${o} kort uit je hoofd ophaalt. Schrijf de datum en het tijdstip erbij. (gespreid herhalen)`}),
  dualcoding:(o)=>({titel:"Maak een schema met tekst én beeld", uitleg:`Vat ${o} samen in een schema of mindmap met korte woorden én een tekening of pijlen. Zo ontstaat een blad dat je later gebruikt om te herhalen. (dual coding)`}),
  zelfstandig:(o)=>({titel:"Doe een opgave helemaal zelf", uitleg:`Maak nu een soortgelijke opgave of situatie rond ${o} helemaal zelf, zonder voorbeeld, en schrijf je antwoord op. Lukt het niet? Zet een vraagteken bij de stap die misging.`}),
  interleaving:(o)=>({titel:"Wissel af en noteer wat past", uitleg:`Oefen ${o} door elkaar met 1–2 andere onderwerpen. Schrijf per onderwerp één kenmerk op waaraan je herkent wélke aanpak past. (interleaving)`}),
  zelfevaluatie:(o)=>({titel:"Vul je stoplichtkaart in", uitleg:`Maak een mini-stoplichtkaart voor ${o}: groen (gaat goed), oranje (bijna), rood (nog niet). Zet bij rood één concrete actie. (zelfevaluatie)`}),
  uitleggen:(o)=>({titel:"Leg het uit en noteer de vraag", uitleg:`Leg ${o} uit aan een klasgenoot en schrijf op welke vraag je niet meteen kon beantwoorden. Die vraag is precies wat je nog moet oefenen. (elaboratie + feedback)`}),
  herhaalschema:(o)=>({titel:"Ontwerp je herhaalschema-kaart", uitleg:`Maak een kaart waarop staat wanneer je ${o} de komende weken herhaalt, afgestemd op je trainings- en schoolweken. Dit is je planning-product. (gespreid ophalen)`}),
};
// Stelt per niveau een onderbouwde reeks samen; sluit af met de gekozen werkvorm.
function bouwLeerstrategieStappen({sub,niveau,werkvorm}){
  const o=sub.toLowerCase();
  const S=LEERSTRATEGIE_STAP;
  const reeks={
    Bronze:[S.voorbeeld(o), S.retrieval(o), S.feedback(o), S.elaboratie(o)],
    Silver:[S.voorbeeld(o), S.retrieval(o), S.feedback(o), S.dualcoding(o), S.spaced(o), S.zelfstandig(o)],
    Gold:[S.retrieval(o), S.elaboratie(o), S.interleaving(o), S.zelfstandig(o), S.feedback(o), S.zelfevaluatie(o)],
    Platinum:[S.interleaving(o), S.herhaalschema(o), S.uitleggen(o), S.zelfstandig(o), S.zelfevaluatie(o)],
  };
  const wp=werkvormProduct(werkvorm);
  const werkvormStap={titel:`Maak je ${(werkvorm.naam||"werkvorm").toLowerCase()}`, uitleg:`${werkvorm.beschrijving} Zo maak je ${wp.product} waarmee je je kennis over ${o} zichtbaar en toetsbaar maakt.`};
  return [...(reeks[niveau]||reeks.Bronze), werkvormStap];
}
// ═══════════════════ MISSIE-GEDREVEN LOKALE GENERATOR (alle thema's) ═══════════════════
// Verborgen achtergrond-onderwerpen voor Commercie: per zichtbare categorie kiest de generator
// op de achtergrond een concreet onderwerp (niet zichtbaar als chip), op basis van context/niveau/sport.
