// Per thema: rol, opdrachtgever en kern voor de missie-framing.
const THEMA_MISSIE = {
  mentaal:{emoji:"🧠",rol:"mentale coach van jezelf",opdrachtgever:"je sportpsycholoog",kern:"focus, zelfvertrouwen en omgaan met druk"},
  weerbaarheid:{emoji:"🛡️",rol:"veerkrachtcoach",opdrachtgever:"je mentale begeleider",kern:"omgaan met tegenslag en verwachtingen"},
  ef:{emoji:"🧩",rol:"regisseur van je eigen leren",opdrachtgever:"je mentor",kern:"plannen, starten en volhouden"},
  studie:{emoji:"📚",rol:"regisseur van je eigen leren",opdrachtgever:"je mentor",kern:"slim en effectief studeren"},
  duaal:{emoji:"⚖️",rol:"regisseur van je dubbele carrière",opdrachtgever:"je studiebegeleider",kern:"sport en school in balans"},
  voeding:{emoji:"🍎",rol:"performance-voedingscoach van jezelf",opdrachtgever:"je diëtist",kern:"energie, herstel en slaap"},
  blessure:{emoji:"🩹",rol:"herstelregisseur",opdrachtgever:"je fysiotherapeut",kern:"slim en geduldig terugkomen na een blessure"},
  kracht:{emoji:"💪",rol:"krachtcoach van jezelf",opdrachtgever:"je trainer",kern:"sterker en explosiever worden"},
  socialmedia:{emoji:"📱",rol:"mediamaker & communicatiestrateeg",opdrachtgever:"je teammanager",kern:"bewust online zijn en helder communiceren"},
  doping:{emoji:"🧪",rol:"ambassadeur van schone sport",opdrachtgever:"je bond",kern:"eerlijk presteren en weten wat mag"},
  leiderschap:{emoji:"⭐",rol:"teamcaptain",opdrachtgever:"je coach",kern:"voorop gaan en je team versterken"},
  commercie:{emoji:"🤝",rol:"manager van je eigen sportcarrière",opdrachtgever:"je management",kern:"ondernemen, sponsoring, marketing en burgerschap"},
};
const MISSIE_DEFAULT={emoji:"🎯",rol:"regisseur van je eigen ontwikkeling",opdrachtgever:"je coach",kern:"je persoonlijke ontwikkeling"};

// Wisselende missies/rollen voor de niet-topsportroutes (variatie + juiste personen: mentor/ouders i.p.v. coach).
const GROEI_MISSIES=[
  {rol:"ontdekkingsreiziger van jezelf",opdrachtgever:"je mentor",kern:"ontdekken wie je bent en wat je wilt"},
  {rol:"bouwer van je eigen gewoontes",opdrachtgever:"je mentor",kern:"sterke gewoontes opbouwen"},
  {rol:"regisseur van je eigen ontwikkeling",opdrachtgever:"je ouders",kern:"je persoonlijke ontwikkeling"},
  {rol:"onderzoeker van je eigen groei",opdrachtgever:"je mentor",kern:"leren over jezelf en groeien"},
  {rol:"ontwerper van je beste versie",opdrachtgever:"je ouders",kern:"werken aan de beste versie van jezelf"},
  {rol:"kapitein van je eigen plan",opdrachtgever:"je mentor",kern:"zelf de leiding nemen over je plan"},
];
const TALENT_MISSIES=[
  {rol:"ontdekker van je talent",opdrachtgever:"je mentor",kern:"je talent ontdekken en verkennen"},
  {rol:"maker van je eigen project",opdrachtgever:"je mentor",kern:"iets moois maken met je talent"},
  {rol:"ontwerper van je toekomst",opdrachtgever:"je ouders",kern:"nadenken over je toekomst en ambities"},
  {rol:"onderzoeker van je interesses",opdrachtgever:"je mentor",kern:"uitzoeken wat jou echt boeit"},
  {rol:"bouwer van je ambitie",opdrachtgever:"je ouders",kern:"stappen zetten richting je droom"},
  {rol:"verkenner van je mogelijkheden",opdrachtgever:"je mentor",kern:"ontdekken wat je allemaal kunt"},
];
function kiesMissie(route,seed){
  const pool=route==="talent"?TALENT_MISSIES:GROEI_MISSIES;
  const s=String(seed);let h=0;for(let i=0;i<s.length;i++)h=(h*31+s.charCodeAt(i))>>>0;
  return {emoji:"",...pool[h%pool.length]};
}
