/* ═══════════════ CHALLENGE LIFECYCLE ENGINE ═══════════════ */
// Statusworkflow van een uitdaging/project. Elke status heeft een label, een eigen icoon
// (geen emoji — de iconen komen uit de Icon-component) en een tint voor de UI.
const LIFECYCLE_STATUS = {
  niet_gestart:{label:"Niet gestart", icon:"circle", kleur:"#8A9099", bg:"#EEF0F2"},
  bezig:{label:"Bezig", icon:"play", kleur:"#B26A1F", bg:"#FBEFE6"},
  gepauzeerd:{label:"Gepauzeerd", icon:"pause", kleur:"#7A7F71", bg:"#EFEFEA"},
  ingeleverd:{label:"Ingeleverd", icon:"upload", kleur:"#3B6FB0", bg:"#EAF1FA"},
  in_beoordeling:{label:"In beoordeling", icon:"eye", kleur:"#5B57B0", bg:"#EEEDFA"},
  terug:{label:"Terug voor verbetering", icon:"rewind", kleur:"#B0553B", bg:"#FBEEEA"},
  goedgekeurd:{label:"Goedgekeurd", icon:"check", kleur:"#2E7D43", bg:"#E7F3EB"},
  uitmuntend:{label:"Uitmuntend", icon:"star", kleur:"#B08A1F", bg:"#FBF5E6"},
  portfolio:{label:"Afgerond & in portfolio", icon:"cap", kleur:"#4C5943", bg:"#EDF0E9"},
};
const statusInfo = s => LIFECYCLE_STATUS[s] || LIFECYCLE_STATUS.niet_gestart;

// Fasesjablonen voor meerdaagse projecten. Elk projecttype krijgt logische fasen,
// elk met eigen doel, richttijd, werkvorm-hint, eindproduct, reflectie en XP.
