// Bepaalt of een challenge-type meerdaags/gefaseerd is.
const isProjectType = t => t==="Project Challenge" || t==="Master Challenge";

const PROJECT_KEY = "tc:projecten:v1";
// Projecten (meerdaagse/gefaseerde uitdagingen) met volledige levenscyclus. Vorm zie maakProject().
const projectStore = {
  async list(){try{if(typeof window!=="undefined"&&window.storage){const r=await window.storage.get(PROJECT_KEY,false);return r&&r.value?JSON.parse(r.value):[]};}catch{}return[];},
  async saveAll(lijst){try{if(typeof window!=="undefined"&&window.storage)await window.storage.set(PROJECT_KEY,JSON.stringify(lijst),false);}catch{}},
  async upsert(p){const l=await this.list();const zonder=l.filter(x=>x.id!==p.id);const nieuw=[p,...zonder];await this.saveAll(nieuw);return nieuw;},
};

// Bouwt een meerdaags project met fasen uit een basis-uitdaging (de challenge-data uit de generator).
function maakProject({basis, leerling, route, challengeType, projectId}){
  const groei = /groei|welzijn|persoonlijk|gewoonte|mentaal|weerbaar/i.test((basis&&basis.thema)||"") ;
  const sjabloonSleutel = groei ? "groeiproject" : "onderzoek_ontwerp";
  const sjabloon = PROJECT_FASE_SJABLOON[sjabloonSleutel];
  const nu = new Date().toISOString();
  const fasen = sjabloon.map((f,i)=>({
    ...f, index:i,
    status:"niet_gestart",
    werk:"",            // tussenresultaat van de leerling (tekst)
    notitie:"",
    reflectie:"",
    ingeleverdOp:null,
    xpVerdiend:0,
  }));
  return {
    id: projectId || ("prj-"+nieuwId()),
    type:"project",
    challengeType: challengeType||"Project Challenge",
    titel: (basis&&basis.titel) || "Persoonlijk project",
    thema: basis&&basis.thema, themaLabel: basis&&basis.themaLabel,
    subthema: basis&&basis.subthema, niveau: basis&&basis.niveau,
    route,
    werkvorm: basis&&basis.werkvorm,
    leerdoelen: (basis&&basis.leerdoelen)||[],
    competenties: (basis&&basis.competenties)||[],
    situatie: basis&&basis.situatie,
    fasen,
    faseActief:0,
    status:"niet_gestart",
    startOp:nu, laatsteActiviteit:nu,
    ingeleverdOp:null,
    aiOordeel:null,          // {sterk, verbeter, gemist, suggesties}
    docent:null,             // {actie, feedback, bonusXp, badge, opmerking, vervolg, door, op}
    portfolio:false,
    leerling: leerling ? {naam:leerling.naam, klas:leerling.klas, foto:leerling.foto, slug:slugVan(leerling)} : null,
    xp: fasen.reduce((s,f)=>s+(f.xp||0),0),
  };
}

// Voortgang in procenten op basis van afgeronde fasen.
function projectVoortgang(p){
  if(!p||!p.fasen||!p.fasen.length) return 0;
  const klaar = p.fasen.filter(f=>["ingeleverd","goedgekeurd","uitmuntend","portfolio"].includes(f.status)||f.werk).length;
  return Math.round((klaar/p.fasen.length)*100);
}
// Totaal tot nu toe verdiende XP binnen een project (per fase + bonus).
function projectXpVerdiend(p){
  if(!p) return 0;
  const faseXp = (p.fasen||[]).reduce((s,f)=>s+(f.xpVerdiend||0),0);
  const bonus = (p.docent&&p.docent.bonusXp)||0;
  const goedgekeurd = ["goedgekeurd","uitmuntend","portfolio"].includes(p.status)?100:0;
  return faseXp+bonus+goedgekeurd;
}

/* ═══════════════ SANDBOX & DEVELOPER INFRASTRUCTUUR ═══════════════ */
// Volledig geïsoleerde test-/ontwikkelmodus voor de Challenge Lifecycle. Draait op een aparte
// opslagsleutel, zodat productie (echte projecten, XP, portfolio) nooit wordt beïnvloed.
// Modulair opgezet: elke engine (Lifecycle, Rechten, XP, Portfolio, Fasen, Notificaties) heeft een
// eigen validator en zelftest die los kan draaien.

// 1) STATUS-OVERGANGEN: welke overgangen zijn geldig binnen de levenscyclus.
const LIFECYCLE_TRANSITIES = {
  niet_gestart:["bezig"],
  bezig:["bezig","gepauzeerd","ingeleverd","in_beoordeling"],
  gepauzeerd:["bezig","ingeleverd"],
  ingeleverd:["in_beoordeling"],
  in_beoordeling:["goedgekeurd","uitmuntend","terug"],
  terug:["bezig","ingeleverd","in_beoordeling"],
  goedgekeurd:["portfolio","uitmuntend"],
  uitmuntend:["portfolio"],
  portfolio:[],
};
// Valideert of een overgang van->naar is toegestaan. Retourneert {ok, reden}.
function valideerOvergang(van, naar){
  if(!LIFECYCLE_STATUS[naar]) return {ok:false, reden:`Onbekende doelstatus "${naar}"`};
  if(!van) return {ok:true, reden:"beginstatus"};
  if(van===naar) return {ok:true, reden:"geen wijziging"};
  const toegestaan = LIFECYCLE_TRANSITIES[van]||[];
  if(toegestaan.includes(naar)) return {ok:true, reden:"geldige overgang"};
  return {ok:false, reden:`Overgang "${statusInfo(van).label}" → "${statusInfo(naar).label}" is niet toegestaan`};
}

// 2) EVENT-LOGGER: legt elke lifecycle-overgang en systeemgebeurtenis vast (in-memory ringbuffer).
const SANDBOX_KEY = "tc:sandbox:v1";
const LIFECYCLE_LOG_MAX = 500;
const _lifecycleLog = [];
const _logAbonnees = new Set();
function lifecycleLog(niveau, module, bericht, extra){
  const entry = {
    id: "evt-"+Date.now().toString(36)+"-"+Math.random().toString(36).slice(2,6),
    ts: new Date().toISOString(),
    niveau: niveau||"info",   // info | success | warn | error
    module: module||"Lifecycle",
    bericht: bericht||"",
    extra: extra||null,
  };
  _lifecycleLog.unshift(entry);
  if(_lifecycleLog.length>LIFECYCLE_LOG_MAX) _lifecycleLog.length=LIFECYCLE_LOG_MAX;
  _logAbonnees.forEach(fn=>{try{fn(entry);}catch{}});
  return entry;
}
function abonneerLog(fn){ _logAbonnees.add(fn); return ()=>_logAbonnees.delete(fn); }
function leesLog(){ return _lifecycleLog.slice(); }
function wisLog(){ _lifecycleLog.length=0; _logAbonnees.forEach(fn=>{try{fn(null);}catch{}}); }

// 3) SANDBOX-STORE: geïsoleerde opslag, losgekoppeld van productie (projectStore).
const sandboxStore = {
  async list(){try{if(typeof window!=="undefined"&&window.storage){const r=await window.storage.get(SANDBOX_KEY,false);return r&&r.value?JSON.parse(r.value):[]};}catch(e){lifecycleLog("error","Sandbox","Kon sandbox niet lezen: "+(e&&e.message));}return[];},
  async saveAll(lijst){try{if(typeof window!=="undefined"&&window.storage){await window.storage.set(SANDBOX_KEY,JSON.stringify(lijst),false);return true;}}catch(e){lifecycleLog("error","Sandbox","Kon sandbox niet opslaan: "+(e&&e.message));}return false;},
  async upsert(p){const l=await this.list();const zonder=l.filter(x=>x.id!==p.id);const nieuw=[p,...zonder];const ok=await this.saveAll(nieuw);if(!ok)lifecycleLog("error","Sandbox","Opslaan van project '"+(p.titel||p.id)+"' mislukte");return nieuw;},
  async wis(){try{if(typeof window!=="undefined"&&window.storage){await window.storage.set(SANDBOX_KEY,JSON.stringify([]),false);lifecycleLog("info","Sandbox","Sandbox geleegd");return true;}}catch(e){lifecycleLog("error","Sandbox","Legen mislukte: "+(e&&e.message));}return false;},
};

// Past een statusovergang toe op een project MET validatie + logging. Retourneert {ok, project, reden}.
// Centrale, testbare mutatie-functie voor de lifecycle.
function pasStatusToe(project, naar, meta){
  const van = project.status;
  const check = valideerOvergang(van, naar);
  if(!check.ok){
    lifecycleLog("error","Lifecycle",`Geweigerde overgang op "${project.titel||project.id}": ${check.reden}`,{van,naar});
    return {ok:false, project, reden:check.reden};
  }
  const next = {...project, status:naar, laatsteActiviteit:new Date().toISOString()};
  if(naar==="ingeleverd"||naar==="in_beoordeling") next.ingeleverdOp = next.ingeleverdOp||new Date().toISOString();
  if(naar==="goedgekeurd"||naar==="uitmuntend"||naar==="portfolio") next.portfolio = true;
  if(meta&&meta.docent) next.docent = {...(project.docent||{}), ...meta.docent};
  lifecycleLog("success","Lifecycle",`"${project.titel||project.id}": ${statusInfo(van).label} → ${statusInfo(naar).label}`,{van,naar});
  return {ok:true, project:next, reden:check.reden};
}

