// Identity Timeline: bewaart op groeimomenten een snapshot van de identiteit (fase, model, componenten),
// zodat een leerling later de eigen ontwikkeling kan terugzien. Vorm: { [slug]: [snapshot, ...] }
const IDENTITY_TIMELINE_KEY = "tc:identity-timeline:v1";
const identityTimelineStore = {
  async map(){try{if(typeof window!=="undefined"&&window.storage){const r=await window.storage.get(IDENTITY_TIMELINE_KEY,false);return r&&r.value?JSON.parse(r.value):{}};}catch{}return{};},
  async list(slug){const m=await this.map();return m[slug]||[];},
  async add(slug,snapshot){try{const m=await this.map();const arr=m[slug]||[];arr.unshift(snapshot);m[slug]=arr.slice(0,50);if(typeof window!=="undefined"&&window.storage)await window.storage.set(IDENTITY_TIMELINE_KEY,JSON.stringify(m),false);return m[slug];}catch{}return[];},
};
// Legt een snapshot vast als er een nieuwe fase is bereikt (of als de tijdlijn nog leeg is).
async function misschienIdentiteitSnapshot(gebruiker, identiteit){
  if(!gebruiker||!identiteit)return;
  const slug=slugVan(gebruiker);
  try{
    const bestaand=await identityTimelineStore.list(slug);
    const laatsteFase=bestaand[0]&&bestaand[0].niveauIndex;
    if(bestaand.length===0 || laatsteFase!==identiteit.niveauIndex){
      await identityTimelineStore.add(slug,{
        ts:new Date().toISOString(),
        niveauIndex:identiteit.niveauIndex,
        titel:identiteit.titel,
        houding:identiteit.houding,
        route:identiteit.route,
        model:identiteit.model,
        domDim:identiteit.domDim,
        // componenten om de snapshot exact opnieuw te tekenen:
        component:{...identiteit},
      });
    }
  }catch{}
}

