// Klascode per klas, bv. H3A-X7P4. Uniek binnen de bestaande klassen.
function genKlascode(naam,bestaand){
  const pre=String(naam||"KLAS").toUpperCase().replace(/[^A-Z0-9]+/g,"").slice(0,4)||"KLAS";
  const rnd=()=>{let s="";const k="ABCDEFGHJKLMNPQRSTUVWXYZ23456789";for(let i=0;i<4;i++)s+=k[Math.floor(Math.random()*k.length)];return s;};
  const codes=new Set((bestaand||[]).map(k=>String(k.code||"").toUpperCase()));
  let c,n=0; do{c=`${pre}-${rnd()}`;n++;}while(codes.has(c)&&n<25);
  return c;
}
// Registreer een leerling bij een schoollicentie (idempotent op naam).
async function koppelLeerlingAanSchool(code,leerling){
  const school=await scholenStore.get(code);
  if(!school)return null;
  school.leerlingen=Array.isArray(school.leerlingen)?school.leerlingen:[];
  if(!school.leerlingen.some(l=>l.naam===leerling.naam)){
    school.leerlingen.push({naam:leerling.naam,klas:leerling.klas||"—",mentor:leerling.mentor||"",sinds:new Date().toISOString()});
    await scholenStore.set(school);
  }
  return school;
}
