function domeinVan(email){const m=String(email||"").toLowerCase().trim().match(/@([^@\s]+)$/);return m?m[1]:"";}
async function schoolViaDomein(email){
  const dom=domeinVan(email); if(!dom)return null;
  const m=await scholenStore.map();
  for(const k in m){const s=m[k];if(s&&s.domein&&String(s.domein).toLowerCase()===dom)return s;}
  return null;
}

