// PREDICTION — voorspel het volgende symbool in een patroon
function genPrediction(tier,thema){
  const syms=["△","◯","◻","◇"];
  const patroon=[];
  const lengte=Math.min(4+tier,7);
  for(let i=0;i<lengte;i++)patroon.push(syms[i%(2+Math.min(tier,2))]);
  const volgend=syms[lengte%(2+Math.min(tier,2))];
  const opties=_shuffle([...new Set([volgend,...syms])].slice(0,3));
  return {type:"keuze",categorie:"Prediction",titel:"Wat komt hierna?",subthema:"Patroonvoorspelling",
    vraag:`Welk symbool komt hierna? ${patroon.join(" ")} ?`,opties,juist:opties.indexOf(volgend),
    feedbackGoed:`Scherp. Het patroon herhaalt, dus ${volgend}.`,feedbackFout:`Bijna. Het patroon herhaalt zich, dus ${volgend}.`,
    reden:"Patronen voorspellen traint vooruitdenken op basis van wat je ziet."};
}
