function bonusHistorie(records){
  const b=(records||[]).filter(r=>r&&r.type==="bonus");
  b.sort((x,y)=>String(y.afgerondOp||y.datum||"").localeCompare(String(x.afgerondOp||x.datum||"")));
  return b;
}

// ── Verborgen vaardigheidsmodel (AI Game Director) ──────────────────────────
// Houdt per leerling een impliciete inschatting bij van 5 vaardigheden (0–100), afgeleid uit de
// bonus-geschiedenis: welke categorieën zijn gedaan en gelukt. Puur intern — nooit aan de leerling
// getoond. Wordt gebruikt om een bonusgame te kiezen die nét boven het huidige niveau ligt (flow).
const BONUS_SKILL_MAP = {
  // categorie → welke vaardigheid hij traint
  Logic:"probleemoplossend", Sequence:"strategisch", Planning:"strategisch", Strategy:"strategisch",
  Systems:"strategisch", Resource:"strategisch", Risk:"strategisch", Prediction:"probleemoplossend",
  Data:"probleemoplossend", Code:"probleemoplossend", HiddenRule:"probleemoplossend", Reverse:"probleemoplossend",
  Creative:"creativiteit", Innovation:"creativiteit",
  Reflection:"reflecteren", Ethics:"reflecteren", Decision:"reflecteren",
  Negotiation:"communicatie", Leadership:"communicatie",
  Memory:"probleemoplossend", Focus:"reflecteren", CognitiveFlex:"strategisch",
};
const BONUS_SKILLS = ["strategisch","creativiteit","reflecteren","communicatie","probleemoplossend"];
function bonusVaardigheidsmodel(historie){
  const model={strategisch:20,creativiteit:20,reflecteren:20,communicatie:20,probleemoplossend:20};
  const teller={strategisch:0,creativiteit:0,reflecteren:0,communicatie:0,probleemoplossend:0};
  const b=bonusHistorie(historie);
  // nieuwste eerst; oudere tellen iets lichter mee (recente prestaties wegen zwaarder)
  b.forEach((r,i)=>{
    const skill=BONUS_SKILL_MAP[r.categorie]; if(!skill)return;
    const gewicht=Math.max(0.5, 1-(i*0.03));
    const winst=(r.gelukt?9:3)*gewicht; // gelukt = meer groei; poging telt ook mee
    model[skill]=Math.min(100, model[skill]+winst);
    teller[skill]++;
  });
  return model;
}
// Kiest de vaardigheid die het meest 'aan de beurt' is: laagste score → meest ruimte om te groeien,
// zodat de challenge nét boven het huidige niveau ligt (flow, niet te makkelijk/moeilijk).
function volgendeBonusSkill(model){
  let laagste=BONUS_SKILLS[0];
  for(const s of BONUS_SKILLS){ if(model[s]<model[laagste]) laagste=s; }
  return laagste;
}

// Variatie-engine (harde regels): geen game twee keer op rij; geen mechaniek vaker dan 1× in de
// laatste 20; kies een categorie die past bij de vaardigheid die aan de beurt is (adaptieve flow).
function kiesBonusChallenge(niveauIndex,route,historie){
  const tier=TIER_VAN_NIVEAU[Math.max(0,Math.min(9,niveauIndex||0))];
  const thema=themaVanRoute(route);
  const b=bonusHistorie(historie);
  const laatste20=b.slice(0,20);
  const laatsteCat=b[0]&&b[0].categorie;                 // meest recente (voor "niet 2× op rij")
  const recenteCats=laatste20.map(r=>r.categorie).filter(Boolean); // mechaniek-venster van 20

  // Adaptief: welke vaardigheid heeft nu de meeste ruimte? Zoek daar passende categorieën bij.
  const model=bonusVaardigheidsmodel(historie);
  const doelSkill=volgendeBonusSkill(model);
  const skillCats=Object.keys(BONUS_SKILL_MAP).filter(c=>BONUS_SKILL_MAP[c]===doelSkill);

  const kandidaten=LOKALE_BONUS_GENERATOREN.map(g=>{try{return g.fn(tier,thema);}catch{return null;}}).concat(bankChallenge(tier,thema)).filter(Boolean);

  // Harde filters, in volgorde van strengheid:
  const nietOpRij = c => c.categorie!==laatsteCat;                          // 1) niet 2× op rij
  const nietIn20  = c => !recenteCats.includes(c.categorie);                // 2) mechaniek max 1× in 20
  const bijSkill  = c => skillCats.includes(c.categorie);                   // 3) past bij doel-vaardigheid

  let pool = kandidaten.filter(c=>nietOpRij(c)&&nietIn20(c)&&bijSkill(c));
  if(!pool.length) pool = kandidaten.filter(c=>nietOpRij(c)&&nietIn20(c)); // laat skill-voorkeur los
  if(!pool.length) pool = kandidaten.filter(c=>nietOpRij(c));              // laat 20-venster los
  if(!pool.length) pool = kandidaten;                                      // laatste redmiddel

  const p=_pick(pool);
  const teller=b.length;
  const tijd=bonusTijd(tier, teller);
  return {...p,tier,thema,meta:{...PUZZEL_TIERS[tier],tijd},tijd,doelSkill};
}
/* AI-generatie: persoonlijker en gevarieerder op basis van historie; lokaal als vangnet. */
async function genereerBonusAI({tier,thema,historie}){
  try{coreBeslis("bonus-games",{uitleg:"Bonusgame na een groeimoment ("+(thema||"")+")"});}catch{}
  try{
    const meta=PUZZEL_TIERS[tier];
    const recent=(historie||[]).slice(0,5).map(r=>`${r.categorie||"?"}:${r.gelukt?"goed":"niet gehaald"}`).join(", ")||"nog geen";
    // Harde variatie: categorieën uit de laatste 20 bonusgames zijn verboden; de allerlaatste sowieso.
    const laatste20cats=[...new Set((historie||[]).slice(0,20).map(r=>r&&r.categorie).filter(Boolean))];
    const laatsteCat=(historie&&historie[0]&&historie[0].categorie)||"";
    // Verborgen vaardigheidsmodel: kies een categorie die de vaardigheid traint die nu de meeste ruimte heeft.
    const skillModel=bonusVaardigheidsmodel(historie);
    const doelSkill=volgendeBonusSkill(skillModel);
    // Adaptieve moeilijkheid: bouwt voort op recente prestaties, niet alleen op de vaste tier.
    let streak=0; for(const r of (historie||[])){if(r&&r.gelukt)streak++;else break;}
    const adaptiefInstr = streak>=2
      ? `Deze leerling rondde de laatste ${streak} bonus-challenges succesvol af. Verhoog nu bewust de moeilijkheid boven het kale tier-niveau: maak het patroon abstracter, combineer meer variabelen tegelijk, voeg afleiding of een onverwachte wending toe.`
      : ((historie&&historie[0]&&!historie[0].gelukt)
        ? `De vorige bonus-challenge lukte niet. Houd deze uitdaging op het niveau van de tier zelf (niet moeilijker), zodat de leerling een succeservaring kan opbouwen — maar maak hem ook niet te makkelijk.`
        : "");
    const cats=Object.keys(BONUS_CATEGORIEEN).filter(c=>!["Memory","Focus","Code"].includes(c));
    const prompt=`Je bent de Bonus Challenge Engine van Unfold Neo, een Nederlands premium ontwikkelplatform voor middelbare scholieren. Genereer EXACT één bonus-challenge als JSON, zonder uitleg of markdown.

ONTWERPFILOSOFIE (zeer belangrijk): een Bonus Challenge mag NOOIT aanvoelen als een simpel spelletje of een basisschoolpuzzel. Ontwerp hem alsof hij afkomstig is uit een combinatie van cognitieve assessments, militaire selectietesten, strategische bordspellen, escape rooms, ondernemerschapschallenges, innovatiewedstrijden en topsport- of prestatiecoaching. De leerling moet regelmatig denken: "dit kost echt denkwerk." Doel is cognitieve groei stimuleren, geen tijd vullen.

COGNITIEVE BELASTING: combineer waar mogelijk meerdere denkvaardigheden tegelijk uit: logisch redeneren, patroonherkenning, werkgeheugen, ruimtelijk inzicht, strategisch plannen, kansberekening, creativiteit, systeemdenken, besluitvorming onder tijdsdruk. Vermijd een uitdaging waarbij maar één simpele vaardigheid nodig is — hoe hoger de tier, hoe meer vaardigheden tegelijk nodig zijn.

INSPIRATIEMENU (kies er ÉÉN als basis en vertaal die volledig naar het JSON-formaat "keuze" of "volgorde" hieronder — dit zijn invalshoeken, geen letterlijke velden):
- Strategic Planning: een complexe situatie met beperkte tijd/energie, meerdere doelen en een onverwachte gebeurtenis; kies de optimale planning.
- Multi Layer Logic: minstens twee patronen tegelijk (bv. richting, kleur, rotatie, positie) die allemaal tegelijk ontdekt moeten worden.
- Systems Thinking: één variabele verandert — welk ander onderdeel verandert daardoor automatisch mee?
- Resource Management: een budget aan tijd, geld, energie of motivatie; bereik het doel met zo min mogelijk middelen, elke keuze heeft een gevolg.
- Tactical Challenge: een doel met een onderweg opduikende, onverwachte hindernis; de optimale strategie verandert.
- Adaptive Escape: een reeks kleine aanwijzingen die logisch op elkaar voortbouwen, als een escape room.
- Data Analysis: beschrijf beknopt een dataset, tabel of patroon in cijfers; de leerling trekt de juiste conclusie.
- Innovation Challenge: een probleem waarvoor de leerling, binnen de tijd, de origineelste én haalbaarste oplossing kiest.
- Negotiation: een gesprekssituatie waarin de leerling inschat welke reactie de ander het beste overtuigt.
- Ethical Decision: een dilemma zonder duidelijk goed of fout antwoord, met een afweging tussen waarden en belangen.
- Reverse Engineering: een eindresultaat wordt getoond; de leerling herleidt welke stappen ertoe leidden.
- Pattern Prediction: een complexe reeks (getallen, vormen, kleuren, symbolen of relaties) die doorzien moet worden.
- Dynamic Memory: nieuwe informatie moet onthouden worden terwijl eerdere informatie ook nog moet kloppen.
- Cognitive Flexibility: de spelregels veranderen halverwege; de leerling moet direct omschakelen.
- Hidden Rule: de regel wordt niet uitgelegd maar moet ontdekt worden door goed naar het patroon te kijken.
- Risk Assessment: meerdere keuzes met elk een andere kans op succes; weeg de risico's af.
- Leadership: een teamsituatie waarin de keuze van de leerling motivatie, prestatie, vertrouwen of tijd beïnvloedt.
- Innovation Sprint: verbeter binnen zeer korte tijd een product, dienst of strategie, of los een maatschappelijk probleem op.

Context: thema "${THEMA_LABEL[thema]}", niveau ${meta.naam} (${meta.moeilijkheid}), tijdslimiet ${bonusTijd(tier,(historie||[]).length)} sec.
VARIATIE-ENGINE (harde regels): gebruik NOOIT twee keer op rij dezelfde spelmechaniek; ${laatsteCat?`de allerlaatste was "${laatsteCat}" — vermijd die sowieso. `:""}${laatste20cats.length?`Vermijd ook deze categorieën uit de laatste 20 bonusgames: ${laatste20cats.join(", ")}. `:""}Minstens 80% van alle bonusgames moet uniek zijn; combineer waar nodig twee mechanieken tot een nieuwe variant.
ADAPTIEVE FLOW (verborgen vaardigheidsmodel): richt deze challenge op de vaardigheid "${doelSkill}" — die heeft nu de meeste groeiruimte. Kies een categorie die daarbij past en leg de lat nét boven het huidige niveau: uitdagend maar haalbaar (flow, niet te makkelijk en niet te moeilijk).
MINDER TEKST, MEER INTERACTIE: toon maximaal 2–3 korte instructieregels; de leerling moet meteen kunnen starten zonder een lange uitleg te lezen.
Moeilijkheidsopbouw: ${tier<=1?"één duidelijke denkstap, maar altijd een échte denkstap — nooit pure feitenkennis":tier<=2?"combineer minstens 2 denkvaardigheden tegelijk":tier<=3?"reflectief én strategisch: toegepast op de leerling zelf, met een echte afweging tussen opties":tier<=4?"een scenario met meerdere onderling afhankelijke variabelen en minstens 3 denkstappen":"een eindbaas-scenario: combineer minstens 3 denkvaardigheden, bouw een onverwachte wending in, en zorg dat de voor de hand liggende keuze NIET de beste is"}.
${adaptiefInstr}
Eerdere challenges van deze leerling (herhaal deze categorieën, onderwerpen én scenario's NIET, ook niet in andere bewoording): ${recent}. Gebruik telkens een andere context, andere cijfers/namen/situaties en een ander domein (school, sport, sociaal, geld, tijd, project, team), zodat geen twee challenges ooit hetzelfde aanvoelen — procedureel gevarieerd, nooit een herhaling.
Kies een categorie uit: ${cats.join(", ")}.

Regels: 100% natuurlijk Nederlands, geen jargon, geen toets-gevoel maar een premium challenge, motiverend geformuleerd en nooit afstraffend bij een fout antwoord, geen emoji. Bij "keuze": maak de opties allemaal plausibel — de leerling moet écht afwegen, niet raden tussen één logische en twee absurde opties. Bij "volgorde": de juiste volgorde mag niet voor de hand liggend zijn op puur gezond verstand; er moet een onderliggende logica ontdekt worden.

JSON-vorm (kies "keuze" of "volgorde"):
{"type":"keuze","categorie":"...","titel":"max 4 woorden","subthema":"...","vraag":"2 tot 5 zinnen: schets eerst kort de complexe situatie (de constraints, variabelen of het patroon), stel dan de vraag","opties":["...","...","...","..."] (3 of 4 plausibele opties),"juist":0,"feedbackGoed":"1 zin","feedbackFout":"1 milde zin zonder straf, die uitlegt WAAROM het juiste antwoord klopt","reden":"1 zin waarom dit past bij de ontwikkeling op dit niveau"}
of
{"type":"volgorde","categorie":"...","titel":"...","subthema":"...","uitleg":"2 tot 4 zinnen: schets de situatie en wat er moet gebeuren","items":["stap1","stap2","stap3","stap4"] (4 tot 6 items, in de JUISTE volgorde, elk item kort en concreet),"feedbackGoed":"...","feedbackFout":"...","reden":"..."}
Antwoord met ALLEEN de JSON.`;
    const res=await fetch("https://api.anthropic.com/v1/messages",{method:"POST",headers:{"Content-Type":"application/json"},
      body:JSON.stringify({model:"claude-sonnet-4-6",max_tokens:1400,messages:[{role:"user",content:prompt}]})});
    const data=await res.json();
    const txt=(data.content||[]).map(c=>c&&c.text?c.text:"").join("").replace(/```json|```/g,"").trim();
    const j=JSON.parse(txt);
    if(!j||typeof j!=="object")return null;
    if(j.type==="keuze"){if(!Array.isArray(j.opties)||j.opties.length<2||j.opties.length>5||typeof j.juist!=="number"||j.juist<0||j.juist>=j.opties.length)return null;}
    else if(j.type==="volgorde"){if(!Array.isArray(j.items)||j.items.length<3||j.items.length>6)return null;}
    else return null;
    if(!BONUS_CATEGORIEEN[j.categorie])j.categorie=j.type==="volgorde"?"Sequence":"Strategy";
    if(!j.feedbackGoed||!j.feedbackFout||!j.reden)return null;
    return j;
  }catch(e){return null;}
}

// Verrijkt de fasen van een project met concrete, op de leerling toegesneden instructies.
// Faalt de AI-call, dan blijven de sjabloon-instructies staan (project werkt sowieso).
async function verrijkProjectFasen(project){
  try{coreBeslis("projecten-verrijking",{uitleg:"AI-verrijking van projectfasen"});}catch{}
  try{
    const f=project.fasen.map((x,i)=>`${i+1}. ${x.naam} — doel: ${x.doel}`).join("\n");
    const prompt=`Je bent de projectcoach van Unfold Neo (Nederlands, voortgezet onderwijs). Werk de fasen van dit meerdaagse project concreet uit voor DEZE leerling. Geef ALLEEN geldige JSON terug, geen uitleg.
Project: "${project.titel}" · thema ${project.themaLabel||project.thema} · subthema ${project.subthema||"-"} · niveau ${project.niveau}.
Fasen:
${f}
Voor elke fase: schrijf 2 tot 4 heldere, activerende instructiestappen (concreet, in natuurlijk Nederlands, B1/B2, geen Engelse constructies, geen vaktaal zonder uitleg) en één korte reflectievraag. Behoud de volgorde en het aantal fasen.
JSON-vorm: {"fasen":[{"instructies":["stap 1","stap 2"],"reflectievraag":"..."}, ...]} met exact ${project.fasen.length} items.
Antwoord met ALLEEN de JSON.`;
    const res=await fetch("https://api.anthropic.com/v1/messages",{method:"POST",headers:{"Content-Type":"application/json"},
      body:JSON.stringify({model:"claude-sonnet-4-6",max_tokens:1500,messages:[{role:"user",content:prompt}]})});
    const data=await res.json();
    const txt=(data.content||[]).map(c=>c&&c.text?c.text:"").join("").replace(/```json|```/g,"").trim();
    const j=JSON.parse(txt);
    if(!j||!Array.isArray(j.fasen))return project;
    const fasen=project.fasen.map((fase,i)=>{
      const bron=j.fasen[i]||{};
      return {...fase,
        instructies:Array.isArray(bron.instructies)&&bron.instructies.length?bron.instructies:[fase.doel],
        reflectievraag:bron.reflectievraag||"Wat ging goed en wat neem je mee naar de volgende fase?"};
    });
    return {...project, fasen};
  }catch(e){ return project; }
}

// AI-voorbeoordeling van ingeleverd werk. Uitsluitend adviserend — de docent beslist.
// Retourneert {sterk:[], verbeter:[], gemist:[], suggesties:[], samenvatting} of null bij falen.
async function aiVoorbeoordeling(project){
  try{coreBeslis("projecten-voorbeoordeling",{uitleg:"AI-voorbeoordeling van een project"});}catch{}
  try{
    const werk=project.fasen.map((f,i)=>`Fase ${i+1} (${f.naam}):\n${(f.werk||"—").slice(0,600)}${f.reflectie?`\nReflectie: ${f.reflectie.slice(0,300)}`:""}`).join("\n\n");
    const doelen=(project.leerdoelen||[]).join("; ");
    const prompt=`Je bent de AI-voorbeoordelaar van Unfold Neo (Nederlands, voortgezet onderwijs). Beoordeel het ingeleverde projectwerk van een leerling ADVISEREND — jij beslist niet, de docent beslist. Wees eerlijk maar opbouwend en groeigericht, nooit afstraffend. Geef ALLEEN geldige JSON terug.
Project: "${project.titel}" · niveau ${project.niveau}. Leerdoelen: ${doelen||"-"}.
Ingeleverd werk per fase:
${werk}
Beoordeel op volledigheid, kwaliteit, diepgang, creativiteit en reflectie in verhouding tot het niveau. 
JSON-vorm: {"samenvatting":"2 tot 3 zinnen overzicht","sterk":["1 tot 3 sterke punten"],"verbeter":["1 tot 3 verbeterpunten"],"gemist":["0 tot 3 ontbrekende onderdelen"],"suggesties":["1 tot 3 concrete suggesties"]}
Antwoord met ALLEEN de JSON.`;
    const res=await fetch("https://api.anthropic.com/v1/messages",{method:"POST",headers:{"Content-Type":"application/json"},
      body:JSON.stringify({model:"claude-sonnet-4-6",max_tokens:900,messages:[{role:"user",content:prompt}]})});
    const data=await res.json();
    const txt=(data.content||[]).map(c=>c&&c.text?c.text:"").join("").replace(/```json|```/g,"").trim();
    const j=JSON.parse(txt);
    if(!j||typeof j!=="object")return null;
    return {
      samenvatting:j.samenvatting||"",
      sterk:Array.isArray(j.sterk)?j.sterk:[],
      verbeter:Array.isArray(j.verbeter)?j.verbeter:[],
      gemist:Array.isArray(j.gemist)?j.gemist:[],
      suggesties:Array.isArray(j.suggesties)?j.suggesties:[],
      op:new Date().toISOString(),
    };
  }catch(e){ return null; }
}
function beloningVoor(tier){
  const xp=PUZZEL_TIERS[tier].bonus;
  if(tier>=5)return {xp,extra:{type:"badge",label:"Achievement badge · Legend Bonus",tekst:_pick(BONUS_QUOTES)}};
  if(tier>=2)return {xp,extra:{type:"quote",label:"Quote unlocked",tekst:_pick(BONUS_QUOTES)}};
  return {xp,extra:null};
}

function GrowthPuzzle({puzzel,onKlaar,onSluiten}){
  const meta=puzzel.meta;
  const [sec,setSec]=useState(meta.tijd);
  const [status,setStatus]=useState("bezig"); // bezig | goed | fout | tijd
  const [fase,setFase]=useState(puzzel.type==="geheugen"?"kijk":"doe");
  const [gekozen,setGekozen]=useState(null);
  const [selectie,setSelectie]=useState([]); // focus
  const [reeks,setReeks]=useState([]); // volgorde/geheugen
  const [beloning,setBeloning]=useState(null);
  const doelVolgorde=puzzel.type==="geheugen"?puzzel.reeks:(puzzel.items||[]);
  const geschud=useMemo(()=>_shuffle(doelVolgorde),[puzzel]);
  const focusItems=useMemo(()=>puzzel.type==="focus"?puzzel.items:[],[puzzel]);
  const stopRef=useRef(false);
  useEffect(()=>{
    if(status!=="bezig")return;
    const id=setInterval(()=>{setSec(s=>{if(s<=1){clearInterval(id);if(!stopRef.current){stopRef.current=true;setStatus("tijd");}return 0;}return s-1;});},1000);
    return ()=>clearInterval(id);
  },[status]);
  useEffect(()=>{
    if(puzzel.type!=="geheugen"||fase!=="kijk")return;
    const t=setTimeout(()=>setFase("doe"),(puzzel.toonSec||5)*1000);
    return ()=>clearTimeout(t);
  },[puzzel,fase]);
  const klaar=(gelukt)=>{stopRef.current=true;if(gelukt)setBeloning(beloningVoor(puzzel.tier));setStatus(gelukt?"goed":"fout");};
  const checkKeuze=()=>{if(gekozen==null)return;klaar(gekozen===puzzel.juist);};
  const checkFocus=()=>{const goed=focusItems.filter(i=>i.goed).map(i=>i.label).sort().join("|");const sel=[...selectie].sort().join("|");klaar(goed===sel);};
  const tapItem=(item)=>{if(status!=="bezig")return;if(reeks.includes(item))return;const nr=[...reeks,item];setReeks(nr);if(nr.length===doelVolgorde.length){klaar(nr.every((x,i)=>x===doelVolgorde[i]));}};
  const gelukt=status==="goed";
  const klaarStatus=status!=="bezig";
  const frac=Math.max(0,Math.min(1,sec/meta.tijd));
  const laag=sec<=10&&status==="bezig";
  const kleur=laag?"#C9621A":"var(--accent)";
  const catInfo=BONUS_CATEGORIEEN[puzzel.categorie]||BONUS_CATEGORIEEN.Strategy;
  return(
    <div style={{position:"fixed",inset:0,zIndex:70,background:"rgba(28,26,23,.55)",display:"grid",placeItems:"center",padding:18}} onClick={()=>klaarStatus&&onSluiten()}>
      <div className="card" style={{width:"100%",maxWidth:460,padding:"26px 24px",borderTop:`4px solid ${kleur}`}} onClick={e=>e.stopPropagation()}>
        <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",gap:10}}>
          <span className="eyebrow" style={{margin:0,color:"var(--accent-diep)"}}>Bonus · {meta.naam} · {catInfo.label}</span>
          {!klaarStatus&&<span style={{fontWeight:800,fontSize:"1.05rem",fontVariantNumeric:"tabular-nums",color:kleur}}>{Math.floor(sec/60)}:{String(sec%60).padStart(2,"0")}</span>}
        </div>
        {!klaarStatus&&<div style={{height:6,borderRadius:6,background:"var(--lijn)",overflow:"hidden",margin:"10px 0 4px"}}><div style={{height:"100%",width:`${frac*100}%`,background:kleur,transition:"width 1s linear"}}/></div>}
        {!klaarStatus&&<p className="muted" style={{fontSize:".76rem",margin:"0 0 12px",fontWeight:700,letterSpacing:".03em"}}>BEAT THE CLOCK · {meta.moeilijkheid} · +{meta.bonus} XP</p>}

        {!klaarStatus&&<>
          <h2 className="h2" style={{fontSize:"1.15rem",margin:"4px 0 6px"}}>{puzzel.titel}</h2>
          <p style={{margin:"0 0 14px",lineHeight:1.5,fontSize:".92rem"}}>{puzzel.type==="volgorde"||puzzel.type==="geheugen"?puzzel.uitleg:puzzel.type==="focus"?puzzel.doel:puzzel.vraag}</p>

          {puzzel.type==="code"&&(
            <div style={{marginBottom:14}}>
              <div style={{display:"flex",flexWrap:"wrap",gap:6,marginBottom:10}}>
                {puzzel.legende.map(([s,l])=>(<span key={s} style={{border:"1px solid var(--lijn)",borderRadius:10,padding:"5px 10px",fontSize:".9rem",fontWeight:700}}>{s} = {l}</span>))}
              </div>
              <div style={{textAlign:"center",fontSize:"1.6rem",letterSpacing:".2em",fontWeight:800,padding:"10px 0",background:"#FAF9F7",borderRadius:12}}>{puzzel.code}</div>
            </div>
          )}

          {(puzzel.type==="keuze"||puzzel.type==="code")&&(
            <div style={{display:"grid",gap:8}}>
              {puzzel.opties.map((o,i)=>(
                <button key={i} onClick={()=>setGekozen(i)} style={{textAlign:"left",padding:"12px 14px",borderRadius:12,border:`1.5px solid ${gekozen===i?"var(--accent)":"var(--lijn)"}`,background:gekozen===i?"var(--accent-zacht)":"#fff",fontWeight:600,fontSize:".9rem",lineHeight:1.4}}>{o}</button>
              ))}
              <button className="btn btn-accent" style={{marginTop:6}} disabled={gekozen==null} onClick={checkKeuze}>Controleer</button>
            </div>
          )}

          {puzzel.type==="focus"&&(
            <div>
              <div style={{display:"flex",flexWrap:"wrap",gap:6}}>
                {focusItems.map(it=>{
                  const aan=selectie.includes(it.label);
                  return <button key={it.label} onClick={()=>setSelectie(s=>aan?s.filter(x=>x!==it.label):[...s,it.label])} style={{padding:"9px 13px",borderRadius:999,border:`1.5px solid ${aan?"var(--accent)":"var(--lijn)"}`,background:aan?"var(--accent-zacht)":"#fff",color:aan?"var(--accent-diep)":"var(--inkt)",fontSize:".88rem",fontWeight:700}}>{it.label}</button>;
                })}
              </div>
              <button className="btn btn-accent" style={{marginTop:14,width:"100%"}} disabled={selectie.length===0} onClick={checkFocus}>Controleer</button>
            </div>
          )}

          {puzzel.type==="geheugen"&&fase==="kijk"&&(
            <div style={{textAlign:"center"}}>
              <div style={{fontSize:"2rem",letterSpacing:".25em",fontWeight:800,padding:"18px 0",background:"#FAF9F7",borderRadius:14}}>{puzzel.reeks.join(" ")}</div>
              <p className="muted" style={{fontSize:".8rem",marginTop:10}}>Onthoud de volgorde… de reeks verdwijnt zo.</p>
            </div>
          )}
          {puzzel.type==="geheugen"&&fase==="doe"&&(
            <div>
              <div style={{minHeight:44,display:"flex",flexWrap:"wrap",gap:6,padding:"8px",border:"1px dashed var(--lijn)",borderRadius:12,marginBottom:10,background:"#FAF9F7"}}>
                {reeks.length===0?<span className="muted" style={{fontSize:".82rem",alignSelf:"center"}}>Tik de symbolen in de onthouden volgorde…</span>:reeks.map((r,i)=>(
                  <span key={r} style={{display:"inline-flex",alignItems:"center",gap:6,background:"var(--accent-zacht)",color:"var(--accent-diep)",borderRadius:999,padding:"6px 12px",fontSize:"1rem",fontWeight:800}}>{r}</span>
                ))}
              </div>
              <div style={{display:"flex",flexWrap:"wrap",gap:8,justifyContent:"center"}}>
                {geschud.map(item=>(
                  <button key={item} onClick={()=>tapItem(item)} disabled={reeks.includes(item)} style={{width:52,height:52,borderRadius:14,border:"1.5px solid var(--lijn)",background:reeks.includes(item)?"#F0EFEC":"#fff",color:reeks.includes(item)?"#B4B4B4":"var(--inkt)",fontSize:"1.3rem",fontWeight:800}}>{item}</button>
                ))}
              </div>
              {reeks.length>0&&<button className="muted" style={{fontSize:".8rem",marginTop:10,background:"none"}} onClick={()=>setReeks([])}>Opnieuw</button>}
            </div>
          )}

          {puzzel.type==="volgorde"&&(
            <div>
              <div style={{minHeight:40,display:"flex",flexWrap:"wrap",gap:6,padding:"8px",border:"1px dashed var(--lijn)",borderRadius:12,marginBottom:10,background:"#FAF9F7"}}>
                {reeks.length===0?<span className="muted" style={{fontSize:".82rem",alignSelf:"center"}}>Tik de stappen in de juiste volgorde…</span>:reeks.map((r,i)=>(
                  <span key={r} style={{display:"inline-flex",alignItems:"center",gap:6,background:"var(--accent-zacht)",color:"var(--accent-diep)",borderRadius:999,padding:"5px 10px",fontSize:".82rem",fontWeight:700}}><b style={{opacity:.6}}>{i+1}</b> {r}</span>
                ))}
              </div>
              <div style={{display:"flex",flexWrap:"wrap",gap:6}}>
                {geschud.map(item=>(
                  <button key={item} onClick={()=>tapItem(item)} disabled={reeks.includes(item)} style={{padding:"9px 12px",borderRadius:999,border:"1.5px solid var(--lijn)",background:reeks.includes(item)?"#F0EFEC":"#fff",color:reeks.includes(item)?"#B4B4B4":"var(--inkt)",fontSize:".85rem",fontWeight:600}}>{item}</button>
                ))}
              </div>
              {reeks.length>0&&<button className="muted" style={{fontSize:".8rem",marginTop:10,background:"none"}} onClick={()=>setReeks([])}>Opnieuw</button>}
            </div>
          )}
        </>}

        {klaarStatus&&(
          <div style={{textAlign:"center",padding:"6px 0"}}>
            <span style={{width:56,height:56,borderRadius:"50%",background:gelukt?"var(--accent)":"#EDEAE5",color:gelukt?"#fff":"var(--grijs)",display:"grid",placeItems:"center",margin:"0 auto"}}>
              {gelukt?<Icon name="spark" size={26}/>:<Icon name="clock" size={26}/>}
            </span>
            <h2 className="h2" style={{marginTop:14,fontSize:"1.2rem"}}>{gelukt?"Bonus unlocked":status==="tijd"?"Tijd voorbij":"Net niet"}</h2>
            {gelukt&&beloning&&<p style={{fontWeight:800,color:"var(--accent-diep)",margin:"6px 0 0"}}>+{beloning.xp} XP · extra groei verdiend</p>}
            {gelukt&&beloning&&beloning.extra&&(
              <div style={{background:"var(--accent-zacht)",borderRadius:12,padding:"10px 14px",margin:"12px 0 0",textAlign:"left"}}>
                <span className="eyebrow" style={{margin:0,color:"var(--accent-diep)"}}>{beloning.extra.label}</span>
                <p style={{margin:"4px 0 0",fontSize:".88rem",fontStyle:"italic",lineHeight:1.45}}>"{beloning.extra.tekst}"</p>
              </div>
            )}
            <p style={{marginTop:12,lineHeight:1.5,fontSize:".9rem"}}>{gelukt?puzzel.feedbackGoed:puzzel.feedbackFout}</p>
            <div className="muted" style={{marginTop:10,fontSize:".8rem",lineHeight:1.5,textAlign:"left",background:"#FAF9F7",borderRadius:12,padding:"10px 14px"}}>
              <b>Vaardigheid getraind:</b> {catInfo.vaardigheid}.<br/>
              <b>In het echt:</b> {catInfo.echt}<br/>
              <b>Bij jouw ontwikkeling:</b> {puzzel.reden}
            </div>
            <button className="btn btn-accent" style={{marginTop:16,width:"100%"}} onClick={()=>{onKlaar(gelukt?beloning:null,gelukt,puzzel);onSluiten();}}>{gelukt?"Bonus ophalen":"Sluiten"}</button>
          </div>
        )}
        {!klaarStatus&&<button onClick={onSluiten} className="muted" style={{display:"block",margin:"14px auto 0",fontSize:".82rem",background:"none"}}>Later spelen</button>}
      </div>
    </div>
  );
}

// Eigen groei-iconen in dezelfde minimalistische lijnstijl als de rest van de app (geen emoji).
function GroeiIcoon({naam,size=22}){
  const p={width:size,height:size,viewBox:"0 0 24 24",fill:"none",stroke:"currentColor",strokeWidth:1.8,strokeLinecap:"round",strokeLinejoin:"round","aria-hidden":"true",style:{display:"block"}};
  switch(naam){
    case "Seed": return <svg {...p}><path d="M12 21v-7.5"/><path d="M12 14c-.3-2.6-2.3-3.7-4.4-3.7.1 2.6 2 3.9 4.4 3.7z"/><path d="M12 12.4c.3-2.9 2.5-4.3 4.9-4.3-.1 2.9-2.2 4.5-4.9 4.3z"/></svg>;
    case "Explorer": return <svg {...p}><path d="M6.5 21V4"/><path d="M6.5 5h9.5l-2 3 2 3H6.5"/></svg>;
    case "Builder": return <svg {...p}><rect x="3.4" y="12.6" width="7" height="6.8" rx="1"/><rect x="13.6" y="12.6" width="7" height="6.8" rx="1"/><rect x="8.5" y="4.6" width="7" height="6.8" rx="1"/></svg>;
    case "Creator": return <svg {...p}><path d="M12 3l1.9 6.1L20 11l-6.1 1.9L12 19l-1.9-6.1L4 11l6.1-1.9z"/></svg>;
    case "Challenger": return <svg {...p}><circle cx="12" cy="12" r="8"/><circle cx="12" cy="12" r="4"/><circle cx="12" cy="12" r="1.2" fill="currentColor"/></svg>;
    case "Performer": return <svg {...p}><path d="M12 3c2.2 3 5 5 5 9a5 5 0 01-10 0c0-1.8.8-3 1.9-4 .4 1 1 1.6 2 1.7C10.8 8.4 10 6.2 12 3z"/></svg>;
    case "Master": return <svg {...p}><path d="M4 9l8-6 8 6-8 12z"/><path d="M4 9h16M12 3v18"/></svg>;
    case "Elite": return <svg {...p}><path d="M13 3L5.5 13.5H11l-1 7.5 8.5-11H12z"/></svg>;
    case "Visionary": return <svg {...p}><path d="M12 3c3 2.2 5 5.2 5 9l-1.8 3H8.8L7 12c0-3.8 2-6.8 5-9z"/><circle cx="12" cy="10.4" r="1.5"/><path d="M9 15.5l-2 4M15 15.5l2 4"/></svg>;
    case "Legend": return <svg {...p}><path d="M4 8.5l3.3 8.8h9.4L20 8.5l-4.9 3.9L12 5.4 8.9 12.4z"/></svg>;
    default: return <svg {...p}><circle cx="12" cy="12" r="8"/></svg>;
  }
}
function GroeiReis({xp}){
  const g=groeiNiveauVan(xp);
  const kleurNu=g.huidig.kleur||"var(--accent)";
  return(
    <div>
      <div style={{display:"flex",alignItems:"center",gap:14}}>
        <span style={{width:54,height:54,borderRadius:16,background:kleurNu,color:"#fff",display:"grid",placeItems:"center",flexShrink:0}}><GroeiIcoon naam={g.huidig.naam} size={30}/></span>
        <div style={{flex:1,minWidth:0}}>
          <div style={{fontWeight:800,fontSize:"1.15rem"}}>{g.huidig.naam}</div>
          <div className="muted" style={{fontSize:".85rem"}}>{g.volgend?`Nog ${g.naarVolgend} XP tot ${g.volgend.naam}`:"Hoogste groeiniveau bereikt"}</div>
          <div style={{height:7,borderRadius:999,background:"#EAE8E2",marginTop:7,overflow:"hidden"}}>
            <div style={{width:`${Math.round(g.frac*100)}%`,height:"100%",background:kleurNu,transition:"width .8s cubic-bezier(.22,.61,.36,1)"}}/>
          </div>
        </div>
      </div>
      <div style={{display:"flex",overflowX:"auto",padding:"14px 2px 2px",WebkitOverflowScrolling:"touch"}}>
        {GROEINIVEAUS.map((lv,i)=>{
          const bereikt=i<=g.index, huidig=i===g.index;
          return(
            <div key={lv.naam} style={{display:"flex",alignItems:"flex-start",flexShrink:0}}>
              <div style={{display:"grid",placeItems:"center",width:56}}>
                <span style={{width:huidig?42:34,height:huidig?42:34,borderRadius:"50%",display:"grid",placeItems:"center",background:bereikt?lv.kleur+"22":"#F1EFEA",color:bereikt?lv.kleur:"#B7B1A7",border:huidig?`2px solid ${lv.kleur}`:"2px solid transparent",transition:"all .3s"}}><GroeiIcoon naam={lv.naam} size={huidig?22:18}/></span>
                <span style={{fontSize:".62rem",fontWeight:700,marginTop:5,color:bereikt?"var(--inkt)":"var(--grijs)",whiteSpace:"nowrap"}}>{lv.naam}</span>
              </div>
              {i<GROEINIVEAUS.length-1&&<span style={{width:14,height:2,background:i<g.index?lv.kleur:"var(--lijn)",flexShrink:0,marginTop:16}}/>}
            </div>
          );
        })}
      </div>
    </div>
  );
}
function berekenVaardigheden(klaar){
  const tel={};
  for(const r of (klaar||[])){
    const cs=(r.data&&Array.isArray(r.data.competenties))?r.data.competenties:[];
    for(const c of cs){ const k=String(c||"").trim(); if(k)tel[k]=(tel[k]||0)+1; }
  }
  return Object.entries(tel).map(([naam,n])=>({naam,n,pct:Math.min(100,20+n*20)})).sort((a,b)=>b.n-a.n).slice(0,6);
}
function VaardigheidBalken({klaar}){
  const vs=berekenVaardigheden(klaar);
  if(!vs.length)return <p className="muted" style={{margin:0,fontSize:".88rem"}}>Rond uitdagingen af om te zien welke vaardigheden je ontwikkelt.</p>;
  return(
    <div style={{display:"grid",gap:12}}>
      {vs.map(v=>(
        <div key={v.naam}>
          <div style={{display:"flex",justifyContent:"space-between",fontSize:".86rem",marginBottom:4}}><span style={{fontWeight:600}}>{v.naam}</span><span className="muted">{v.n}×</span></div>
          <div style={{height:8,borderRadius:999,background:"#EAE8E2",overflow:"hidden"}}><div style={{width:`${v.pct}%`,height:"100%",background:"var(--accent)",transition:"width .6s"}}/></div>
        </div>
      ))}
    </div>
  );
}
function BadgeStar({size=16}){return <svg width={size} height={size} viewBox="0 0 24 24" fill="currentColor" aria-hidden="true" style={{display:"block"}}><path d="M12 3.2l2.5 5.1 5.6.8-4.05 3.95.96 5.58L12 16.98 6.99 18.6l.96-5.58L3.9 9.1l5.6-.8z"/></svg>;}
function berekenStreak(klaar){
  const dagen=[...new Set((klaar||[]).map(r=>String(r.afgerondOp||r.datum||"").slice(0,10)).filter(Boolean))].sort();
  if(!dagen.length)return {huidig:0,best:0,dagen:0};
  const dayNum=(s)=>Math.floor(new Date(s+"T00:00:00").getTime()/86400000);
  const nums=dagen.map(dayNum);
  let best=1,run=1;
  for(let i=1;i<nums.length;i++){ if(nums[i]===nums[i-1]+1){run++;best=Math.max(best,run);}else if(nums[i]!==nums[i-1])run=1; }
  let huidig=1;
  for(let i=nums.length-1;i>0;i--){ if(nums[i]===nums[i-1]+1)huidig++; else break; }
  const vandaag=dayNum(new Date().toISOString().slice(0,10));
  if(vandaag-nums[nums.length-1]>1)huidig=0;
  return {huidig,best,dagen:dagen.length};
}

/* ════════════════ ACHIEVEMENT & GROWTH RECOGNITION SYSTEM (AGRS) ════════════════ */
// Erkent AANTOONBARE groei uit de Learning Memory — niet louter XP. Elke prestatie vereist een
// concrete drempel (bewijs uit challenges/mentor/reflectie) en soms mentorvalidatie. Vijf
// zeldzaamheidsniveaus met unieke animaties; verzamelreeksen met setbonus; verborgen achievements.
const ZELDZAAMHEID={
  Common:{label:"Common",kleur:"#8A8F98",rand:"#D7DADF",bg:"#F6F7F8",orde:1,klasse:"agrs-common"},
  Rare:{label:"Rare",kleur:"#4C79C0",rand:"#BFD2EC",bg:"#EEF4FC",orde:2,klasse:"agrs-rare"},
  Epic:{label:"Epic",kleur:"#8B4FD0",rand:"#DBC6F2",bg:"#F4EDFC",orde:3,klasse:"agrs-epic"},
  Legendary:{label:"Legendary",kleur:"#C9971F",rand:"#EBD79A",bg:"#FBF4DE",orde:4,klasse:"agrs-legendary"},
  Mythic:{label:"Mythic",kleur:"#9B4FBF",rand:"#E4C6F0",bg:"#F7ECFB",orde:5,klasse:"agrs-mythic"},
};
const TRAIT_LABEL={doorzetting:"Doorzettingsvermogen",creativiteit:"Creativiteit",samenwerking:"Samenwerking",eigenaarschap:"Eigenaarschap",reflectie:"Reflectie",probleemoplossend:"Probleemoplossend",leiderschap:"Leiderschap",leerstrategie:"Leerstrategieën",maatschappelijk:"Maatschappelijke betrokkenheid",mastery:"Meesterschap"};
function _traitSignalen(af){
  const has=(s,arr)=>arr.some(w=>String(s||"").toLowerCase().includes(w));
  let creativiteit=0,samenwerking=0,leiderschap=0,probleemoplossend=0,maatschappelijk=0,reflectie=0,eigenaarschap=0;
  const strategieSet=new Set();
  af.forEach(r=>{
    const d=r.data||{},a=r.alpe||{}; const cat=(d.werkvorm&&d.werkvorm.categorie)||""; const wv=(d.werkvorm&&d.werkvorm.naam)||"";
    const eind=(d.eindproduct||"").toLowerCase();
    if(cat==="creatief"||cat==="visueel"||has(eind,["poster","moodboard","vlog","ontwerp","prototype","storyboard","infographic","campagne"]))creativiteit++;
    if(cat==="sociaal"||has(d.samenwerking,["samen","klasgenoot","buddy","peer","groep"]))samenwerking++;
    if(has(wv,["coach","teach","peer","mentor","interview"])||has((a.rollen||[]).join(" "),["coach","leider","mentor"]))leiderschap++;
    if(cat==="denken"||has(d.bloom,["analys","evalu"])||has(wv,["casus","detective","debat"]))probleemoplossend++;
    if(r.thema==="commercie"||has(d.subthema,["burgerschap","maatschapp","duurzaam"]))maatschappelijk++;
    if(Array.isArray(r.reflectie)&&r.reflectie.some(x=>x&&x.waarde!=null))reflectie++;
    (a.leerstrategieen||[]).forEach(s=>strategieSet.add(String(s).toLowerCase()));
    if(r.niveau==="Platinum"||has((d.leerdoelen||[]).join(" "),["eigenaarschap","zelfstandig"]))eigenaarschap++;
  });
  return {creativiteit,samenwerking,leiderschap,probleemoplossend,maatschappelijk,reflectie,leerstrategie:strategieSet.size,eigenaarschap};
}
function bouwPrestatieContext({records,gebruiker,progVooraf}){
  const af=(records||[]).filter(r=>r&&r.afgerond&&r.data&&r.type!=="event"&&r.type!=="bonus");
  const niveauCount={Bronze:0,Silver:0,Gold:0,Platinum:0}; af.forEach(r=>{if(niveauCount[r.niveau]!=null)niveauCount[r.niveau]++;});
  const subs=[...new Set(af.map(r=>r.data.subthema).filter(Boolean))];
  const prog=progVooraf||subthemaProgressie(records,subs);
  const maxMastery=prog.reduce((m,p)=>Math.max(m,p.mastery||0),0);
  const subthemasMastered=prog.filter(p=>p.mastery>=80).length;
  const faseMastery=prog.filter(p=>p.faseIndex>=7).length;
  const st=berekenStreak(af);
  const reflectieCount=af.filter(r=>Array.isArray(r.reflectie)&&r.reflectie.length).length;
  const mentorValid=af.filter(r=>r.alpe&&r.alpe.mentorfeedback).length;
  const themas=new Set(af.map(r=>r.thema).filter(Boolean));
  let verbeterdNaLaag=false;
  subs.forEach(s=>{const rs=af.filter(r=>r.data.subthema===s).sort((a,b)=>String(a.afgerondOp||a.datum||"").localeCompare(String(b.afgerondOp||b.datum||"")));for(let i=1;i<rs.length;i++){if(rs[i-1].rubricScore!=null&&rs[i-1].rubricScore<60&&rs[i].rubricScore!=null&&rs[i].rubricScore>=70)verbeterdNaLaag=true;}});
  const traits=_traitSignalen(af);
  const tp=taalprofiel(gebruiker&&gebruiker.leeftijd,(gebruiker&&gebruiker.klas)||"");
  const eersteMet=(pred)=>{const r=af.find(pred);return r?r.id:null;};
  return {n:af.length,niveauCount,subthemaCount:subs.length,prog,maxMastery,subthemasMastered,faseMastery,streakBest:st.best,streakHuidig:st.huidig,reflectieCount,mentorValid,themaCount:themas.size,verbeterdNaLaag,traits,leeftijd:tp.leeftijd,onderwijs:tp.onderwijs,af,eersteMet};
}
