// ── Prioriteits-variantenset (8) — elk met een `img`-slot voor de echte NEO-render.
//    Zolang img=null tekent de engine procedureel (pose-motion + SVG-gezicht + prop).
//    Een geüploade transparante PNG hier invullen = variant meteen live, geen codewijziging.

/* ══════════════════ NEO CHARACTER LIBRARY ENGINE v2.0 ══════════════════
   16 pose-varianten, elk gekoppeld aan een rol/state. TWEE LAGEN:
   (1) de POSE (lichaam) wisselt per context/state; (2) de Facial Animation
   Engine (vizier: knipperen, glimlach-glow) blijft continu binnen elke pose
   actief. De Character Selection Engine kiest automatisch de juiste pose.
   Elke pose heeft een eigen auto-gedetecteerde vizier-rect (incl. ar). */
const NEO_CORE_IDLE="data:image/webp;base64,";
/* ══════════════ MODULAIRE NEO-ASSET-LOADER (lazy-load + cache) ══════════════
   Alleen de core-idle wordt direct meegeleverd. Alle sport-/talent-/thema-
   varianten zijn losse WebP-bestanden die pas geladen worden wanneer de
   Character Selection Engine ze nodig heeft, en daarna in-memory gecachet
   (één keer ophalen). Zet window.NEO_ASSET_BASE naar je eigen asset-host/CDN;
   default is ./assets/neo/. Nieuwe varianten toevoegen = alleen een bestand +
   een regel in het manifest, zonder de app-bundle te vergroten. */
const NEO_ASSET_BASE=(typeof window!=="undefined"&&window.NEO_ASSET_BASE)||"./assets/neo/";
const NEO_ASSET_MANIFEST={'basis': 'neo-basis.webp', 'start': 'neo-start.webp', 'highfive': 'neo-highfive.webp', 'sport': 'neo-sport.webp', 'idle': 'neo-idle.webp', 'celebrate': 'neo-celebrate.webp', 'coach2': 'neo-coach2.webp', 'football': 'neo-football.webp', 'tennis': 'neo-tennis.webp', 'music': 'neo-music.webp', 'think2': 'neo-think2.webp', 'success2': 'neo-success2.webp', 'reflect2': 'neo-reflect2.webp', 'running': 'neo-running.webp', 'dance': 'neo-dance.webp'};
const neoAssetCache=new Map([["idle",NEO_CORE_IDLE]]);
const neoAssetProm=new Map();
function neoAssetUrl(key){ return NEO_ASSET_BASE+(NEO_ASSET_MANIFEST[key]||("neo-"+key+".webp")); }
function loadNeoAsset(key){
  if(!key) return Promise.resolve(NEO_CORE_IDLE);
  if(neoAssetCache.has(key)) return Promise.resolve(neoAssetCache.get(key));
  if(neoAssetProm.has(key)) return neoAssetProm.get(key);
  const p=fetch(neoAssetUrl(key)).then(r=>{if(!r.ok)throw 0;return r.blob();})
    .then(b=>new Promise(res=>{const fr=new FileReader();fr.onload=()=>res(fr.result);fr.readAsDataURL(b);}))
    .then(u=>{neoAssetCache.set(key,u);return u;})
    .catch(()=>{neoAssetCache.set(key,NEO_CORE_IDLE);return NEO_CORE_IDLE;});
  neoAssetProm.set(key,p); return p;
}
function useNeoAsset(key){
  const [src,setSrc]=useState(()=>neoAssetCache.get(key)||NEO_CORE_IDLE);
  useEffect(()=>{ let ok=true;
    if(neoAssetCache.has(key)){ setSrc(neoAssetCache.get(key)); return; }
    loadNeoAsset(key).then(u=>{ if(ok)setSrc(u); });
    return ()=>{ok=false;};
  },[key]);
  return src;
}

