// Face-state → library-rol (val terug op idle). Context kan overrulen.
const NEO_STATE_LIB={idle:"idle",friendly:"welcome",coaching:"coach",thinking:"thinking",listening:"listening",reflect:"reflect",calm:"idle",focus:"focus",encouraging:"encourage",happy:"encourage",celebrate:"celebrate",highfive:"highfive",victory:"celebrate"};
// Context → library-rol (heeft voorrang op de state-mapping waar zinvol).
function neoLibraryRole(state, ctx){
  const c=ctx||{};
  if(c.appArea==="onboarding") return "welcome";
  if(c.sessionEnd||c.goodbye) return "goodbye";
  const bag=[c.theme,c.subtheme,...(c.sports||[]),...(c.interests||[]),...(c.talentTags||[])].filter(Boolean).join(" ").toLowerCase();
  if(/(voetbal|football|soccer)/.test(bag)) return "football";
  if(/(tennis|padel)/.test(bag)) return "tennis";
  if(/(muziek|music|dj|zang|dans|dance)/.test(bag)) return "music";
  if(/(basket|dribbel|bal|sport)/.test(bag) && (state==="focus"||state==="idle"||c.appArea==="challenge")) return "basketball";
  if(/(leider|leiderschap|leader|captain|aanvoerder)/.test(bag)) return "leader";
  if(c.resultState==="level_up"||c.resultState==="badge_earned") return "celebrate";
  if(c.resultState==="completed") return "success";
  if(c.challengeHard||c.moeilijk) return "challengemaster";
  return NEO_STATE_LIB[state]||"idle";
}
// Bouwt een variant-vormig object voor een library-pose (werkt in NeoLive).
function neoLibVariant(state, ctx){
  const role=neoLibraryRole(state, ctx); const e=NEO_LIBRARY[role]||NEO_LIBRARY.idle;
  return {id:"neo-lib-"+role, name:e.label, assetKey:e.assetKey, visor:e.visor, animationProfile:e.anim, role};
}

