/* ════════════════ HOOFD APP ════════════════ */
/* ════════════════ DISCOVERY STEP-TO-STEP FLOW ════════════════ */
const DISCOVERY_CONSTRUCTEN = [
  {key:"zelfeffectiviteit",label:"Zelfeffectiviteit",vraag:"Ik heb vertrouwen dat ik moeilijke opdrachten kan voltooien als ik mijn best doe."},
  {key:"mindset",label:"Growth mindset",vraag:"Als iets moeilijk is, kan ik mezelf verbeteren door te oefenen en feedback te gebruiken."},
  {key:"autonomie",label:"Autonomie",vraag:"Ik vind het belangrijk dat ik zelf keuzes kan maken in hoe ik leer en train."},
  {key:"motivatie",label:"Intrinsieke motivatie",vraag:"Ik leer en train beter als ik begrijp waarom iets belangrijk voor mij is."},
  {key:"planning",label:"Planning",vraag:"Ik plan mijn schoolwerk en trainingen meestal vooruit."},
  {key:"impulscontrole",label:"Impulscontrole",vraag:"Ik denk meestal eerst na voordat ik ergens aan begin."},
  {key:"doorzettingsvermogen",label:"Doorzettingsvermogen",vraag:"Ik blijf meestal doorgaan, ook als iets langer duurt of tegenzit."},
  {key:"stress",label:"Stressbeleving",vraag:"Ik raak snel gestrest als school, sport en andere dingen tegelijk veel worden.",omgekeerd:true},
  {key:"reflectie",label:"Reflectievermogen",vraag:"Na een opdracht, training of wedstrijd denk ik na over wat goed ging en wat beter kan."},
  {key:"socialeSteun",label:"Sociale steun",vraag:"Ik vraag hulp aan een coach, docent, mentor, ouder of teamgenoot als ik ergens niet uitkom."},
];
const TRAINING_OPTIES=["0–3 uur","4–6 uur","7–10 uur","11–15 uur","16+ uur"];
const SCHOOL_OPTIES=["Minder dan 20 uur","20–25 uur","26–30 uur","31–35 uur","Meer dan 35 uur"];

function bouwDiscoveryProfiel(d){
  const scores={};
  for(const c of DISCOVERY_CONSTRUCTEN) scores[c.key]=d.antwoorden[c.key]||3;
  const sterke=[], aandacht=[];
  for(const c of DISCOVERY_CONSTRUCTEN){
    const v=scores[c.key];
    if(c.omgekeerd){ if(v<=2)sterke.push("Stressbestendigheid"); else if(v>=4)aandacht.push("Stressregulatie"); }
    else { if(v>=4)sterke.push(c.label); else if(v<=2)aandacht.push(c.label); }
  }
  const zr=["zelfeffectiviteit","mindset","planning","impulscontrole","doorzettingsvermogen","reflectie"];
  const gem=zr.reduce((s,k)=>s+(scores[k]||3),0)/zr.length;
  const aanbevolenNiveau= gem>=4.2?"Gold":gem>=3.4?"Silver":"Bronze";
  const sterkTekst = sterke.length?sterke.slice(0,3).join(", ").toLowerCase():"je inzet en motivatie";
  const aandachtTekst = aandacht.length?aandacht.slice(0,2).join(" en ").toLowerCase():"het vasthouden van je routines";
  const samenvatting = `Je bent sterk in ${sterkTekst}. De komende tijd werk je vooral aan ${aandachtTekst}. Unfold Neo schrijft uitdagingen die jou helpen om `+
    (d.schooldoel?("op school "+d.schooldoel.toLowerCase()):"op school te groeien")+" en "+
    (d.sportdoel?("in je sport "+d.sportdoel.toLowerCase()):"in je sport stappen te zetten")+" te combineren met je persoonlijke ontwikkeling.";
  return {route:"topsport",profielNaam:"Prestatieprofiel",naam:d.naam,geboortedatum:d.geboortedatum||"",leeftijd:d.geboortedatum?leeftijdUit(d.geboortedatum):null,sport:d.sport,club:d.club,trainingUren:d.training,schoolUren:d.schoolU,schooldoel:d.schooldoel,sportdoel:d.sportdoel,droomdoel:d.droomdoel,scores,sterke,aandacht,aanbevolenNiveau,samenvatting,datum:new Date().toISOString()};
}

// Simpele uitleg bij moeilijke woorden (voor leerlingen van 12-16). Tik op een chip → korte uitleg.
const WOORD_UITLEG = {
  "stressregulatie":"Rustig blijven en jezelf kalmeren als iets spannend of druk wordt.",
  "stressbeleving":"Hoe sterk jij spanning of druk voelt.",
  "stressbestendigheid":"Goed omgaan met spanning en druk zonder van slag te raken.",
  "impulscontrole":"Even nadenken vóór je iets doet, in plaats van meteen reageren.",
  "doorzettingsvermogen":"Volhouden, ook als iets moeilijk is of tegenzit.",
  "planning":"Vooruit denken en op tijd beginnen, zodat je je werk af krijgt.",
  "zelfeffectiviteit":"Geloven dat jij het kunt als je je best doet.",
  "growth mindset":"Geloven dat je in alles kunt groeien door te blijven oefenen.",
  "autonomie":"Zelf keuzes maken en zelfstandig aan de slag gaan.",
  "intrinsieke motivatie":"Iets doen omdat je het zelf leuk of belangrijk vindt.",
  "extrinsieke motivatie":"Iets doen voor een beloning of omdat het moet.",
  "reflectievermogen":"Terugkijken op wat je deed en daarvan leren.",
  "reflectie":"Terugkijken op wat je deed en daarvan leren.",
  "sociale steun":"Hulp en steun van mensen om je heen, zoals vrienden, familie of je coach.",
  "emotieregulatie":"Omgaan met je gevoelens, ook als ze heftig zijn.",
  "taakinitiatie":"Uit jezelf beginnen aan een taak, zonder uit te stellen.",
  "werkgeheugen":"Dingen even in je hoofd vasthouden terwijl je ermee bezig bent.",
  "flexibiliteit":"Je makkelijk aanpassen als er iets verandert.",
  "zelfregulatie":"Jezelf sturen: je aandacht, je gevoel en je gedrag onder controle houden.",
  "veerkracht":"Weer terugveren na een tegenslag.",
  "prioriteren":"Kiezen wat het belangrijkste is om als eerste te doen.",
  "zelfvertrouwen":"Vertrouwen in wat je kunt.",
  "executieve functies":"De vaardigheden in je hoofd om te plannen, te focussen en jezelf te sturen.",
  "metacognitie":"Nadenken over hoe jij zelf het beste leert.",
  "zelfkennis":"Weten wie je bent, wat je kunt en wat je wilt.",
  "consciëntieusheid":"Hoe zorgvuldig en plichtsgetrouw je bent — je werkt netjes en maakt af wat je begint.",
  "conscientieusheid":"Hoe zorgvuldig en plichtsgetrouw je bent — je werkt netjes en maakt af wat je begint.",
  "openheid":"Hoe nieuwsgierig je bent en hoe je openstaat voor nieuwe dingen en ideeën.",
  "zelfstandigheid":"Hoe goed je zelf aan de slag gaat, zonder dat iemand je hoeft te sturen.",
  "zelfreflectie":"Terugkijken op wat je deed en daarvan leren.",
  "planningsvaardigheden":"Hoe goed je vooruit plant en op tijd begint.",
};
function UitlegChip({label,bg,kleur}){
  const [open,setOpen]=useState(false);
  const uitleg=WOORD_UITLEG[String(label||"").toLowerCase().trim()];
  if(!uitleg)return <span className="pill" style={{background:bg,color:kleur}}>{label}</span>;
  return(
    <span style={{position:"relative",display:"inline-block"}}>
      <button type="button" onClick={()=>setOpen(o=>!o)} onBlur={()=>setOpen(false)} className="pill" style={{background:bg,color:kleur,border:"none",cursor:"pointer",font:"inherit",display:"inline-flex",alignItems:"center",gap:6}}>
        {label}
        <span aria-hidden="true" style={{width:15,height:15,borderRadius:"50%",border:`1.3px solid ${kleur}`,fontSize:10,fontWeight:800,lineHeight:1,display:"grid",placeItems:"center",opacity:.85}}>i</span>
      </button>
      {open&&(
        <span role="tooltip" onClick={()=>setOpen(false)} style={{position:"absolute",bottom:"calc(100% + 8px)",left:0,zIndex:60,width:"max-content",maxWidth:240,background:"#141311",color:"#fff",fontSize:".8rem",lineHeight:1.45,fontWeight:500,padding:"9px 11px",borderRadius:10,boxShadow:"0 8px 24px rgba(0,0,0,.28)",whiteSpace:"normal"}}>{uitleg}</span>
      )}
    </span>
  );
}
// Inline woord met tik-voor-uitleg (voor labels die geen 'pill' zijn, bv. persoonlijkheidskenmerken).
function UitlegWoord({label,kleur,style}){
  const [open,setOpen]=useState(false);
  const uitleg=WOORD_UITLEG[String(label||"").toLowerCase().trim()];
  if(!uitleg)return <span style={style}>{label}</span>;
  return(
    <span style={{position:"relative",display:"inline-flex",alignItems:"center",gap:6,...(style||{})}}>
      <button type="button" onClick={()=>setOpen(o=>!o)} onBlur={()=>setOpen(false)} style={{background:"none",border:"none",padding:0,margin:0,font:"inherit",color:"inherit",cursor:"pointer",display:"inline-flex",alignItems:"center",gap:6}}>
        <span style={{borderBottom:`1.5px dotted ${kleur||"#B99"}`}}>{label}</span>
        <span aria-hidden="true" style={{width:15,height:15,borderRadius:"50%",border:`1.3px solid ${kleur||"#B99"}`,color:kleur||"#B99",fontSize:10,fontWeight:800,lineHeight:1,display:"grid",placeItems:"center",opacity:.85}}>i</span>
      </button>
      {open&&(
        <span role="tooltip" onClick={()=>setOpen(false)} style={{position:"absolute",bottom:"calc(100% + 8px)",left:0,zIndex:60,width:"max-content",maxWidth:240,background:"#141311",color:"#fff",fontSize:".8rem",lineHeight:1.45,fontWeight:500,padding:"9px 11px",borderRadius:10,boxShadow:"0 8px 24px rgba(0,0,0,.28)",whiteSpace:"normal"}}>{uitleg}</span>
      )}
    </span>
  );
}
function DiscoverySchaal({waarde,onKies}){
  return(
    <div style={{display:"flex",gap:6,marginTop:10}}>
      {[1,2,3,4,5].map(n=>(
        <button key={n} onClick={()=>onKies(n)} style={{flex:1,padding:"12px 0",borderRadius:10,fontWeight:800,fontSize:"1rem",cursor:"pointer",border:`1.5px solid ${waarde===n?"var(--accent)":"var(--lijn)"}`,background:waarde===n?"var(--accent)":"#fff",color:waarde===n?"#fff":"var(--grijs)"}}>{n}</button>
      ))}
    </div>
  );
}

function Discovery({gebruiker,onKlaar,onHome}){
  const [i,setI]=useState(0);
  const [naam,setNaam]=useState((gebruiker&&gebruiker.naam)||"");
  const [geboortedatum,setGeboortedatum]=useState((gebruiker&&gebruiker.geboortedatum)||"");
  const [sport,setSport]=useState("");
  const [club,setClub]=useState("");
  const [training,setTraining]=useState("");
  const [schoolU,setSchoolU]=useState("");
  const [schooldoel,setSchooldoel]=useState("");
  const [sportdoel,setSportdoel]=useState("");
  const [droomdoel,setDroomdoel]=useState("");
  const [antw,setAntw]=useState({});
  const [err,setErr]=useState("");
  const setA=(k,v)=>setAntw(a=>({...a,[k]:v}));

  const groep1=DISCOVERY_CONSTRUCTEN.slice(0,5);
  const groep2=DISCOVERY_CONSTRUCTEN.slice(5,10);
  const stappen=["welkom","naam","geboortedatum","sport","training","school","schooldoel","sportdoel","droomdoel","vragen1","vragen2","resultaat"];
  const totaal=stappen.length;
  const huidige=stappen[i];
  const ga=(d)=>{setErr("");setI(x=>Math.min(Math.max(x+d,0),totaal-1));if(typeof window!=="undefined")window.scrollTo({top:0,behavior:"smooth"});};

  const valideer=()=>{
    if(huidige==="naam"&&!naam.trim()){setErr("Vul je naam in.");return false;}
    if(huidige==="geboortedatum"&&!geboortedatum){setErr("Vul je geboortedatum in.");return false;}
    if(huidige==="sport"&&!sport.trim()){setErr("Vul minimaal je sport in.");return false;}
    if(huidige==="training"&&!training){setErr("Kies je trainingsuren.");return false;}
    if(huidige==="school"&&!schoolU){setErr("Kies je lesuren.");return false;}
    if(huidige==="vragen1"&&!groep1.every(c=>antw[c.key])){setErr("Beantwoord alle vragen voordat je verdergaat.");return false;}
    if(huidige==="vragen2"&&!groep2.every(c=>antw[c.key])){setErr("Beantwoord alle vragen voordat je verdergaat.");return false;}
    return true;
  };
  const volgende=()=>{if(valideer())ga(1);};

  const pct=Math.round((i/(totaal-1))*100);
  const OptieRij=({opties,waarde,onKies})=>(
    <div style={{display:"grid",gap:8,marginTop:10}}>
      {opties.map(o=>(
        <button key={o} onClick={()=>onKies(o)} style={{textAlign:"left",padding:"13px 16px",borderRadius:12,fontWeight:700,cursor:"pointer",border:`1.5px solid ${waarde===o?"var(--accent)":"var(--lijn)"}`,background:waarde===o?"var(--accent-zacht)":"#fff",color:waarde===o?"var(--accent-diep)":"var(--inkt)"}}>{o}</button>
      ))}
    </div>
  );
  const VraagBlok=({c})=>(
    <div className="card" style={{padding:"16px 18px",marginTop:12}}>
      <p style={{fontWeight:700,margin:0,lineHeight:1.4}}>{c.vraag}</p>
      <DiscoverySchaal waarde={antw[c.key]} onKies={v=>setA(c.key,v)}/>
    </div>
  );

  if(huidige==="resultaat"){
    const p=bouwDiscoveryProfiel({naam,geboortedatum,sport,club,training,schoolU,schooldoel,sportdoel,droomdoel,antwoorden:antw});
    return(
      <div className="in" style={{minHeight:"100vh",display:"grid",placeItems:"center",padding:"28px 18px"}}>
        <div className="card" style={{width:"100%",maxWidth:520,padding:"30px 26px"}}>
          <span className="eyebrow">Klaar</span>
          <h2 className="h2" style={{marginTop:8}}>Jouw Prestatieprofiel</h2>
          <div style={{display:"grid",gridTemplateColumns:"auto 1fr",gap:"6px 14px",margin:"18px 0",fontSize:".95rem"}}>
            <span className="muted">Naam</span><span style={{fontWeight:700}}>{p.naam||"—"}</span>
            <span className="muted">Sport</span><span style={{fontWeight:700}}>{p.sport||"—"}</span>
            {p.club&&<><span className="muted">Club</span><span style={{fontWeight:700}}>{p.club}</span></>}
            <span className="muted">Training/week</span><span style={{fontWeight:700}}>{p.trainingUren||"—"}</span>
            <span className="muted">Schoolbelasting</span><span style={{fontWeight:700}}>{p.schoolUren||"—"}</span>
          </div>
          <div style={{display:"grid",gap:14}}>
            <div>
              <span className="eyebrow">Sterke punten</span>
              {neoConfidence({profiel:p})>=NEO_DREMPELS.kwaliteiten&&p.sterke.length?(
              <div style={{display:"flex",flexWrap:"wrap",gap:6,marginTop:8}}>
                {p.sterke.map(s=>(<UitlegChip key={s} label={s} bg="var(--accent-zacht)" kleur="var(--accent-diep)"/>))}
              </div>):<Vergrendeld/>}
            </div>
            <div>
              <span className="eyebrow">Aandachtspunten</span>
              {neoConfidence({profiel:p})>=NEO_DREMPELS.ontwikkel&&p.aandacht.length?(
              <div style={{display:"flex",flexWrap:"wrap",gap:6,marginTop:8}}>
                {p.aandacht.map(s=>(<UitlegChip key={s} label={s} bg="#EEE" kleur="var(--grijs)"/>))}
              </div>):<Vergrendeld/>}
            </div>
            <div>
              <span className="eyebrow">Jouw richting</span>
              <p style={{marginTop:8,lineHeight:1.5}}>{p.samenvatting}</p>
            </div>
            <div style={{background:"var(--accent-zacht)",borderRadius:12,padding:"12px 16px"}}>
              <span className="muted" style={{fontSize:".82rem"}}>Aanbevolen startniveau</span>
              <p style={{fontWeight:800,fontSize:"1.05rem",margin:"2px 0 0",color:"var(--accent-diep)"}}>{p.aanbevolenNiveau==="Gold"?"Goud":p.aanbevolenNiveau}</p>
            </div>
          </div>
          <button className="btn btn-accent" style={{marginTop:22,width:"100%"}} onClick={()=>onKlaar(p)}>Naar mijn uitdagingen →</button>
          <p className="muted" style={{fontSize:".78rem",marginTop:14,lineHeight:1.5}}>Je antwoorden worden gebruikt om betere persoonlijke uitdagingen te maken. Mentoren of coaches zien alleen samenvattingen en voortgang, niet alles wat je letterlijk invult, tenzij de school dit anders instelt.</p>
        </div>
      </div>
    );
  }

  return(
    <div className="in" style={{minHeight:"100vh",display:"grid",placeItems:"center",padding:"28px 18px"}}>
      <div className="card" style={{width:"100%",maxWidth:520,padding:"30px 26px"}}>
        <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:4}}>
          <Logo onClick={onHome}/>
          <span className="muted" style={{fontSize:".8rem"}}>Stap {i+1} van {totaal}</span>
        </div>
        <div style={{height:6,borderRadius:6,background:"var(--lijn)",overflow:"hidden",margin:"10px 0 22px"}}>
          <div style={{height:"100%",width:`${pct}%`,background:"var(--accent)",transition:"width .3s"}}/>
        </div>

        {huidige==="welkom"&&(
          <div>
            <h2 className="h2">Laten we jouw Prestatieprofiel maken</h2>
            <p style={{marginTop:12,lineHeight:1.55}}>Beantwoord een paar korte vragen over school, sport en jouw doelen. Daarna maakt Unfold Neo jouw persoonlijke ontwikkelprofiel. Dit profiel helpt de AI om uitdagingen te schrijven die beter passen bij wie jij bent, wat je doet en waar je naartoe wilt.</p>
            <p className="muted" style={{fontSize:".82rem",marginTop:14,lineHeight:1.5}}>Je antwoorden worden gebruikt om betere persoonlijke uitdagingen te maken. Mentoren of coaches zien alleen samenvattingen en voortgang, niet alles wat je letterlijk invult, tenzij de school dit anders instelt.</p>
          </div>
        )}
        {huidige==="naam"&&(
          <div><span className="eyebrow">Wie ben jij?</span><h2 className="h2" style={{marginTop:8}}>Wat is je naam?</h2>
            <Veld label="Naam"><input className="field" value={naam} onChange={e=>setNaam(e.target.value)} placeholder="Voornaam en eventueel achternaam"/></Veld></div>
        )}
        {huidige==="geboortedatum"&&(
          <div><span className="eyebrow">Wie ben jij?</span><h2 className="h2" style={{marginTop:8}}>Wat is je geboortedatum?</h2>
            <Veld label="Geboortedatum"><input className="field" type="date" value={geboortedatum} max={new Date().toISOString().slice(0,10)} onChange={e=>setGeboortedatum(e.target.value)}/></Veld>
            {geboortedatum&&leeftijdUit(geboortedatum)?<p className="muted" style={{fontSize:".82rem",marginTop:6}}>Je bent {leeftijdUit(geboortedatum)} jaar — we stemmen de taal en uitdagingen hierop af.</p>:null}</div>
        )}
        {huidige==="sport"&&(
          <div><span className="eyebrow">Jouw sport</span><h2 className="h2" style={{marginTop:8}}>Welke sport doe je?</h2>
            <div style={{display:"grid",gap:12,marginTop:6}}>
              <Veld label="Sport"><input className="field" value={sport} onChange={e=>setSport(e.target.value)} placeholder="bv. voetbal, judo, turnen"/></Veld>
              <Veld label="Club, vereniging of academie"><input className="field" value={club} onChange={e=>setClub(e.target.value)} placeholder="bv. PSV Academy"/></Veld>
            </div></div>
        )}
        {huidige==="training"&&(
          <div><span className="eyebrow">Jouw sport</span><h2 className="h2" style={{marginTop:8}}>Hoeveel uur train je gemiddeld per week?</h2>
            <OptieRij opties={TRAINING_OPTIES} waarde={training} onKies={setTraining}/></div>
        )}
        {huidige==="school"&&(
          <div><span className="eyebrow">Jouw schoolweek</span><h2 className="h2" style={{marginTop:8}}>Hoeveel lesuren heb je gemiddeld per week?</h2>
            <OptieRij opties={SCHOOL_OPTIES} waarde={schoolU} onKies={setSchoolU}/></div>
        )}
        {huidige==="schooldoel"&&(
          <div><span className="eyebrow">Doelen dit schooljaar</span><h2 className="h2" style={{marginTop:8}}>Wat wil je dit schooljaar bereiken op school?</h2>
            <Veld label="Schooldoel"><textarea className="field" rows={3} value={schooldoel} onChange={e=>setSchooldoel(e.target.value)} placeholder="Bijvoorbeeld: overgaan, betere planning, hogere cijfers, minder stress, beter leren leren, examen halen."/></Veld></div>
        )}
        {huidige==="sportdoel"&&(
          <div><span className="eyebrow">Doelen dit sportjaar</span><h2 className="h2" style={{marginTop:8}}>Wat wil je dit jaar bereiken in je sport?</h2>
            <Veld label="Sportdoel"><textarea className="field" rows={3} value={sportdoel} onChange={e=>setSportdoel(e.target.value)} placeholder="Bijvoorbeeld: sterker worden, basisplaats halen, selectie halen, technisch beter worden, blessurevrij blijven."/></Veld></div>
        )}
        {huidige==="droomdoel"&&(
          <div><span className="eyebrow">Droomdoel</span><h2 className="h2" style={{marginTop:8}}>Wat is jouw grote droomdoel, ook als het nog ver weg lijkt?</h2>
            <Veld label="Droomdoel"><textarea className="field" rows={3} value={droomdoel} onChange={e=>setDroomdoel(e.target.value)} placeholder="Denk aan sport, school, studie, werk, persoonlijke ontwikkeling of wie je later wilt worden."/></Veld></div>
        )}
        {(huidige==="vragen1"||huidige==="vragen2")&&(
          <div>
            <span className="eyebrow">Ontwikkelvragen</span>
            <h2 className="h2" style={{marginTop:8}}>Hoe herken jij jezelf hierin?</h2>
            <p className="muted" style={{fontSize:".82rem",marginTop:6}}>1 = helemaal niet mee eens · 5 = helemaal mee eens</p>
            {(huidige==="vragen1"?groep1:groep2).map(c=>(<VraagBlok key={c.key} c={c}/>))}
          </div>
        )}

        {err&&<p style={{color:"var(--accent-diep)",fontSize:".86rem",marginTop:14}}>{err}</p>}
        <div style={{display:"flex",gap:10,marginTop:22}}>
          {i>0&&<button className="btn btn-licht" style={{flex:"0 0 auto",width:"auto",paddingLeft:"1.4rem",paddingRight:"1.4rem"}} onClick={()=>ga(-1)}>← Vorige</button>}
          <button className="btn btn-accent" style={{flex:1,width:"auto"}} onClick={volgende}>{huidige==="welkom"?"Start mijn profiel":huidige==="vragen2"?"Maak mijn profiel":"Volgende →"}</button>
        </div>
      </div>
    </div>
  );
}

const LOGO_TOPSPORT = "data:image/png;base64,";
const LOGO_JORIS = "data:image/png;base64,";
const LOGO_INNOVA = "data:image/png;base64,";
/* ════════════════ SCHOOLDASHBOARD ════════════════ */
function PlatformAdmin({onTerug}){
  const [scholen,setScholen]=useState([]);
  const [aanvragen,setAanvragen]=useState([]);
  const [klassen,setKlassen]=useState([]);
  const [audit,setAudit]=useState([]);
  const [laden,setLaden]=useState(true);
  const [domeinEdit,setDomeinEdit]=useState({});
  const herlaad=async()=>{
    try{const m=await scholenStore.map();setScholen(Object.keys(m).map(k=>m[k]));}catch{}
    try{setAanvragen(await aanvraagStore.list());}catch{}
    try{setKlassen(await klasStore.list());}catch{}
    try{setAudit(await auditStore.list());}catch{}
  };
  useEffect(()=>{(async()=>{await herlaad();setLaden(false);})();},[]);
  const klassenVan=(code)=>klassen.filter(k=>k.schoolcode&&k.schoolcode===code);
  const modLabel={neo:"Neo",pta:"PTA",projects:"Projects"};

  const bewaarSchool=async(next)=>{try{await scholenStore.set(next);}catch{}setScholen(s=>s.map(x=>x.code===next.code?next:x));};
  const zetStatus=async(school,status)=>{const next={...school,licentiestatus:status};await bewaarSchool(next);await auditStore.add("Licentiestatus gewijzigd",`${school.naam} → ${licentieLabel(status)}`);setAudit(await auditStore.list());};
  const toggleModule=async(school,k)=>{const mods={...(school.modules||{neo:true}),[k]:!(school.modules||{})[k]};const next={...school,modules:mods};await bewaarSchool(next);await auditStore.add("Module gewijzigd",`${school.naam}: ${modLabel[k]} ${mods[k]?"aan":"uit"}`);setAudit(await auditStore.list());};
  const koppelDomein=async(school)=>{const dom=String(domeinEdit[school.code]||"").trim().toLowerCase();const next={...school,domein:dom};await bewaarSchool(next);setDomeinEdit(d=>({...d,[school.code]:undefined}));await auditStore.add("Microsoft-domein gekoppeld",`${school.naam} → @${dom}`);setAudit(await auditStore.list());};

  const werkAanvraagBij=async(id,patch)=>{const l=await aanvraagStore.list();const nl=l.map(a=>a.id===id?{...a,...patch}:a);await aanvraagStore.saveAll(nl);setAanvragen(nl);};
  const goedkeuren=async(a)=>{
    let code=genSchoolcode(a.schoolnaam);
    if(await scholenStore.get(code))code=code.replace(/-2026$/,"")+"-"+Math.random().toString(36).slice(2,5).toUpperCase()+"-2026";
    const school={code,schoolId:a.schoolId||genSchoolId(),tenantId:genTenantId(),naam:a.schoolnaam,plaats:a.plaats||"",domein:domeinVan(a.email),beheerder:{naam:a.contact,email:a.email},plan:"pro",licentiestatus:"in_afwachting",modules:{neo:true,pta:false,projects:false},bewaartermijn:"3 jaar",status:"actief",klassen:[],mentoren:[],leerlingen:[],aangemaakt:new Date().toISOString()};
    try{await scholenStore.set(school);}catch{}
    await werkAanvraagBij(a.id,{status:"goedgekeurd"});
    await auditStore.add("Schoolaanvraag goedgekeurd",`${a.schoolnaam} · ${school.schoolId} · tenant ${school.tenantId}`);
    await herlaad_scholen_audit();
  };
  const herlaad_scholen_audit=async()=>{try{const m=await scholenStore.map();setScholen(Object.keys(m).map(k=>m[k]));}catch{}setAudit(await auditStore.list());};
  const afwijzen=async(a)=>{await werkAanvraagBij(a.id,{status:"afgewezen"});await auditStore.add("Schoolaanvraag afgewezen",a.schoolnaam);setAudit(await auditStore.list());};
  const meerInfo=async(a)=>{await werkAanvraagBij(a.id,{status:"info_gevraagd"});await auditStore.add("Meer informatie opgevraagd",a.schoolnaam);setAudit(await auditStore.list());};

  const actieveModules=scholen.reduce((s,sc)=>s+Object.keys(sc.modules||{}).filter(k=>(sc.modules||{})[k]).length,0);
  const totLeerlingen=scholen.reduce((s,sc)=>s+((sc.leerlingen||[]).length),0);
  const totMentoren=scholen.reduce((s,sc)=>s+((sc.mentoren||[]).length),0);
  const openAanvragen=aanvragen.filter(a=>!a.status||a.status==="ontvangen"||a.status==="info_gevraagd").length;
  const Stat=({label,waarde,sub})=>(
    <div className="card" style={{padding:"16px 18px"}}>
      <div className="eyebrow" style={{margin:0}}>{label}</div>
      <div style={{fontSize:"1.7rem",fontWeight:800,marginTop:4,lineHeight:1}}>{waarde}</div>
      {sub&&<div className="muted" style={{fontSize:".78rem",marginTop:4}}>{sub}</div>}
    </div>
  );
  const statusKleur=(s)=>licentieActief(s)?{bg:"var(--accent-zacht)",fg:"var(--accent-diep)"}:(s==="in_afwachting"||s==="concept")?{bg:"#FFF4E0",fg:"#9A6A12"}:{bg:"#F4E0E0",fg:"#9A2A2A"};

  return(
    <Section eyebrow="Platform Administrator" titel="Platformbeheer" sub="Intern beheer van scholen, licenties, modules, aanvragen en auditlogs. Uitsluitend voor Unfold-medewerkers.">
      {laden?<div className="card" style={{padding:24}}>Laden…</div>:(<>
        <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(140px,1fr))",gap:12,marginBottom:18}}>
          <Stat label="Scholen" waarde={scholen.length}/>
          <Stat label="Leerlingen" waarde={totLeerlingen}/>
          <Stat label="Mentoren" waarde={totMentoren}/>
          <Stat label="Actieve modules" waarde={actieveModules}/>
          <Stat label="Open aanvragen" waarde={openAanvragen}/>
        </div>

        <div className="card" style={{padding:"18px 22px",marginBottom:18}}>
          <h3 style={{margin:"0 0 12px",fontSize:"1.1rem",fontWeight:800}}>Systeemstatus</h3>
          <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(150px,1fr))",gap:10}}>
            {[["Server","Operationeel"],["AI-services","Operationeel"],["Authenticatie","Operationeel"],["Back-ups","Actueel"],["Incidenten","0"]].map(([l,v])=>(
              <div key={l} style={{display:"flex",alignItems:"center",gap:8,padding:"8px 10px",borderRadius:10,background:"#f9f9f9"}}>
                <span style={{width:9,height:9,borderRadius:"50%",background:v==="0"||v==="Operationeel"||v==="Actueel"?"#3E9C54":"#C99A00",flexShrink:0}}/>
                <span style={{fontSize:".82rem"}}><b>{l}:</b> {v}</span>
              </div>
            ))}
          </div>
          <p className="muted" style={{fontSize:".74rem",marginTop:10}}>Realtime monitoring, IP- en device-controle draaien op de beveiligde platformlaag.</p>
        </div>

        <div className="card" style={{padding:"20px 22px",marginBottom:18}}>
          <h3 style={{margin:"0 0 12px",fontSize:"1.1rem",fontWeight:800}}>Licentieaanvragen</h3>
          {aanvragen.length===0?<p className="muted" style={{fontSize:".9rem",margin:0}}>Nog geen aanvragen ontvangen.</p>:(
            <div style={{display:"grid",gap:10}}>
              {aanvragen.map(a=>{
                const open=!a.status||a.status==="ontvangen"||a.status==="info_gevraagd";
                const stLabel=a.status==="goedgekeurd"?"Goedgekeurd":a.status==="afgewezen"?"Afgewezen":a.status==="info_gevraagd"?"Info opgevraagd":"Nieuwe aanvraag";
                return(
                  <div key={a.id} style={{border:"1px solid var(--lijn)",borderRadius:12,padding:"12px 14px"}}>
                    <div style={{display:"flex",justifyContent:"space-between",gap:10,flexWrap:"wrap",alignItems:"baseline"}}>
                      <span style={{fontWeight:800}}>{a.schoolnaam}{a.plaats?` · ${a.plaats}`:""}</span>
                      <span className="pill" style={{background:open?"#FFF4E0":"#EEE",color:open?"#9A6A12":"var(--grijs)",fontWeight:700,fontSize:".72rem"}}>{stLabel}</span>
                    </div>
                    <div className="muted" style={{fontSize:".82rem",marginTop:6,lineHeight:1.5}}>
                      {a.contact}{a.functie?` (${a.functie})`:""} · {a.email}{a.tel?` · ${a.tel}`:""}<br/>
                      {a.leerlingen||"—"} leerlingen · {a.mentoren||"—"} mentoren · Microsoft 365: {a.ms365||"—"}{a.opmerking?` · "${a.opmerking}"`:""}
                    </div>
                    {open&&(
                      <div style={{display:"flex",gap:8,flexWrap:"wrap",marginTop:10}}>
                        <button className="btn btn-accent" onClick={()=>goedkeuren(a)}>Goedkeuren</button>
                        <button className="btn btn-licht" onClick={()=>meerInfo(a)}>Meer info opvragen</button>
                        <button className="btn btn-licht" style={{color:"#B71C1C",borderColor:"#E4C4C4"}} onClick={()=>afwijzen(a)}>Afwijzen</button>
                      </div>
                    )}
                    {a.status==="goedgekeurd"&&<p className="muted" style={{fontSize:".78rem",margin:"8px 0 0"}}>Schoolomgeving aangemaakt · {a.schoolId}. Activeer de licentie hieronder bij Scholen.</p>}
                  </div>
                );
              })}
            </div>
          )}
        </div>

        <div className="card" style={{padding:"20px 22px",marginBottom:18}}>
          <h3 style={{margin:"0 0 12px",fontSize:"1.1rem",fontWeight:800}}>Scholen (tenants)</h3>
          {scholen.length===0?<p className="muted" style={{fontSize:".9rem",margin:0}}>Nog geen scholen. Keur een aanvraag goed of laat een beheerder een school aanmaken.</p>:(
            <div style={{display:"grid",gap:12}}>
              {scholen.map(sc=>{
                const mods=sc.modules||{neo:true};const kl=statusKleur(sc.licentiestatus);
                return(
                  <div key={sc.code} style={{border:"1px solid var(--lijn)",borderRadius:12,padding:"14px 16px"}}>
                    <div style={{display:"flex",justifyContent:"space-between",gap:10,flexWrap:"wrap",alignItems:"baseline"}}>
                      <span style={{fontWeight:800}}>{sc.naam}{sc.plaats?` · ${sc.plaats}`:""}</span>
                      <span className="muted" style={{fontSize:".76rem",fontFamily:"ui-monospace,Menlo,monospace"}}>{sc.schoolId||"—"} · {sc.tenantId||"—"} · {sc.code}</span>
                    </div>
                    <div style={{display:"flex",gap:8,flexWrap:"wrap",alignItems:"center",marginTop:10}}>
                      <span className="pill" style={{background:kl.bg,color:kl.fg,fontWeight:700}}>{licentieLabel(sc.licentiestatus)}</span>
                      <select value={sc.licentiestatus||"actief"} onChange={e=>zetStatus(sc,e.target.value)} style={{padding:"6px 8px",borderRadius:8,border:"1.5px solid var(--lijn)",fontSize:".8rem",background:"#fff",fontWeight:700}}>
                        {LICENTIE_STATUS.map(([v,l])=><option key={v} value={v}>{l}</option>)}
                      </select>
                      <span style={{flex:1}}/>
                      {["neo","pta","projects"].map(k=>(
                        <button key={k} onClick={()=>toggleModule(sc,k)} className="pill" style={{background:mods[k]?"var(--accent)":"#EEE",color:mods[k]?"#fff":"#B4B4B4",fontWeight:700,fontSize:".72rem"}}>{modLabel[k]}</button>
                      ))}
                    </div>
                    <div style={{display:"flex",gap:8,alignItems:"center",marginTop:10,flexWrap:"wrap"}}>
                      <span className="muted" style={{fontSize:".8rem"}}>Microsoft-domein:</span>
                      {domeinEdit[sc.code]!==undefined?(
                        <>
                          <input className="field" value={domeinEdit[sc.code]} onChange={e=>setDomeinEdit(d=>({...d,[sc.code]:e.target.value}))} placeholder="school.nl" style={{maxWidth:180,padding:"6px 8px",fontSize:".82rem"}}/>
                          <button className="btn btn-accent" onClick={()=>koppelDomein(sc)}>Koppel</button>
                          <button className="btn btn-licht" onClick={()=>setDomeinEdit(d=>({...d,[sc.code]:undefined}))}>Annuleer</button>
                        </>
                      ):(
                        <>
                          <b style={{fontSize:".84rem"}}>{sc.domein?`@${sc.domein}`:"niet gekoppeld"}</b>
                          <button className="btn btn-licht" onClick={()=>setDomeinEdit(d=>({...d,[sc.code]:sc.domein||""}))}>{sc.domein?"Wijzig":"Koppel"}</button>
                        </>
                      )}
                    </div>
                    <div className="muted" style={{fontSize:".8rem",marginTop:8}}>{(sc.mentoren||[]).length} mentoren · {(sc.leerlingen||[]).length} leerlingen · {klassenVan(sc.code).length} klassen{licentieActief(sc.licentiestatus)?"":" · toegang geblokkeerd (gegevens behouden)"}</div>
                  </div>
                );
              })}
            </div>
          )}
        </div>

        <div className="card" style={{padding:"20px 22px",marginBottom:18}}>
          <h3 style={{margin:"0 0 4px",fontSize:"1.1rem",fontWeight:800}}>Auditlog</h3>
          <p className="muted" style={{fontSize:".8rem",margin:"0 0 12px"}}>Onwijzigbaar overzicht van beheeracties.</p>
          {audit.length===0?<p className="muted" style={{fontSize:".9rem",margin:0}}>Nog geen acties geregistreerd.</p>:(
            <div style={{display:"grid",gap:6}}>
              {audit.slice(0,40).map(l=>(
                <div key={l.id} style={{display:"flex",gap:10,alignItems:"baseline",padding:"8px 10px",borderRadius:8,background:"#f9f9f9",flexWrap:"wrap"}}>
                  <span className="muted" style={{fontSize:".74rem",fontFamily:"ui-monospace,Menlo,monospace",minWidth:130}}>{new Date(l.ts).toLocaleString("nl-NL")}</span>
                  <span style={{fontWeight:700,fontSize:".84rem"}}>{l.actie}</span>
                  <span className="muted" style={{fontSize:".82rem"}}>{l.detail}</span>
                </div>
              ))}
            </div>
          )}
        </div>

        <p className="muted" style={{fontSize:".8rem",lineHeight:1.5}}>Facturatie, MFA, IP- en device-monitoring en disaster recovery verlopen via de beveiligde platformlaag en zijn hier niet zichtbaar. Iedere school is een gescheiden tenant.</p>
        <button onClick={onTerug} className="btn btn-licht" style={{marginTop:8}}>← Terug</button>
      </>)}
    </Section>
  );
}

function LicentieAanvraag({onTerug,onBeheerder}){
  const [f,setF]=useState({schoolnaam:"",plaats:"",contact:"",functie:"",email:"",tel:"",leerlingen:"",mentoren:"",ms365:"ja",opmerking:""});
  const [verzonden,setVerzonden]=useState(null);
  const [err,setErr]=useState("");
  const set=(k,v)=>setF(o=>({...o,[k]:v}));
  const verstuur=async()=>{
    if(!f.schoolnaam.trim()||!f.contact.trim()||!f.email.trim()){setErr("Vul minimaal schoolnaam, contactpersoon en e-mailadres in.");return;}
    setErr("");
    const schoolId=genSchoolId();
    try{await aanvraagStore.add({...f,id:nieuwId(),schoolId,status:"ontvangen",datum:new Date().toISOString()});}catch{}
    setVerzonden({schoolId});
    if(typeof window!=="undefined")window.scrollTo({top:0,behavior:"smooth"});
  };
  if(verzonden)return(
    <div className="in" style={{minHeight:"70vh",display:"grid",placeItems:"center",padding:"32px 18px"}}>
      <div className="card" style={{width:"100%",maxWidth:520,padding:"34px 30px",textAlign:"center",borderTop:"4px solid var(--accent)"}}>
        <span style={{width:56,height:56,borderRadius:"50%",background:"var(--accent)",color:"#fff",display:"grid",placeItems:"center",margin:"0 auto"}}><Icon name="check" size={26}/></span>
        <h2 className="h2" style={{marginTop:16}}>Licentieaanvraag ontvangen</h2>
        <p className="muted" style={{marginTop:8,lineHeight:1.55}}>Bedankt. We hebben je aanvraag voor <b>{f.schoolnaam}</b> ontvangen en nemen contact op met {f.contact} via {f.email}. Je aanvraag krijgt intern kenmerk <b>{verzonden.schoolId}</b>.</p>
        <div style={{background:"var(--accent-zacht)",borderRadius:12,padding:"14px 16px",margin:"18px 0",textAlign:"left"}}>
          <span className="eyebrow" style={{margin:0}}>Volgende stappen</span>
          <p className="muted" style={{fontSize:".86rem",margin:"6px 0 0",lineHeight:1.5}}>Aanvraag beoordelen → licentie activeren → Microsoft-domein koppelen → mentoren uitnodigen → klassen aanmaken. Daarna loggen leerlingen in met Microsoft en voeren ze eenmalig hun klascode in.</p>
        </div>
        <button className="btn btn-accent" style={{width:"100%"}} onClick={onBeheerder}>Ik ben schoolbeheerder — school inrichten</button>
        <button onClick={onTerug} className="muted" style={{display:"block",margin:"14px auto 0",fontSize:".85rem"}}>← Terug naar home</button>
      </div>
    </div>
  );
  return(
    <div className="in" style={{minHeight:"80vh",display:"grid",placeItems:"center",padding:"32px 18px"}}>
      <div className="card" style={{width:"100%",maxWidth:560,padding:"32px 28px"}}>
        <Logo onClick={onTerug}/>
        <span className="pill" style={{background:"var(--accent)",color:"#fff",fontWeight:800,marginTop:16,display:"inline-block"}}>Unfold Neo · €4.999 / jaar</span>
        <h2 className="h2" style={{marginTop:10}}>Vraag de Unfold Neo-licentie aan</h2>
        <p className="muted" style={{marginTop:8,lineHeight:1.55}}>De Unfold Neo-module binnen het Unfold Education Platform kost €4.999 per school per jaar (exclusief btw) en geeft volledige toegang tot alle routes, thema's, niveaus en functies. Na goedkeuring activeren we de licentie en koppelen we jullie Microsoft-domein.</p>
        <div style={{display:"grid",gap:12,marginTop:20}}>
          <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:12}}>
            <Veld label="Schoolnaam"><input className="field" value={f.schoolnaam} onChange={e=>set("schoolnaam",e.target.value)} placeholder="bv. St. Janslyceum"/></Veld>
            <Veld label="Vestigingsplaats"><input className="field" value={f.plaats} onChange={e=>set("plaats",e.target.value)} placeholder="bv. 's-Hertogenbosch"/></Veld>
            <Veld label="Contactpersoon"><input className="field" value={f.contact} onChange={e=>set("contact",e.target.value)} placeholder="Voor- en achternaam"/></Veld>
            <Veld label="Functie"><input className="field" value={f.functie} onChange={e=>set("functie",e.target.value)} placeholder="bv. teamleider"/></Veld>
            <Veld label="E-mailadres"><input className="field" type="email" value={f.email} onChange={e=>set("email",e.target.value)} placeholder="jij@school.nl"/></Veld>
            <Veld label="Telefoonnummer"><input className="field" value={f.tel} onChange={e=>set("tel",e.target.value)} placeholder="06 …"/></Veld>
            <Veld label="Aantal leerlingen"><input className="field" type="number" value={f.leerlingen} onChange={e=>set("leerlingen",e.target.value)} placeholder="bv. 800"/></Veld>
            <Veld label="Aantal mentoren"><input className="field" type="number" value={f.mentoren} onChange={e=>set("mentoren",e.target.value)} placeholder="bv. 65"/></Veld>
          </div>
          <Veld label="Microsoft 365 aanwezig?">
            <div style={{display:"flex",gap:8}}>
              {[["ja","Ja"],["nee","Nee"],["onbekend","Weet ik niet"]].map(([v,l])=>(
                <button key={v} onClick={()=>set("ms365",v)} style={{flex:1,padding:"9px 4px",borderRadius:10,fontWeight:700,fontSize:".82rem",border:`1.5px solid ${f.ms365===v?"var(--accent)":"var(--lijn)"}`,background:f.ms365===v?"var(--accent-zacht)":"#fff",color:f.ms365===v?"var(--accent-diep)":"var(--grijs)"}}>{l}</button>
              ))}
            </div>
          </Veld>
          <Veld label="Opmerkingen (optioneel)"><textarea className="field" rows={3} value={f.opmerking} onChange={e=>set("opmerking",e.target.value)} placeholder="Gewenste modules, koppelingen of vragen…" style={{resize:"vertical"}}/></Veld>
        </div>
        {err&&<p style={{color:"var(--accent-diep)",fontSize:".86rem",marginTop:12}}>{err}</p>}
        <button className="btn btn-accent" style={{marginTop:18,width:"100%"}} onClick={verstuur}>Aanvraag versturen</button>
        <button onClick={onTerug} className="muted" style={{display:"block",margin:"14px auto 0",fontSize:".85rem"}}>← Terug</button>
      </div>
    </div>
  );
}

// ── INTEGRATION INTELLIGENCE — modulaire, slimme koppelingen (adapter-registry + overzicht) ──
// Geen losse koppelingen maar SLIMME koppelingen: elke integratie beschrijft wat ze intelligent doet.
// Modulair zoals de Opportunity-connectors: externe adapters pluggen in via registreerIntegratie(key, adapter);
// zodra een adapter geregistreerd is, wordt de status automatisch 'actief'. AVG: sport/health alleen opt-in.
const INTEGRATIE_ADAPTERS={};
function registreerIntegratie(key,adapter){ INTEGRATIE_ADAPTERS[key]={key,adapter,sinds:Date.now()}; return INTEGRATIE_ADAPTERS[key]; }
function integratieStatus(it){ return INTEGRATIE_ADAPTERS[it.key]?"actief":it.status; }
const INTEGRATIES=[
  {key:"magister",naam:"Magister",categorie:"Schoolsystemen",status:"gepland",richting:"import/sync",slim:"leest rooster & resultaten in en stemt planning en niveau automatisch af"},
  {key:"somtoday",naam:"Somtoday",categorie:"Schoolsystemen",status:"gepland",richting:"import/sync",slim:"synchroniseert klassen, cijfers en rooster"},
  {key:"itslearning",naam:"itslearning",categorie:"Schoolsystemen",status:"gepland",richting:"sync",slim:"koppelt opdrachten en voortgang aan de leeromgeving"},
  {key:"moodle",naam:"Moodle",categorie:"Schoolsystemen",status:"gepland",richting:"sync",slim:"deelt challenges en resultaten met Moodle-cursussen"},
  {key:"canvas",naam:"Canvas",categorie:"Schoolsystemen",status:"gepland",richting:"sync",slim:"koppelt opdrachten en beoordelingen aan Canvas"},
  {key:"google-classroom",naam:"Google Classroom",categorie:"Schoolsystemen",status:"gepland",richting:"sync",slim:"wisselt opdrachten en klaslijsten uit"},
  {key:"ms-teams",naam:"Microsoft Teams / Entra",categorie:"Schoolsystemen",status:"beschikbaar",richting:"login/sync",slim:"Entra ID-login is al actief; klassen en opdrachten kunnen worden gesynchroniseerd"},
  {key:"pdf-export",naam:"PDF-export",categorie:"Portfolio & credentials",status:"actief",richting:"export",slim:"portfolio en rapporten worden nu al als PDF gegenereerd"},
  {key:"linkedin",naam:"LinkedIn",categorie:"Portfolio & credentials",status:"gepland",richting:"export",slim:"exporteert het talent-/competentieprofiel naar LinkedIn"},
  {key:"europass",naam:"Europass",categorie:"Portfolio & credentials",status:"gepland",richting:"export",slim:"zet het profiel om in een Europass-CV"},
  {key:"open-badges",naam:"Open Badges",categorie:"Portfolio & credentials",status:"gepland",richting:"export",slim:"zet verdiende prestaties om in verifieerbare Open Badges"},
  {key:"claude",naam:"Anthropic Claude",categorie:"AI-modellen (gateway)",status:"actief",richting:"gateway",slim:"huidige AI-laag; alle AI-calls lopen via de centrale gateway"},
  {key:"openai",naam:"OpenAI",categorie:"AI-modellen (gateway)",status:"beschikbaar",richting:"gateway",slim:"pluggable via de gateway — niet afhankelijk van één model"},
  {key:"gemini",naam:"Google Gemini",categorie:"AI-modellen (gateway)",status:"beschikbaar",richting:"gateway",slim:"selecteerbaar model achter de gateway"},
  {key:"mistral",naam:"Mistral",categorie:"AI-modellen (gateway)",status:"gepland",richting:"gateway",slim:"alternatief model via de gateway"},
  {key:"llama",naam:"Llama",categorie:"AI-modellen (gateway)",status:"gepland",richting:"gateway",slim:"open model-optie via de gateway"},
  {key:"google-agenda",naam:"Google Agenda",categorie:"Agenda",status:"gepland",richting:"sync",slim:"plant uitdagingen en deadlines automatisch in"},
  {key:"outlook",naam:"Outlook",categorie:"Agenda",status:"gepland",richting:"sync",slim:"synchroniseert planning met Outlook"},
  {key:"apple-agenda",naam:"Apple Agenda",categorie:"Agenda",status:"gepland",richting:"sync",slim:"synchroniseert planning met Apple Agenda"},
  {key:"garmin",naam:"Garmin",categorie:"Sport (met toestemming)",status:"gepland",richting:"import (opt-in)",slim:"koppelt herstel/belasting aan welzijnssignalen — alleen met toestemming",avg:true},
  {key:"polar",naam:"Polar",categorie:"Sport (met toestemming)",status:"gepland",richting:"import (opt-in)",slim:"belasting- en hersteldata voor welzijn — opt-in",avg:true},
  {key:"coros",naam:"Coros",categorie:"Sport (met toestemming)",status:"gepland",richting:"import (opt-in)",slim:"trainings- en hersteldata — opt-in",avg:true},
  {key:"strava",naam:"Strava",categorie:"Sport (met toestemming)",status:"gepland",richting:"import (opt-in)",slim:"activiteiten als context voor welzijn — opt-in",avg:true},
  {key:"apple-health",naam:"Apple Health",categorie:"Sport (met toestemming)",status:"gepland",richting:"import (opt-in)",slim:"gezondheids- en herstelsignalen — opt-in",avg:true},
  {key:"google-drive",naam:"Google Drive",categorie:"Documenten & opslag",status:"gepland",richting:"import/export",slim:"koppelt bewijs en eindproducten rechtstreeks"},
  {key:"onedrive",naam:"OneDrive",categorie:"Documenten & opslag",status:"gepland",richting:"import/export",slim:"bewijsbestanden importeren/exporteren"},
  {key:"dropbox",naam:"Dropbox",categorie:"Documenten & opslag",status:"gepland",richting:"import/export",slim:"bewijsbestanden importeren/exporteren"},
  {key:"canva",naam:"Canva",categorie:"Documenten & opslag",status:"gepland",richting:"import",slim:"creatieve eindproducten importeren als bewijs"},
];
const _INTEG_STATUS={actief:{label:"Actief",kleur:"#3E6633"},beschikbaar:{label:"Beschikbaar",kleur:"#5D87C5"},gepland:{label:"Gepland",kleur:"#7E8C77"}};
function IntegratiePaneel(){
  const cats=[...new Set(INTEGRATIES.map(i=>i.categorie))];
  const items=INTEGRATIES.map(i=>({...i,_status:integratieStatus(i)}));
  const actief=items.filter(i=>i._status==="actief").length;
  return (
    <div className="card" style={{padding:"20px 22px",marginBottom:18}}>
      <div style={{display:"flex",alignItems:"center",gap:8,flexWrap:"wrap"}}>
        <Icon name="layers" size={17}/><h3 style={{margin:0,fontSize:"1.1rem",fontWeight:800}}>Integraties</h3>
        <span className="muted" style={{fontSize:".8rem",marginLeft:"auto"}}>{actief} actief · {items.length} beschikbaar/gepland</span>
      </div>
      <p className="muted" style={{fontSize:".82rem",lineHeight:1.5,margin:"6px 0 14px"}}>Slimme, modulaire koppelingen: elke integratie beschrijft wat ze intelligent doet. Externe partners pluggen in via de adapter-registry; sport- en gezondheidsdata uitsluitend met toestemming (AVG).</p>
      <div style={{display:"grid",gap:16}}>
        {cats.map(cat=>(
          <div key={cat}>
            <div style={{fontSize:".78rem",fontWeight:800,textTransform:"uppercase",letterSpacing:".04em",color:"var(--grijs)",marginBottom:6}}>{cat}</div>
            <div style={{display:"grid",gap:8}}>
              {items.filter(i=>i.categorie===cat).map(i=>{const S=_INTEG_STATUS[i._status]||_INTEG_STATUS.gepland;return(
                <div key={i.key} style={{display:"flex",alignItems:"flex-start",gap:12,padding:"10px 12px",borderRadius:12,background:"#f9f9f9"}}>
                  <div style={{flex:1,minWidth:0}}>
                    <div style={{display:"flex",alignItems:"center",gap:8,flexWrap:"wrap"}}>
                      <b style={{fontSize:".92rem"}}>{i.naam}</b>
                      <span className="pill" style={{fontSize:".68rem",fontWeight:700,background:S.kleur+"1A",color:S.kleur}}>{S.label}</span>
                      <span className="muted" style={{fontSize:".72rem"}}>{i.richting}</span>
                      {i.avg&&<span className="pill" style={{fontSize:".66rem",background:"#F5F3EE",color:"#8A6D3B"}}>opt-in</span>}
                    </div>
                    <div className="muted" style={{fontSize:".8rem",lineHeight:1.45,marginTop:2}}>{i.slim}</div>
                  </div>
                </div>
              );})}
            </div>
          </div>
        ))}
      </div>
      <p className="muted" style={{fontSize:".72rem",lineHeight:1.4,marginTop:12}}>Uitbreidbaar zonder de kern te wijzigen: registreer een adapter via <code style={{fontFamily:"ui-monospace,Menlo,monospace"}}>registreerIntegratie(key, adapter)</code> en de status wordt automatisch 'Actief'. Gegevens blijven per school gescheiden; koppelingen vereisen toestemming en zijn intrekbaar.</p>
    </div>
  );
}
function SchoolDashboard({gebruiker,alle,mentorKlassen}){
  const [school,setSchool]=useState(null);
  const [laden,setLaden]=useState(true);
  const [nwKlas,setNwKlas]=useState("");
  const [nwKlasMentor,setNwKlasMentor]=useState("");
  const [nwMentor,setNwMentor]=useState("");
  const [gekopieerd,setGekopieerd]=useState(false);
  const [codeKopie,setCodeKopie]=useState("");

  useEffect(()=>{(async()=>{
    let s=null; try{s=await scholenStore.get(gebruiker.schoolcode);}catch{}
    if(!s)s={code:gebruiker.schoolcode||genSchoolcode(gebruiker.schoolnaam||"school"),naam:gebruiker.schoolnaam||"Mijn school",beheerder:{naam:gebruiker.naam},plan:"pro",klassen:[],mentoren:[],leerlingen:[],aangemaakt:new Date().toISOString()};
    let veranderd=false;
    if(!s.schoolId){s.schoolId=genSchoolId();veranderd=true;}
    if(!s.modules){s.modules={neo:true,pta:false,projects:false};veranderd=true;}
    if(!s.bewaartermijn){s.bewaartermijn="3 jaar";veranderd=true;}
    if(!s.status)s.status="actief";
    if(veranderd){try{await scholenStore.set(s);}catch{}}
    setSchool(s);setLaden(false);
  })();},[gebruiker.schoolcode]);

  const opslaan=async(next)=>{setSchool({...next});try{await scholenStore.set(next);}catch{}};
  const kopieer=()=>{try{if(navigator&&navigator.clipboard)navigator.clipboard.writeText(school.code);setGekopieerd(true);setTimeout(()=>setGekopieerd(false),1500);}catch{}};

  if(laden||!school)return <div className="card" style={{padding:24,marginTop:24}}>Schooldashboard laden…</div>;

  const leerlingen=school.leerlingen||[], klassen=school.klassen||[], mentoren=school.mentoren||[];
  const modules=school.modules||{neo:true,pta:false,projects:false};
  const toggleModule=(k)=>opslaan({...school,modules:{...modules,[k]:!modules[k]}});
  const bewaartermijn=school.bewaartermijn||"3 jaar";
  const schoolKlassen=(mentorKlassen||[]).filter(k=>k.schoolcode&&k.schoolcode===school.code);
  const kopieerCode=async(c)=>{try{if(navigator&&navigator.clipboard)await navigator.clipboard.writeText(c);setCodeKopie(c);setTimeout(()=>setCodeKopie(""),1500);}catch{}};
  const namen=new Set(leerlingen.map(l=>l.naam));
  const records=(alle||[]).filter(r=>r&&r.leerling&&namen.has(r.leerling.naam));
  const afRecords=records.filter(r=>r.afgerond);
  const totaalXP=records.reduce((s,r)=>s+(r.xp||0),0);
  const scores=afRecords.filter(r=>r.rubricScore!=null);
  const gemScore=scores.length?Math.round(scores.reduce((a,r)=>a+r.rubricScore,0)/scores.length):null;

  const perLeerling=leerlingen.map(l=>{
    const rs=records.filter(r=>r.leerling.naam===l.naam);
    return {...l,totaal:rs.length,afgerond:rs.filter(r=>r.afgerond).length,xp:rs.reduce((a,r)=>a+(r.xp||0),0)};
  });
  const klasNamen=[...new Set([...klassen.map(k=>k.naam),...leerlingen.map(l=>l.klas).filter(Boolean)])];
  const perKlas=klasNamen.map(naam=>{
    const ll=perLeerling.filter(l=>l.klas===naam);
    return {naam,mentor:(klassen.find(k=>k.naam===naam)||{}).mentor||"",aantal:ll.length,afgerond:ll.reduce((a,l)=>a+l.afgerond,0),xp:ll.reduce((a,l)=>a+l.xp,0)};
  });
  const perNiveau=afRecords.reduce((m,r)=>({...m,[r.niveau]:(m[r.niveau]||0)+1}),{});
  const themaTel=records.reduce((m,r)=>({...m,[r.thema]:(m[r.thema]||0)+1}),{});
  const topThema=Object.keys(themaTel).sort((a,b)=>themaTel[b]-themaTel[a])[0];
  const actiefsteKlas=[...perKlas].sort((a,b)=>b.afgerond-a.afgerond)[0];
  const afRatio=records.length?Math.round(afRecords.length/records.length*100):0;
  const niveauNL=n=>n==="Gold"?"Goud":n;

  const voegKlasToe=()=>{if(!nwKlas.trim())return;const next={...school,klassen:[...klassen,{id:nieuwId(),naam:nwKlas.trim(),mentor:nwKlasMentor||""}]};setNwKlas("");setNwKlasMentor("");opslaan(next);};
  const voegMentorToe=()=>{if(!nwMentor.trim())return;const next={...school,mentoren:[...mentoren,{id:nieuwId(),naam:nwMentor.trim()}]};setNwMentor("");opslaan(next);};
  const zetKlasMentor=(kid,mentor)=>{opslaan({...school,klassen:klassen.map(k=>k.id===kid?{...k,mentor}:k)});};
  const zetLeerling=(naam,patch)=>{opslaan({...school,leerlingen:leerlingen.map(l=>l.naam===naam?{...l,...patch}:l)});};

  const Stat=({icon,label,waarde,sub})=>(
    <div className="card" style={{padding:"18px 20px"}}>
      <div style={{display:"flex",alignItems:"center",gap:8,color:"var(--accent)"}}><Icon name={icon} size={18}/><span className="eyebrow" style={{margin:0}}>{label}</span></div>
      <div style={{fontSize:"1.8rem",fontWeight:800,marginTop:6,lineHeight:1}}>{waarde}</div>
      {sub&&<div className="muted" style={{fontSize:".8rem",marginTop:4}}>{sub}</div>}
    </div>
  );
  const veldStyle={padding:"8px 10px",borderRadius:8,border:"1.5px solid var(--lijn)",fontSize:".84rem",background:"#fff"};

  return(
    <div className="in" style={{paddingTop:20}}>
      {/* Kop met schoolcode */}
      <div className="card" style={{padding:"24px 24px",marginBottom:18,display:"flex",flexWrap:"wrap",alignItems:"center",justifyContent:"space-between",gap:16}}>
        <div>
          <div style={{display:"flex",alignItems:"center",gap:10}}>
            <span style={{color:"var(--accent)"}}><Icon name="school" size={24}/></span>
            <h2 className="h2" style={{margin:0}}>{school.naam}</h2>
            <span className="pill" style={{background:"var(--accent)",color:"#fff",fontWeight:800}}>Pro · Schoollicentie</span>
          </div>
          <p className="muted" style={{margin:"8px 0 0",fontSize:".9rem"}}>Schoolbeheerder: {(school.beheerder&&school.beheerder.naam)||gebruiker.naam} · centraal gefactureerd, leerlingen betalen niets.</p>
        </div>
        <div style={{textAlign:"right"}}>
          <div className="muted" style={{fontSize:".74rem",textTransform:"uppercase",letterSpacing:".05em",marginBottom:4}}>Schoolcode</div>
          <button onClick={kopieer} className="btn btn-licht" style={{fontFamily:"monospace",fontWeight:800,fontSize:".95rem"}}>{school.code} {gekopieerd?"✓":"⧉"}</button>
          <div className="muted" style={{fontSize:".74rem",marginTop:6,maxWidth:240}}>Deel deze code met leerlingen; ze koppelen kosteloos.</div>
          {school.domein&&<div className="muted" style={{fontSize:".74rem",marginTop:6}}>Licentie gekoppeld aan domein <b>@{school.domein}</b></div>}
        </div>
      </div>

      {/* Klassen & klascodes (aangemaakt door mentoren) */}
      <div className="card" style={{padding:"20px 22px",marginBottom:18}}>
        <div style={{display:"flex",alignItems:"baseline",justifyContent:"space-between",gap:10,flexWrap:"wrap"}}>
          <h3 style={{margin:"0 0 4px",fontSize:"1.1rem",fontWeight:800}}>Klassen &amp; klascodes</h3>
          <span className="muted" style={{fontSize:".82rem"}}>{schoolKlassen.length} klas{schoolKlassen.length===1?"":"sen"} · leerlingen koppelen zich met de klascode</span>
        </div>
        {schoolKlassen.length===0?(
          <p className="muted" style={{fontSize:".9rem",margin:"8px 0 0"}}>Nog geen klassen aangemaakt. Mentoren maken klassen aan in hun eigen omgeving; de klascodes verschijnen hier automatisch.</p>
        ):(
          <div style={{display:"grid",gap:8,marginTop:10}}>
            {schoolKlassen.map(k=>(
              <div key={k.id} style={{display:"flex",alignItems:"center",gap:12,padding:"10px 14px",borderRadius:12,background:"#f9f9f9",flexWrap:"wrap"}}>
                <span style={{fontWeight:800,minWidth:60}}>{k.naam}</span>
                <span className="muted" style={{fontSize:".82rem",flex:1,minWidth:120}}>{(k.leerlingen||[]).length} leerling(en){k.mentor?` · mentor ${k.mentor}`:""}</span>
                <button onClick={()=>kopieerCode(k.code)} className="btn btn-licht" style={{fontFamily:"ui-monospace,Menlo,monospace",fontWeight:800,letterSpacing:".05em",fontSize:".85rem"}}>{k.code||"—"} {codeKopie===k.code?"✓":"⧉"}</button>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* Modules & Trust Center */}
      <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(300px,1fr))",gap:16,marginBottom:18}}>
        <div className="card" style={{padding:"20px 22px"}}>
          <h3 style={{margin:"0 0 4px",fontSize:"1.1rem",fontWeight:800}}>Modules</h3>
          <p className="muted" style={{fontSize:".82rem",margin:"0 0 12px"}}>Activeer Unfold-modules voor je school. Eén Microsoft-login geeft toegang tot alle actieve modules.</p>
          <div style={{display:"grid",gap:8}}>
            {[["neo","Unfold Neo","Persoonlijke ontwikkeling & talentcoaching"],["pta","PTA Vergelijker","PTA-analyse bij overstap"],["projects","Unfold Projects","Begeleiding van school­projecten"]].map(([k,naam,oms])=>(
              <div key={k} style={{display:"flex",alignItems:"center",justifyContent:"space-between",gap:12,padding:"10px 12px",borderRadius:12,background:"#f9f9f9"}}>
                <div><div style={{fontWeight:700,fontSize:".92rem"}}>{naam}</div><div className="muted" style={{fontSize:".78rem"}}>{oms}</div></div>
                <button onClick={()=>toggleModule(k)} aria-label={modules[k]?"Actief":"Inactief"} style={{width:46,height:26,borderRadius:20,background:modules[k]?"var(--accent)":"#CFCFCF",position:"relative",transition:"background .15s",flexShrink:0}}>
                  <span style={{position:"absolute",top:3,left:modules[k]?23:3,width:20,height:20,borderRadius:"50%",background:"#fff",transition:"left .15s"}}/>
                </button>
              </div>
            ))}
          </div>
        </div>
        <div className="card" style={{padding:"20px 22px"}}>
          <div style={{display:"flex",alignItems:"center",gap:8}}><Icon name="lock" size={17}/><h3 style={{margin:0,fontSize:"1.1rem",fontWeight:800}}>Trust Center</h3></div>
          <div style={{display:"grid",gap:8,marginTop:12,fontSize:".88rem"}}>
            <div style={{display:"flex",justifyContent:"space-between",gap:10}}><span className="muted">School-ID</span><b>{school.schoolId||"—"}</b></div>
            <div style={{display:"flex",justifyContent:"space-between",gap:10}}><span className="muted">Status</span><b style={{color:"var(--accent-diep)"}}>{(school.status||"actief")==="actief"?"Actief":school.status}</b></div>
            <div style={{display:"flex",justifyContent:"space-between",gap:10}}><span className="muted">Authenticatie</span><b>Microsoft Entra ID (OAuth)</b></div>
            <div style={{display:"flex",justifyContent:"space-between",gap:10}}><span className="muted">Versleuteling</span><b>AES-256 · TLS</b></div>
            <div style={{display:"flex",justifyContent:"space-between",gap:10,alignItems:"center"}}><span className="muted">Bewaartermijn</span>
              <select value={bewaartermijn} onChange={e=>opslaan({...school,bewaartermijn:e.target.value})} style={{padding:"6px 8px",borderRadius:8,border:"1.5px solid var(--lijn)",fontSize:".82rem",background:"#fff",fontWeight:700}}>
                {["1 jaar","2 jaar","3 jaar","5 jaar"].map(v=><option key={v} value={v}>{v}</option>)}
              </select>
            </div>
          </div>
          <p className="muted" style={{fontSize:".78rem",margin:"12px 0 0",lineHeight:1.5}}>Privacy by Design &amp; Default · AVG-proof · Least Privilege · leerlingen behouden recht op inzage, correctie, dataportabiliteit en verwijdering. Gegevens van jouw school zijn logisch gescheiden en worden nooit gedeeld met andere scholen of verkocht.</p>
        </div>
        <div className="card" style={{padding:"20px 22px"}}>
          <div style={{display:"flex",alignItems:"center",gap:8}}><Icon name="cap" size={17}/><h3 style={{margin:0,fontSize:"1.1rem",fontWeight:800}}>Didactische instellingen</h3></div>
          <div style={{display:"flex",justifyContent:"space-between",gap:12,alignItems:"flex-start",marginTop:14}}>
            <div style={{flex:1}}>
              <b style={{fontSize:".9rem"}}>Leerlingen mogen zelf Project- en Master Challenges kiezen</b>
              <p className="muted" style={{fontSize:".8rem",margin:"4px 0 0",lineHeight:1.5}}>Staat dit uit, dan kiezen leerlingen alleen Micro/Core/Deep of de AI-aanbeveling. Mentoren en docenten kunnen altijd elk type toewijzen. De AI kan meerdaagse projecten sowieso automatisch voorstellen.</p>
            </div>
            <button onClick={()=>opslaan({...school,projectenVoorLeerlingen:!school.projectenVoorLeerlingen})}
              aria-label="Aan/uit"
              style={{flexShrink:0,width:48,height:28,borderRadius:999,border:"none",cursor:"pointer",position:"relative",transition:"background .2s",
                background:school.projectenVoorLeerlingen?"var(--accent)":"#CBD0D6"}}>
              <span style={{position:"absolute",top:3,left:school.projectenVoorLeerlingen?23:3,width:22,height:22,borderRadius:"50%",background:"#fff",transition:"left .2s",boxShadow:"0 1px 3px rgba(0,0,0,.2)"}}/>
            </button>
          </div>
        </div>
      </div>

      {/* Integration Intelligence — slimme, modulaire koppelingen */}
      <IntegratiePaneel/>

      {/* Statcards */}
      <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(150px,1fr))",gap:12,marginBottom:18}}>
        <Stat icon="check" label="Actieve leerlingen" waarde={leerlingen.length} sub={`${perLeerling.filter(l=>l.totaal>0).length} actief bezig`}/>
        <Stat icon="school" label="Klassen" waarde={klasNamen.length}/>
        <Stat icon="coach" label="Mentoren" waarde={mentoren.length}/>
        <Stat icon="target" label="Uitdagingen" waarde={records.length} sub={`${afRecords.length} afgerond`}/>
      </div>

      {/* Voortgang per klas */}
      <div className="card" style={{padding:"20px 22px",marginBottom:18}}>
        <h3 style={{margin:"0 0 12px",fontSize:"1.1rem",fontWeight:800}}>Voortgang per klas</h3>
        {perKlas.length===0?<p className="muted" style={{fontSize:".9rem"}}>Nog geen klassen of leerlingen gekoppeld.</p>:(
          <div style={{display:"grid",gap:8}}>
            {perKlas.map(k=>(
              <div key={k.naam} style={{display:"flex",alignItems:"center",gap:12,padding:"10px 14px",borderRadius:12,background:"#f9f9f9"}}>
                <span style={{fontWeight:800,minWidth:60}}>{k.naam}</span>
                <span className="muted" style={{fontSize:".82rem",flex:1}}>{k.aantal} leerling(en){k.mentor?` · mentor ${k.mentor}`:""}</span>
                <span style={{fontSize:".84rem",fontWeight:700}}>{k.afgerond} afgerond</span>
                <span className="pill" style={{background:"var(--accent-zacht)",color:"var(--accent-diep)"}}>{k.xp} XP</span>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* Voortgang per leerling */}
      <div className="card" style={{padding:"20px 22px",marginBottom:18}}>
        <h3 style={{margin:"0 0 12px",fontSize:"1.1rem",fontWeight:800}}>Voortgang per leerling</h3>
        {perLeerling.length===0?<p className="muted" style={{fontSize:".9rem"}}>Nog geen leerlingen. Deel de schoolcode <b>{school.code}</b> zodat leerlingen zich koppelen.</p>:(
          <div style={{display:"grid",gap:8}}>
            {perLeerling.map(l=>(
              <div key={l.naam} style={{display:"flex",flexWrap:"wrap",alignItems:"center",gap:10,padding:"10px 14px",borderRadius:12,background:"#f9f9f9"}}>
                <span style={{fontWeight:700,minWidth:120}}>{l.naam}</span>
                <select value={l.klas||""} onChange={e=>zetLeerling(l.naam,{klas:e.target.value})} style={veldStyle}>
                  <option value="">— klas —</option>
                  {klasNamen.map(kn=><option key={kn} value={kn}>{kn}</option>)}
                </select>
                <select value={l.mentor||""} onChange={e=>zetLeerling(l.naam,{mentor:e.target.value})} style={veldStyle}>
                  <option value="">— mentor —</option>
                  {mentoren.map(m=><option key={m.id} value={m.naam}>{m.naam}</option>)}
                </select>
                <span style={{flex:1}}/>
                <span style={{fontSize:".82rem",fontWeight:700}}>{l.afgerond}/{l.totaal} afgerond</span>
                <span className="pill" style={{background:"var(--accent-zacht)",color:"var(--accent-diep)"}}>{l.xp} XP</span>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* Rapportages + AI-analyses */}
      <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(280px,1fr))",gap:16,marginBottom:18}}>
        <div className="card" style={{padding:"20px 22px"}}>
          <h3 style={{margin:"0 0 12px",fontSize:"1.1rem",fontWeight:800}}>Rapportages</h3>
          <div style={{display:"grid",gap:8,fontSize:".9rem"}}>
            <div style={{display:"flex",justifyContent:"space-between"}}><span className="muted">Afgeronde uitdagingen</span><b>{afRecords.length}</b></div>
            <div style={{display:"flex",justifyContent:"space-between"}}><span className="muted">Totaal verdiende XP</span><b>{totaalXP}</b></div>
            <div style={{display:"flex",justifyContent:"space-between"}}><span className="muted">Gemiddelde reflectiescore</span><b>{gemScore!=null?gemScore+"%":"—"}</b></div>
            <div style={{display:"flex",justifyContent:"space-between"}}><span className="muted">Afrondingsratio</span><b>{afRatio}%</b></div>
            <div style={{borderTop:"1px solid var(--lijn)",paddingTop:8,marginTop:2}}>
              <div className="muted" style={{fontSize:".8rem",marginBottom:6}}>Per niveau afgerond</div>
              <div style={{display:"flex",flexWrap:"wrap",gap:6}}>
                {["Bronze","Silver","Gold","Platinum"].map(n=>(<span key={n} className="pill" style={{background:"#f1f1f1",color:"var(--inkt)"}}>{niveauNL(n)}: {perNiveau[n]||0}</span>))}
              </div>
            </div>
          </div>
          <button className="btn btn-licht" style={{marginTop:14,fontSize:".85rem"}} disabled>PDF-export (binnenkort)</button>
        </div>
        <div className="card" style={{padding:"20px 22px"}}>
          <div style={{display:"flex",alignItems:"center",gap:8,marginBottom:12}}><span style={{color:"var(--accent)"}}><Icon name="sparkles" size={18}/></span><h3 style={{margin:0,fontSize:"1.1rem",fontWeight:800}}>AI-analyses</h3></div>
          {records.length===0?<p className="muted" style={{fontSize:".9rem"}}>Zodra leerlingen uitdagingen maken, verschijnen hier automatische inzichten en trends.</p>:(
            <ul style={{margin:0,paddingLeft:18,lineHeight:1.6,fontSize:".9rem"}}>
              <li>Schoolbreed is {afRatio}% van de gestarte uitdagingen afgerond{afRatio>=70?" — sterke betrokkenheid.":afRatio>=40?" — gezonde betrokkenheid.":" — hier valt nog groei te halen."}</li>
              {actiefsteKlas&&actiefsteKlas.afgerond>0&&<li>Meest actieve klas: <b>{actiefsteKlas.naam}</b> met {actiefsteKlas.afgerond} afgeronde uitdagingen.</li>}
              {topThema&&<li>Populairste thema: <b>{themaLabel(topThema)}</b>. Overweeg dit schoolbreed te verbinden aan begeleiding.</li>}
              {gemScore!=null&&<li>Gemiddelde reflectiescore is {gemScore}%{gemScore>=70?"; leerlingen schatten zichzelf op niveau in.":"; stimuleer eerlijke, opbouwende reflectie."}</li>}
              <li>{perLeerling.filter(l=>l.totaal===0).length} leerling(en) zijn nog niet gestart — een gerichte herinnering kan helpen.</li>
            </ul>
          )}
        </div>
      </div>

      {/* Beheer: klassen & mentoren */}
      <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(280px,1fr))",gap:16}}>
        <div className="card" style={{padding:"20px 22px"}}>
          <h3 style={{margin:"0 0 12px",fontSize:"1.1rem",fontWeight:800}}>Klassen beheren</h3>
          <div style={{display:"grid",gap:8,marginBottom:14}}>
            {klassen.length===0&&<p className="muted" style={{fontSize:".88rem",margin:0}}>Nog geen klassen aangemaakt.</p>}
            {klassen.map(k=>(
              <div key={k.id} style={{display:"flex",alignItems:"center",gap:10,padding:"8px 12px",borderRadius:10,background:"#f9f9f9"}}>
                <span style={{fontWeight:700,minWidth:54}}>{k.naam}</span>
                <select value={k.mentor||""} onChange={e=>zetKlasMentor(k.id,e.target.value)} style={{...veldStyle,flex:1}}>
                  <option value="">— koppel mentor —</option>
                  {mentoren.map(m=><option key={m.id} value={m.naam}>{m.naam}</option>)}
                </select>
              </div>
            ))}
          </div>
          <div style={{display:"flex",gap:8}}>
            <input className="field" value={nwKlas} onChange={e=>setNwKlas(e.target.value)} placeholder="Nieuwe klas (bv. H4b)" style={{flex:1}}/>
            <button className="btn btn-accent" style={{flex:"0 0 auto",width:"auto",paddingLeft:"1.2rem",paddingRight:"1.2rem"}} onClick={voegKlasToe}>+ Klas</button>
          </div>
        </div>
        <div className="card" style={{padding:"20px 22px"}}>
          <h3 style={{margin:"0 0 12px",fontSize:"1.1rem",fontWeight:800}}>Mentoren beheren</h3>
          <div style={{display:"grid",gap:8,marginBottom:14}}>
            {mentoren.length===0&&<p className="muted" style={{fontSize:".88rem",margin:0}}>Nog geen mentoren toegevoegd.</p>}
            {mentoren.map(m=>(
              <div key={m.id} style={{display:"flex",alignItems:"center",gap:10,padding:"8px 12px",borderRadius:10,background:"#f9f9f9"}}>
                <span style={{color:"var(--accent)"}}><Icon name="coach" size={16}/></span>
                <span style={{fontWeight:700,flex:1}}>{m.naam}</span>
                <span className="muted" style={{fontSize:".8rem"}}>{klassen.filter(k=>k.mentor===m.naam).length} klas(sen)</span>
              </div>
            ))}
          </div>
          <div style={{display:"flex",gap:8}}>
            <input className="field" value={nwMentor} onChange={e=>setNwMentor(e.target.value)} placeholder="Naam mentor/docent" style={{flex:1}}/>
            <button className="btn btn-accent" style={{flex:"0 0 auto",width:"auto",paddingLeft:"1.2rem",paddingRight:"1.2rem"}} onClick={voegMentorToe}>+ Mentor</button>
          </div>
        </div>
      </div>
    </div>
  );
}

/* ════════════════ BEGELEIDINGSROUTES ════════════════ */
const ROUTE_FOTOS={groei:"data:image/jpeg;base64,",topsport:"data:image/jpeg;base64,",talent:"data:image/jpeg;base64,"};

const ROUTES = {
  groei:    {key:"groei",   naam:"Persoonlijke groei", profiel:"Groeiprofiel",    emoji:"🌱", icon:"cap",  accent:"#7E8C77", diep:"#5C6857", zacht:"#E9EDE7",
             sub:"Voor alle leerlingen die willen groeien in studie, planning, motivatie en persoonlijke ontwikkeling."},
  topsport: {key:"topsport",naam:"Topsport & school",  profiel:"Prestatieprofiel", emoji:"🏀", icon:"run",  accent:"#E87722", diep:"#C9621A", zacht:"#FBEFE6",
             sub:"Voor leerlingen die school combineren met intensieve sport en alles uit zichzelf willen halen."},
  talent:   {key:"talent",  naam:"Talent & ambitie",   profiel:"Talentenprofiel",  emoji:"⭐", icon:"star", accent:"#AEA38B", diep:"#7F735A", zacht:"#F1ECE4",
             sub:"Voor leerlingen die school combineren met een intensieve passie of talent: muziek, dans, kunst, theater, schrijven, fotografie, film, media, ondernemen, techniek, content maken, e-sports, koken, mode, design of iets anders."},
};

/* ──────────── ONTWIKKELPADEN (onder de motorkap gekoppeld aan thema's/subthema's) ────────────
   De leerling ziet doelgerichte paden ("Word zelfverzekerder"), nooit losse thema's of scores.
   Elk pad wijst intern naar een bestaand thema + subthema's waarmee de uitdaging wordt opgebouwd. */
const ONTWIKKELPADEN = {
  groei:[
    {key:"zelfverzekerder",emoji:"🌱",icon:"spark",label:"Word zelfverzekerder",beschrijving:"Meer geloven in jezelf en durven laten zien wat je kunt.",thema:"mentaal",subs:["zelfvertrouwen","assertiviteit","positief zelfbeeld"]},
    {key:"betereleerling",emoji:"🎯",icon:"book",label:"Word een betere leerling",beschrijving:"Slimmer leren, beter concentreren en meer uit school halen.",thema:"studie",subs:["studievaardigheden","concentratie","leren leren"]},
    {key:"gripopjedag",emoji:"⚡",icon:"bolt",label:"Krijg meer grip op je dag",beschrijving:"Beter plannen, handige gewoontes en rust in je hoofd.",thema:"ef",subs:["planning","gewoontes","prioriteiten"]},
    {key:"injevel",emoji:"😊",icon:"smile",label:"Voel je beter in je vel",beschrijving:"Minder stress, meer veerkracht en lekkerder in je vel.",thema:"weerbaarheid",subs:["stress hanteren","welzijn","veerkracht"]},
    {key:"contact",emoji:"🤝",icon:"users",label:"Sterker in contact met anderen",beschrijving:"Helder communiceren, samenwerken en omgaan met feedback.",thema:"socialmedia",subs:["communicatie","feedback geven en ontvangen","samenwerken"]},
    {key:"ontdek",emoji:"💡",icon:"compass",label:"Ontdek wie je bent",beschrijving:"Je waarden, talenten en wat jou echt drijft leren kennen.",thema:"mentaal",subs:["kernwaarden","identiteit","zelfkennis"]},
    {key:"toekomst",emoji:"🚀",icon:"rocket",label:"Bouw aan jouw toekomst",beschrijving:"Ontdekken wat bij je past en stappen zetten richting later.",thema:"studie",subs:["studiekeuze","loopbaanoriëntatie","doelen stellen"]},
  ],
  topsport:[
    {key:"onderdruk",emoji:"🏆",icon:"target",label:"Presteer onder druk",beschrijving:"Scherp blijven en je beste niveau halen op het juiste moment.",thema:"mentaal",subs:["presteren onder druk","wedstrijdspanning","focus"]},
    {key:"balans",emoji:"⚖️",icon:"balance",label:"Vind balans tussen sport en school",beschrijving:"School, sport en herstel slim op elkaar afstemmen.",thema:"duaal",subs:["balans school-sport","planning","herstel"]},
    {key:"mentaalsterk",emoji:"🔥",icon:"shield",label:"Word mentaal sterker",beschrijving:"Veerkrachtig omgaan met tegenslag en verwachtingen.",thema:"weerbaarheid",subs:["mentale weerbaarheid","veerkracht","omgaan met tegenslag"]},
    {key:"discipline",emoji:"💪",icon:"flame",label:"Bouw duurzame discipline",beschrijving:"Sterke gewoontes die je vol blijft houden.",thema:"ef",subs:["discipline","gewoontes","doorzetten"]},
    {key:"sportdoelen",emoji:"🎯",icon:"target",label:"Bereik jouw sportdoelen",beschrijving:"Heldere doelen stellen en er gericht naartoe werken.",thema:"mentaal",subs:["doelen stellen","motivatie","doorzettingsvermogen"]},
    {key:"trainslim",emoji:"🧠",icon:"dumbbell",label:"Train als een topsporter",beschrijving:"Slimmer trainen met gerichte oefening en herstel.",thema:"kracht",subs:["trainingsopbouw","gericht oefenen","herstel"]},
    {key:"herstel",emoji:"😴",icon:"moon",label:"Verbeter herstel en energie",beschrijving:"Beter herstellen, slapen en je energie verdelen.",thema:"voeding",subs:["herstel","slaap","energie"]},
    {key:"studieslim",emoji:"📚",icon:"book",label:"Combineer studie en topsport slimmer",beschrijving:"Studeren en sporten beter laten samengaan.",thema:"duaal",subs:["studie en sport combineren","planning","executieve functies"]},
    {key:"teamspeler",emoji:"🤝",icon:"users",label:"Groei als teamspeler",beschrijving:"Je rol pakken, samenwerken en je team versterken.",thema:"leiderschap",subs:["teamrol","samenwerken","communicatie"]},
    {key:"leiderschap",emoji:"👑",icon:"crown",label:"Ontwikkel leiderschap",beschrijving:"Voorop gaan, verantwoordelijkheid nemen en anderen meenemen.",thema:"leiderschap",subs:["leiderschap","verantwoordelijkheid","voorbeeldgedrag"]},
  ],
  talent:[
    {key:"creatief",emoji:"🎨",icon:"brush",label:"Ontwikkel je creatieve talent",beschrijving:"Je creativiteit verdiepen en gericht beter worden.",thema:"mentaal",subs:["creativiteit","talent ontwikkelen","gericht oefenen"]},
    {key:"project",emoji:"🚀",icon:"rocket",label:"Bouw jouw eigen project",beschrijving:"Een eigen idee stap voor stap tot iets echts maken.",thema:"ef",subs:["projectmatig werken","planning","doorzetten"]},
    {key:"ondernemender",emoji:"💼",icon:"briefcase",label:"Word ondernemender",beschrijving:"Kansen zien, initiatief nemen en ideeën uitvoeren.",thema:"leiderschap",subs:["ondernemerschap","initiatief","kansen zien"]},
    {key:"creator",emoji:"🎥",icon:"video",label:"Groei als creator",beschrijving:"Content maken, je verhaal vertellen en publiek bereiken.",thema:"socialmedia",subs:["content maken","online communicatie","persoonlijk merk"]},
    {key:"artistiek",emoji:"🎼",icon:"music",label:"Ontwikkel jouw artistieke talent",beschrijving:"Je kunst of podiumtalent naar een hoger niveau brengen.",thema:"mentaal",subs:["artistiek talent","oefenen","optreden"]},
    {key:"techniek",emoji:"💻",icon:"code",label:"Ontdek technologie en AI",beschrijving:"Nieuwsgierig technologie verkennen en toepassen.",thema:"studie",subs:["technologie","probleemoplossend denken","leren leren"]},
    {key:"impact",emoji:"🌍",icon:"globe",label:"Maak impact",beschrijving:"Met je talent iets betekenen voor anderen of de wereld.",thema:"leiderschap",subs:["impact maken","waarden","samenwerken"]},
    {key:"merk",emoji:"⭐",icon:"star",label:"Bouw aan jouw persoonlijke merk",beschrijving:"Laten zien wie je bent en waar je voor staat.",thema:"socialmedia",subs:["persoonlijk merk","communicatie","netwerken"]},
    {key:"presenteren",emoji:"🎤",icon:"mic",label:"Presenteer met zelfvertrouwen",beschrijving:"Jezelf en je werk overtuigend kunnen presenteren.",thema:"leiderschap",subs:["presenteren","zelfvertrouwen","overtuigen"]},
    {key:"professional",emoji:"🏗️",icon:"briefcase",label:"Werk als een professional",beschrijving:"Met werkethiek en focus dingen echt afmaken.",thema:"ef",subs:["werkethiek","projectmatig werken","discipline"]},
  ],
};
// Verborgen analysevariabelen per route (de AI weegt deze; de leerling ziet ze nooit).
const ANALYSE_VARIABELEN = {
  groei:["motivatie","executieve functies","veerkracht","stress","zelfvertrouwen","focus","doorzettingsvermogen","zelfreflectie","zelfregie","communicatie","creativiteit","samenwerken","zelfbeeld","discipline","autonomie","growth mindset","intrinsieke motivatie","welzijn","studiehouding","waarden","interesses","leerstijl","feedbackvoorkeur"],
  topsport:["trainingsbelasting","wedstrijdbelasting","herstelvermogen","balans school-sport","slaapkwaliteit","energie","stressniveau","mentale weerbaarheid","wedstrijdspanning","concentratie","coachrelatie","ouderondersteuning","zelfvertrouwen","doelgerichtheid","doorzettingsvermogen","grit","leiderschap","teamrol","communicatie","feedbackgevoeligheid","studiedruk","executieve functies","leefstijl","herstelgewoonten","zelfregie","intrinsieke motivatie"],
  talent:["creativiteit","innovatief denken","nieuwsgierigheid","ondernemerschap","artistieke voorkeur","technische interesse","leiderschap","doorzettingsvermogen","persoonlijk merk","netwerken","zelfvertrouwen","focus","gericht oefenen","ambitie","autonomie","werkethiek","projectmatig werken","communicatie","presentatievaardigheden","probleemoplossend vermogen"],
};
function padViaKey(route,key){return (ONTWIKKELPADEN[route]||[]).find(p=>p.key===key);}

// ── Dynamische ontwikkelpaden: scores die meebewegen met afgeronde uitdagingen en check-ins ──
function bouwPadScores(route,aanbevolenKeys){
  const alle=ONTWIKKELPADEN[route]||[];
  const scores={};
  alle.forEach(p=>{scores[p.key]=1;});
  (aanbevolenKeys||[]).forEach((k,i)=>{ if(scores[k]!=null) scores[k]+=Math.max(3-i,1)+2; });
  return scores;
}
function topPaden(route,padScores,niveau){
  const alle=ONTWIKKELPADEN[route]||[];
  return [...alle].sort((a,b)=>(padScores[b.key]||0)-(padScores[a.key]||0)).slice(0,3).map(p=>({...p,niveau:niveau||"Silver"}));
}
function herberekenPaden(profiel){
  const ps=profiel.padScores||{};
  return {...profiel,paden:topPaden(profiel.route,ps,profiel.aanbevolenNiveau)};
}
// Na een afgeronde uitdaging: thema gehaald -> pad rustig laten uitrotteren (beheerst), niet gehaald -> prioriteit houden.
function werkPadenBijNaUitdaging(profiel,rec){
  if(!profiel||!profiel.route||!rec)return profiel;
  const route=profiel.route;
  const alle=ONTWIKKELPADEN[route]||[];
  const ps={...(profiel.padScores||bouwPadScores(route,profiel.aanbevolenPaden))};
  const grens=(niveauInfo(rec.niveau).grens)||65;
  const behaald=rec.rubricScore!=null&&rec.rubricScore>=grens;
  alle.filter(p=>p.thema===rec.thema).forEach(p=>{
    ps[p.key]=Math.max(0,(ps[p.key]||1)+(behaald?-0.9:0.6));
  });
  const log=[...(profiel.padLog||[]),{type:"uitdaging",thema:rec.thema,niveau:rec.niveau,score:rec.rubricScore??null,datum:new Date().toISOString()}].slice(-40);
  return herberekenPaden({...profiel,padScores:ps,padLog:log});
}
// Wekelijkse check-in: antwoorden verhogen de prioriteit van paden die de leerling noemt.
function werkPadenBijNaCheckin(profiel,antwoorden){
  if(!profiel||!profiel.route)return profiel;
  const route=profiel.route;
  const alle=ONTWIKKELPADEN[route]||[];
  const ps={...(profiel.padScores||bouwPadScores(route,profiel.aanbevolenPaden))};
  const zoek=Object.values(antwoorden||{}).join(" ").toLowerCase();
  alle.forEach(p=>{
    const tekst=(p.label+" "+p.beschrijving+" "+p.subs.join(" ")).toLowerCase();
    const hit=tekst.split(/\s+/).reduce((s,w)=>s+(w.length>3&&zoek.includes(w)?1:0),0);
    if(hit>0)ps[p.key]=(ps[p.key]||1)+hit*0.8;
  });
  const checkins=[...(profiel.checkins||[]),{datum:new Date().toISOString(),antwoorden}].slice(-20);
  return herberekenPaden({...profiel,padScores:ps,checkins,laatsteCheckin:new Date().toISOString()});
}
